create temporary table import_summary (wikidata_id text primary key, summary text not null, source text not null);

insert into import_summary (wikidata_id, summary, source) values
  ('Q39054028', 'RC de Go! est un jeu de course de voitures radiocommandées développé par Taito. Il est d''abord sorti dans les salles d''arcades Japonaises, sur le système G-NET de Taito. Le jeu a ensuite été porté sur PlayStation, sa distribution étant assurée en Europe et en Amérique du Nord par Acclaim Entertainment. Il a connu des notes généralement positives a sa sortie par la presse spécialisée, la comparant a RC Pro-Am.', 'https://fr.wikipedia.org/wiki/RC_de_GO!'),
  ('Q1571488', 'Déjà Vu est un jeu vidéo d''aventure développé par ICOM Simulations et édité par Mindscape, sorti à partir de 1985 sur Apple IIGS, Mac OS, Atari ST, Commodore 64, Amiga, DOS, Game Boy Color, Pocket PC (Windows Mobile) et NES.

Il a pour suite Déjà Vu II: Lost in Las Vegas.', 'https://fr.wikipedia.org/wiki/D%C3%A9j%C3%A0_Vu_(jeu_vid%C3%A9o)'),
  ('Q1567550', 'Joust est un jeu vidéo créé par la société américaine Williams Electronics, sorti en 1982 sur borne d''arcade.

Joust est un classique du jeu d''arcade. C''est un jeu d''action qui met en scène des joutes à dos d''oiseau dans un univers médiéval fantaisiste. Il introduit un mode deux joueurs jouable à la fois en coopération et en compétition. Il a été adapté sur de nombreuses systèmes familiaux, et a eu une suite, Joust 2: Survival of the Fittest, en 1986.', 'https://fr.wikipedia.org/wiki/Joust'),
  ('Q1535509', 'Rampart est un jeu vidéo de stratégie développé et édité par Atari Games, sorti en 1990 sur borne d''arcade. Il a été adapté sur divers supports familiaux: micro-ordinateurs (Amiga, Atari ST, Commodore 64, DOS) et consoles (Master System, Mega Drive, NES, Super Nintendo, Lynx et Game Boy).

Midway Games a réédité le jeu sur Game Boy Color (1999), sur GameCube, PlayStation 2, PlayStation Portable, Windows et Xbox via les compilations Midway Arcade Treasures (2003), sur Game Boy Advance en pack avec Gauntlet (2005) et sur PlayStation 3 via le PlayStation Network (2007). Cette derrière version implémente un mode de jeu en ligne jouable à trois.', 'https://fr.wikipedia.org/wiki/Rampart'),
  ('Q1565343', 'Q*bert est un jeu vidéo d''action/réflexion édité sur borne d''arcade par Gottlieb en 1982. Conçu par Warren Davis et Jeff Lee, Q*bert est devenu un classique du jeu d''arcade et a été porté sur de nombreux micro-ordinateurs personnels.', 'https://fr.wikipedia.org/wiki/Q*bert'),
  ('Q1648866', 'The Bugs Bunny Blowout, connu au Japon et sur l''écran titre sous le nom de Happy Birthday Bugs et en Amérique du Nord sous le nom de The Bugs Bunny Birthday Blowout, est un jeu vidéo de plates-formes développé par Kemco en 1990 sur Nintendo Entertainment System.', 'https://fr.wikipedia.org/wiki/The_Bugs_Bunny_Blowout'),
  ('Q1618401', 'King''s Quest V: Absence Make the Heart Go Yonder! (traduction littérale « L''absence fait chavirer le cœur ») est le cinquième volet de la série de jeux vidéo King''s Quest, sorti sur PC en 1990 et adapté par la suite sur Amiga, Macintosh, FM-Towns et NES.', 'https://fr.wikipedia.org/wiki/King%27s_Quest_V:_Absence_Makes_the_Heart_Go_Yonder!'),
  ('Q1584331', 'Adventure Island II est un jeu vidéo de plates-formes en 2D à thème préhistorique par Hudson Soft, sorti en 1991 sur Nintendo Entertainment System. Une adaptation, Adventure Island, est sorti en 1992 sur Game Boy. Le jeu est resorti sur Nintendo 3DS et Wii.', 'https://fr.wikipedia.org/wiki/Adventure_Island_II'),
  ('Q1630875', 'Track and Field, officiellement graphié Track & Field, est une série de jeux vidéo sportive dont le premier soft est sorti sur arcade en 1983.

Ensuite, cette série qui propose de multiples épreuves à la manière des Jeux olympiques, sera présente sur plusieurs plateformes.', 'https://fr.wikipedia.org/wiki/Track_and_Field'),
  ('Q1777574', 'Ufouria: The Saga, ou Hebereke au Japon, est un jeu vidéo sorti en 1991 sur NES. Ce jeu a été développé et édité par Sunsoft. C''est le premier jeu de la série Hebereke.

Le 18 août 2022, Sunsoft annonce le portage prochain du titre sur Nintendo Switch, PlayStation 4, Xbox One et PC.', 'https://fr.wikipedia.org/wiki/Ufouria:_The_Saga'),
  ('Q1804014', 'Rainbow Islands: The Story of Bubble Bobble 2 est un jeu vidéo de plates-formes développé par Taito, initialement sorti en 1987 sur borne d''arcade.

Il s''agit du second épisode de la série Bubble Bobble. Dans cette nouvelle aventure, le joueur incarne Bub ou Bob, qui ont repris leur forme humaine après avoir été transformé en « Bubble Dragon » dans le 1er épisode. Les habitants de sept îles ont été enlevés par « Boss of Dark Shadow ». Le but du jeu est de rejoindre le sommet de chaque niveau avant que la montée des eaux ne submerge le héros. Bub a le pouvoir de lancer des arcs-en-ciel magiques qui font office d''armes et de plates-formes temporaires.', 'https://fr.wikipedia.org/wiki/Rainbow_Islands:_The_Story_of_Bubble_Bobble_2'),
  ('Q2188282', 'R.C. Pro-Am est un jeu vidéo de course de voiture en vue aérienne isométrique. Il a été développé par Rare Ltd. et édité par Nintendo et Rare. Il est sorti en Amérique du Nord sur NES en février 1988, suivi de l''Europe le 15 avril 1988. Le jeu a aussi été porté sur Mega Drive par Tradewest en 1992 sous une version améliorée intitulée Championship Pro-Am.', 'https://fr.wikipedia.org/wiki/R.C._Pro-Am_(jeu_vid%C3%A9o)'),
  ('Q2182703', 'Pin Bot est un jeu vidéo de flipper développé par Rare et édité par Nintendo, sorti en 1990 sur NES.', 'https://fr.wikipedia.org/wiki/Pin_Bot'),
  ('Q1790249', 'Winter Games est un jeu vidéo de sport multi-épreuves ayant pour thème les Jeux olympiques d''hiver. Il fut développé et édité par Epyx, sorti en 1985 sur de nombreux ordinateurs personnels et consoles de jeu.', 'https://fr.wikipedia.org/wiki/Winter_Games'),
  ('Q1707792', 'Space Harrier est un jeu vidéo de type shoot ''em up développé par Sega-AM2 et commercialisé par Sega sur borne d''arcade en décembre 1985. Sur une surface plane sur laquelle la caméra réalise un scrolling vers l''avant, le joueur déplace le personnage joueur nommé Harrier qui, à l''aide de son canon qui lui permet de voler, fait face à des vagues d''ennemis et des objets de décor qu''il doit détruire. Le jeu se déroule dans un univers de science-fiction aux couleurs psychédéliques, peuplé d''une faune et d''une flore étranges et hostiles, comme des rochers volants, des mammouths monophtalmes, des têtes de statues de l''île de Pâques volantes, ou des extraterrestres.', 'https://fr.wikipedia.org/wiki/Space_Harrier_(jeu_vid%C3%A9o)'),
  ('Q1658492', 'Shadow Warriors II: Ninja Gaiden II, connu au Japon sous le titre Ninja Ryukenden II: Ankoku no Jashinken ou bien Ninja Gaiden II: The Dark Sword of Chaos en Amérique du Nord, est un jeu vidéo de plates-formes/action développé et édité par Tecmo pour la NES en 1990.

Le jeu connait une suite Ninja Gaiden III: The Ancient Ship of Doom en 1991.', 'https://fr.wikipedia.org/wiki/Shadow_Warriors_II:_Ninja_Gaiden_II'),
  ('Q1835554', 'Fester''s Quest est un jeu vidéo d''action-aventure en vue du dessus, contenant des phases de labyrinthe en vue subjective, développé par Sunsoft sorti en 1989 aux États-Unis sur Nintendo Entertainment System et borne d''arcade, et en 1990 en France. Il est adapté de la série télévisée La Famille Addams et raconte l''histoire de Fester Addams, qui part délivrer les habitants de la ville, tous enlevés lors d''une invasion extraterrestre.', 'https://fr.wikipedia.org/wiki/Fester%27s_Quest'),
  ('Q1837967', 'The Simpsons: Bart vs. the Space Mutants (ou simplement Bart vs. the Space Mutants) est un jeu vidéo de plates-formes alliant action et réflexion, développé par Imagineering et édité par Acclaim sur NES à partir de février 1991. Le jeu est porté à partir de 1991 sur console par Imagineering et édité par Acclaim, ainsi que sur ordinateur où il est porté par Arc Developments et édité par Ocean Software. Le jeu est également commercialisé sur les consoles Master System, Mega Drive et sur la console portable Game Gear, ainsi que sur ordinateur PC (MS-DOS), Amiga, Amstrad CPC, Atari ST, Commodore 64, ZX Spectrum. C''est la première adaptation de la série d''animation Les Simpson en jeu vidéo.', 'https://fr.wikipedia.org/wiki/The_Simpsons:_Bart_vs._the_Space_Mutants'),
  ('Q1668079', 'Smash TV est un jeu vidéo d''action développé et édité par Williams Electronics Games en 1990 sur borne d''arcade. Le jeu a été porté sur divers supports familiaux à partir de 1991.', 'https://fr.wikipedia.org/wiki/Smash_TV_(jeu_vid%C3%A9o)'),
  ('Q1759528', 'Snake Rattle ''n'' Roll est un jeu vidéo de plates-formes développé par Rare et édité par Nintendo. Il est sorti sur Nintendo Entertainment System en juillet 1990 en Amérique du Nord et le 27 mars 1991 en Europe et a ensuite été porté sur Mega Drive par Sega en 1993. Le jeu met en scène deux serpents, Rattle et Roll, dans des niveaux en 3D isométrique.

Snake Rattle ''n'' Roll a été développé par deux membres de Rare, Tim Stamper et Mark Betteridge, et la musique a été composée par David Wise. Il a été bien reçu par la presse spécialisée, qui l''a salué pour ses graphismes en 3D, sa jouabilité et son niveau de difficulté. Une suite du nom de Snake in Space devait sortir mais n''a jamais vu le jour. Cependant, il fut tout de même suivi par Sneaky Snakes sur Game Boy en 1991. Snake Rattle ''n'' Roll a été désigné comme l''un des meilleurs jeux sortis sur NES ainsi que comme l''un des meilleurs jeux développés par Rare.', 'https://fr.wikipedia.org/wiki/Snake_Rattle_%27n%27_Roll'),
  ('Q1748800', 'Hogan''s Alley est un jeu vidéo de tir au pistolet développé par Intelligent Systems et édité par Nintendo en 1984 sur NES. Le titre du jeu est issu du surnom d''un terrain d''entraînement de la National Rifle Association.', 'https://fr.wikipedia.org/wiki/Hogan%27s_Alley_(jeu_vid%C3%A9o)'),
  ('Q2223652', 'R.C. Pro-Am 2 est un jeu vidéo de course de voiture en vue aérienne isométrique développé par Rare et édité par Tradewest. Il est sorti sur NES en Amérique du Nord en décembre 1992 ainsi qu''en Europe le 23 septembre 1993. C''est le deuxième opus de la série R.C. Pro-Am.', 'https://fr.wikipedia.org/wiki/R.C._Pro-Am_II'),
  ('Q2212127', 'Rad Racer est un jeu vidéo de course automobile, développé et publié par Square Co. en 1987 pour la console Nintendo Entertainment System. Ce titre, un des premiers du genre sur cette console, est considéré comme la réponse de Nintendo au fameux Out Run de son concurrent Sega, sorti l''année précédente.

Le jeu sortit d''abord au Japon sur Famicom sous le nom Highway Star. Pour sa sortie américaine ce nom fut changé, pour éviter l''homonymie avec le tube Highway Star de Deep Purple.', 'https://fr.wikipedia.org/wiki/Rad_Racer'),
  ('Q2238794', 'Metro-Cross est un jeu de plates-formes développé et édité par Namco sur borne d''arcade en 1985. Il est en vue perspective cavalière suivant un scrolling horizontal. Le jeu a ensuite été converti sur Amstrad CPC, Atari ST, Commodore 64, Famicom et ZX Spectrum.', 'https://fr.wikipedia.org/wiki/Metro-Cross'),
  ('Q2240236', 'Ultima III: Exodus, est un jeu de rôle sur ordinateur, développé par Richard Garriott et publié par sa société, Origin Systems, en 1983. Le jeu est le troisième de la série de jeux de rôle Ultima et est considéré par de nombreuses personnes comme l’un des jeux de rôle informatiques les plus influents de l’histoire.', 'https://fr.wikipedia.org/wiki/Ultima_III:_Exodus'),
  ('Q2260930', 'Baseball Stars 2 est un jeu vidéo de baseball développé et édité par SNK en 1992 sur Neo-Geo MVS, Neo-Geo AES et en 1994 sur Neo-Geo CD (NGM / NGH 041).', 'https://fr.wikipedia.org/wiki/Baseball_Stars_2'),
  ('Q2252902', 'StarTropics est un jeu vidéo d''action-aventure sorti en Europe en 1992, développé et édité par Nintendo sur NES. Bien qu''il ait été conçu au Japon, le jeu n''est jamais sorti sur ce territoire et a été commercialisé uniquement en Amérique du Nord et en Europe. L''histoire suit Mike Jones, un adolescent dont l''oncle a disparu sur une île tropicale. Le système de jeu consiste à explorer des villages à pied, à naviguer sur les mers et à parcourir des donjons pour progresser.

Le jeu est produit, écrit et réalisé par Genyo Takeda de Nintendo Integrated Research & Development, également créateur de la série Punch-Out!!. StarTropics connait une suite, Zoda''s Revenge: StarTropics II, sortie en 1994 sur NES seulement en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/StarTropics'),
  ('Q2264301', 'Donkey Kong Jr. est un jeu vidéo de plates-formes développé par Nintendo R&D1 et édité par Nintendo. Le jeu est sorti sur borne d''arcade en 1982. Il s''agit de la suite du jeu d''arcade Donkey Kong. Le joueur contrôle le fils de Donkey Kong, Donkey Kong Junior, qui doit délivrer son père capturé par Mario.', 'https://fr.wikipedia.org/wiki/Donkey_Kong_Jr.'),
  ('Q2292340', 'Chack''n Pop est un jeu vidéo édité par Taito en 1983, considéré comme l''ancêtre de Bubble Bobble du fait de la ressemblance de nombreux ennemis et de la duplication dans Bubble Bobble d''un niveau de Chack''n Pop. La version arcade utilise par ailleurs une configuration graphique particulière pour "Zen-Chan", le personnage à remontoir mécanique, qui apparaîtra plus tard dans Bubble Bobble.

Bien qu''aujourd''hui considéré comme peu connu, ce jeu existait sur différents supports: borne arcade, ordinateur MSX, consoles NES, NEC PC-6001, NEC PC-8801 et Sega SG-1000. De plus, l''émulation arcade est incluse dans la compilation Taito Legends Power-Up pour la PlayStation Portable (PSP) et la version NES est téléchargeable sur la Virtual Console (Wii).', 'https://fr.wikipedia.org/wiki/Chack%27n_Pop'),
  ('Q2300687', 'Toki est un jeu vidéo de plates-formes développé et édité par TAD, sorti sur borne d''arcade en 1989. Il fut ensuite porté sur Amiga, Atari ST, Commodore 64, Mega Drive, Nintendo Entertainment System et Lynx.', 'https://fr.wikipedia.org/wiki/Toki_(jeu_vid%C3%A9o)'),
  ('Q2303119', 'Popeye est un jeu d''arcade sorti en 1982, basé sur les personnages du cartoon Popeye, licencié par King Features Syndicate.', 'https://fr.wikipedia.org/wiki/Popeye_(jeu_vid%C3%A9o)'),
  ('Q2306270', 'Hillsfar (ou Advanced Dungeons & Dragons: Hillsfar) est un jeu vidéo de rôle développé par Westwood Studios et publié Strategic Simulations en 1989 sur MS-DOS, Amiga, Atari ST et Commodore 64 puis porté sur NES en novembre 1993. Offrant des quêtes générées aléatoirement, le jeu est basé sur les règles de Donjons et Dragons et se déroule dans l''univers des Royaumes oubliés. Au total, Strategic Simulations a vendu plus de 100 000 copies du jeu.', 'https://fr.wikipedia.org/wiki/Hillsfar'),
  ('Q907618', 'Ys III: Wanderers from Ys est un jeu vidéo de type action-RPG sorti en 1989 sur PC-88, PC-98 et MSX 2. Il sortira par la suite sur X68000, PC-Engine CD, Super Nintendo, Famicom, Mega Drive et PlayStation 2. Le jeu a été développé par Nihon Falcom.', 'https://fr.wikipedia.org/wiki/Ys_III:_Wanderers_from_Ys'),
  ('Q869558', 'Gyromite est un jeu vidéo qui utilise le Robot Operating Buddy (R.O.B.) comme extension et qui est l''un des 2 jeux à utiliser ce robot, l''autre étant Stack-Up. Dans ce jeu, le joueur doit utiliser R.O.B. pour manipuler les gyros (gyroscopes) et ainsi ouvrir les portes rouges et bleues sur l''écran du jeu.', 'https://fr.wikipedia.org/wiki/Gyromite'),
  ('Q2312762', 'Dragon Quest II, est un jeu vidéo de rôle développé par Chunsoft pour la société japonaise Enix. Il sort en 1987 sur NES au Japon puis en 1990 en Amérique du Nord.

Suite de Dragon Quest, le jeu rencontre le succès au Japon. Dans les années suivantes, il est réédité sur MSX, Super Famicom, Game Boy Color et téléphone mobile.', 'https://fr.wikipedia.org/wiki/Dragon_Quest_II'),
  ('Q907744', 'Street Fighter 2010: The Final Fight, ou simplement nommé Street Fighter 2010 au Japon, est un jeu vidéo d''action/plate-forme sorti en 1990 sur Nintendo Entertainment System. Dans la version japonaise, le jeu n''a aucun rapport avec la série Street Fighter, mais la version américaine a changé le nom et l''histoire du personnage principal pour le faire passer pour Ken, bien que Street Fighter 2010 ne soit pas un jeu de combat.', 'https://fr.wikipedia.org/wiki/Street_Fighter_2010:_The_Final_Fight'),
  ('Q917503', 'Gyruss est un jeu vidéo de type shoot ''em up développé par Konami et publié par Centuri en 1983 sur borne d''arcade.', 'https://fr.wikipedia.org/wiki/Gyruss'),
  ('Q911802', 'Parodius, ou Parodius Da! au Japon, est un jeu vidéo de type shoot them up développé et édité par Konami, sorti en 1990 sur borne d''arcade. Il s''agit d''une transposition du concept de Gradius et d''autres jeux de tir dans un univers décalé et parodique.

La version Super Nintendo est sous-titrée Non-Sense Fantasy.', 'https://fr.wikipedia.org/wiki/Parodius_(jeu_vid%C3%A9o,_1990)'),
  ('Q81288', 'Dragon Quest III est un jeu vidéo de rôle développé par Chunsoft pour Enix. Il sort sur NES en février 1988 au Japon puis en mars 1992 en Amérique du Nord.

Par la suite, le jeu est porté sur Super Famicom par Heartbeat en 1996, sur Game Boy Color par TOSE en 2000 et sur téléphones par Matrix Software en 2009.

Un remake intitulé Dragon Quest III HD-2D Remake est annoncé en 2021 et est sorti en novembre 2024 sur Nintendo Switch, PlayStation 5, Xbox Series et Microsoft Windows.', 'https://fr.wikipedia.org/wiki/Dragon_Quest_III'),
  ('Q912286', 'NES Open Tournament Golf (au Japon, Mario Open Golf) est un jeu vidéo de golf, sorti sur NES en 1991.', 'https://fr.wikipedia.org/wiki/NES_Open_Tournament_Golf'),
  ('Q2318803', 'Bases Loaded II est un jeu vidéo de baseball sorti en 1988 sur Famicom au Japon et en 1990 sur NES aux États-Unis. Le jeu a été développé par TOSE et édité par Jaleco.', 'https://fr.wikipedia.org/wiki/Bases_Loaded_II'),
  ('Q2323709', 'Mother (mazā) est un jeu vidéo développé par HAL Laboratory et Ape et édité par Nintendo, sorti au Japon en 1989 sur Famicom. Le jeu sort en 2003 sur Game Boy Advance au Japon, puis sur la console virtuelle de la Wii U en 2015 dans le monde sous le titre EarthBound Beginnings avant de ressortir en 2022 sur le Nintendo Switch Online.

Le jeu raconte l''histoire d''un jeune garçon de douze ans nommé Ninten qui part pour un périple autour des États-Unis afin de sauver la planète d''une race d''extraterrestres maléfiques. D''autres personnages se joignent à lui durant ce voyage qui aboutira à la confrontation finale avec Giegue, le chef des aliens.', 'https://fr.wikipedia.org/wiki/Mother_(jeu_vid%C3%A9o)'),
  ('Q2321007', 'Adventures of Lolo 3, ou Adventures of Lolo II au Japon, est un jeu vidéo de réflexion sorti en 1990 au Japon, en 1991 aux États-Unis et en 1992 en France sur Family Computer (ou Nintendo). Le jeu a été développé et édité par HAL Laboratory.', 'https://fr.wikipedia.org/wiki/Adventures_of_Lolo_3'),
  ('Q2313869', 'Dragon Quest, connu sous le nom de Dragon Warrior aux États-Unis, est un jeu vidéo de rôle développé par Chunsoft pour la société japonaise Enix. Il sort en 1986 sur NES au Japon puis en 1989 en Amérique du Nord. Il sort en 2019 sur Nintendo Switch en Europe. Imaginé et dirigé par Yūji Horii, le jeu connaît un grand succès et donne de nombreuses suites. La licence Dragon Quest devient en quelques années l''une des séries de jeu vidéo les plus populaires au Japon.

Inspiré par les déjà nombreux jeux de rôles sur micro-ordinateurs, Dragon Quest est considéré comme le premier représentant du genre sur console de jeux vidéo.', 'https://fr.wikipedia.org/wiki/Dragon_Quest_(jeu_vid%C3%A9o)'),
  ('Q71910', 'Tetris est un jeu vidéo de puzzle en mouvement conçu par l''ingénieur soviétique Alekseï Pajitnov à partir de 1984 sur Elektronika 60. Lors de la création du concept, Pajitnov est aidé de Dmitri Pavlovski et Vadim Guerassimov pour le développement. Le jeu est édité par plusieurs sociétés au cours du temps, à la suite d''une guerre pour l''appropriation des droits à la fin des années 1980. Le déroulement précis du développement et des premières commercialisations est encore débattu dans les années 2010. Après une exploitation importante par Nintendo, les droits appartiennent depuis 1996 à la société The Tetris Company.', 'https://fr.wikipedia.org/wiki/Tetris'),
  ('Q2321818', 'Castlevania III: Dracula''s Curse est un jeu vidéo d''action et de plates-formes sorti en 1989 sur Nintendo Entertainment System, développé et édité par Konami, distribué par Konami aux États-Unis et au Japon, Palcom en Europe.

Cet opus est le 3e volet de la saga Castlevania à être sorti sur Nintendo Entertainment System, et le 5e de la série tous supports confondus.', 'https://fr.wikipedia.org/wiki/Castlevania_III:_Dracula%27s_Curse'),
  ('Q2321832', 'Castlevania II: Simon''s Quest, connu au Japon sous le nom Dracula II: Noroi no Fūin, est un jeu vidéo d''action et de plates-formes développé et édité par Konami. Comparé aux autres jeux sortis à la même époque, ce jeu dispose d''une grande durée de vie.', 'https://fr.wikipedia.org/wiki/Castlevania_II:_Simon%27s_Quest'),
  ('Q1906269', 'Parasol Stars: The Story of Bubble Bobble III est un jeu vidéo de plates-formes développé par Taito, initialement sorti en 1991 sur PC Engine. Le jeu a été adapté en 1992 sur Amiga, Atari ST, NES et Game Boy, sous-titré The Story of Rainbow Island II dans les versions micros.

Il s''agit du troisième épisode de la série Bubble Bobble. À la différence de Bubble Bobble et Rainbow Islands, le jeu n''est pas sorti en salle d''arcade. Dans cette nouvelle aventure, Bub et Bob, qui ont gardé leur forme humaine du précédent épisode, doivent défaire le terrible « Chaostikahn » et se débarrasser des ennemis dans 70 niveaux, aidés de leur parapluie magique multi - fonction.', 'https://fr.wikipedia.org/wiki/Parasol_Stars'),
  ('Q1865060', 'Gauntlet II est un jeu d''arcade sorti en 1986, qui fait suite au jeu Gauntlet, sorti l''année précédente. Gauntlet II, comme son prédécesseur, est un hack and slash se déroulant dans un univers fantasy.', 'https://fr.wikipedia.org/wiki/Gauntlet_II'),
  ('Q1888364', 'The Battle of Olympus est un jeu vidéo d''action-RPG et Metroidvania développé par le studio Infinity sur Nintendo Entertainment System, sorti le 28 mars 1988 au Japon, un an plus tard en décembre 1989 en Amérique du Nord, puis le 26 septembre 1991 en Europe.

Le jeu retrace l''aventure du mythe d''Orphée — que le joueur incarne — dans une version revisitée. Dans une Grèce antique inspirée de la mythologie grecque, les habitants vivent sous le règne tyrannique d''Hadès, dieu des Enfers. Une femme prénommée Hélène, compagne d''Orphée, est capturée par Hadès; Orphée décide d''aller la sauver. Dans son périple, il rencontre plusieurs monstres et héros issus de la mythologie grecque, ainsi que plusieurs dieux de l''Olympe dont il doit obtenir les faveurs afin de récupérer sa dulcinée.', 'https://fr.wikipedia.org/wiki/The_Battle_of_Olympus'),
  ('Q956303', 'Ghosts ''n Goblins au Japon est un jeu vidéo de plates-formes développé et édité par Capcom en 1985 sur borne d''arcade. Quatre suites officielles virent ensuite le jour, Ghouls ''n Ghosts, Super Ghouls ''n Ghosts, Ultimate Ghosts ''n Goblins et Ghosts ''n Goblins Resurrection. Ce premier opus a été porté vers de nombreuses plates-formes. Ghosts ''n Goblins est considéré comme l''un des jeux les plus difficiles de tous les temps.', 'https://fr.wikipedia.org/wiki/Ghosts_%27n_Goblins_(jeu_vid%C3%A9o)'),
  ('Q950084', 'Trojan est un jeu vidéo de type beat them all en 2D développé par Capcom, et commercialisé par Capcom et Romstar en 1986 sur système d''arcade Section Z et PlayChoice-10. Semblable à Tiger Road ou Kung-Fu Master, le jeu a été adapté sur NES en 1987 et réédité sur PlayStation 2 et Xbox dans la compilation Capcom Classics Collection en 2005.', 'https://fr.wikipedia.org/wiki/Trojan_(jeu_vid%C3%A9o)'),
  ('Q968020', 'Millipede est un jeu vidéo de type shoot ''em up développé et édité par Atari Inc., sorti en 1982 sur borne d''arcade et Atari 2600.

Il fait suite à Centipede. Le jeu est également disponible sur Game Boy en compilation sous le titre Arcade Classic No. 2: Centipede / Millipede.', 'https://fr.wikipedia.org/wiki/Millipede_(jeu_vid%C3%A9o)'),
  ('Q945899', 'Spy vs. Spy est un jeu vidéo édité en 1984 par First Star Software. Pour deux joueurs en écran partagé, le jeu reprend les espions de la bande dessinée Spy vs. Spy du magazine Mad. D''abord sorti sur Atari 8-bit, Commodore 64 et Apple II, il est ensuite porté sur Acorn Electron, Amiga, Amstrad CPC, Atari ST, BBC Micro, Commodore 16, Game Boy, Game Boy Color, MSX, NES, Master System, Sharp X1 et ZX Spectrum.', 'https://fr.wikipedia.org/wiki/Spy_vs._Spy_(jeu_vid%C3%A9o,_1984)'),
  ('Q928439', 'World Games est un jeu vidéo de sport multi-épreuves développé en 1986 par Epyx.', 'https://fr.wikipedia.org/wiki/World_Games'),
  ('Q933328', 'Disney''s DuckTales (traduit par La Bande à Picsou) est un jeu vidéo de plate-forme adapté de la série d''animation du même nom La Bande à Picsou. Le jeu, développé par Capcom est d''abord sorti aux États-Unis sur NES en 1989 avant d''être porté sur Game Boy l''année suivante.', 'https://fr.wikipedia.org/wiki/Disney%27s_DuckTales'),
  ('Q938696', 'Murder on the Mississippi est un jeu vidéo d’aventure créé par Adam Bellin et publié par Activision en 1986 sur Apple II, Commodore 64 et Commodore 128. Le jeu se déroule à bord d’un bateau à aubes lors d’un voyage sur le Mississippi entre Saint-Louis et La Nouvelle-Orléans. Le joueur incarne le détective Sir Charles Foxworth qui, accompagné de son assistant Regis Phelps, prend part au voyage avec huit autres passagers. Peu après le départ, il découvre un cadavre et dispose alors de trois jours pour enquêter sur le crime et découvrir l’identité de l’assassin. Pour cela, il peut interroger les passagers et fouiller le navire à la recherche d’indice. Il doit également se méfier de l’assassin qui peut tenter de l’empêcher de poursuivre son enquête. Le joueur contrôle son personnage à l’aide du joystick et peut ainsi explorer les quatre ponts et les vingt-quatre cabines du navire. Un système de menu, dans lesquels il navigue à l’aide du joystick, lui permet d’interroger chaque suspect au sujet de la victime, de lui-même ou des autres passagers. Les informations importantes obtenues grâce à ces témoignages peuvent être enregistrées dans un carnet, que le joueur peut consulter à tout moment. De leurs côtés, les indices que le joueur découvre peuvent être gardés par son assistant, ou stockés dans le coffre de sa cabine.', 'https://fr.wikipedia.org/wiki/Murder_on_the_Mississippi'),
  ('Q923597', 'Bases Loaded 4 est un jeu vidéo de baseball sorti en 1991 sur Famicom au Japon et en 1993 sur NES aux États-Unis. Le jeu a été développé par TOSE et édité par Jaleco.', 'https://fr.wikipedia.org/wiki/Bases_Loaded_4'),
  ('Q2627223', 'Friday the 13th est un jeu vidéo développé par Atlus et édité par LJN, sorti en 1989 sur Nintendo Entertainment System.

Le jeu est basé sur la série de films Vendredi 13. Il est parfois considéré comme l''un des pires jeux de la console (il a à ce titre été testé par l''Angry Video Game Nerd et le Joueur du Grenier).', 'https://fr.wikipedia.org/wiki/Friday_the_13th_(jeu_vid%C3%A9o,_1989)'),
  ('Q2623012', 'Bump ''n'' Jump, aussi appelé Burnin'' Rubber, est un jeu vidéo développé par Data East, sorti en 1982 sur borne d''arcade. Il a été adapté sur les consoles Atari 2600, Commodore 64, Intellivision en 1983, ColecoVision en 1984 et NES en 1986. Il s''agit d''un jeu de course automobile en vue de dessus où le joueur doit terminer le parcours tout en évitant de se faire plaquer par les autres voitures sur le côté. De plus, le joueur rencontre des obstacles impossibles à contourner comme des cours d''eau.', 'https://fr.wikipedia.org/wiki/Bump_%27n%27_Jump'),
  ('Q2624732', 'Little Nemo: The Dream Master est un jeu vidéo de plates-formes développé et édité par Capcom sur Nintendo Entertainment System en septembre 1990. Le jeu est basé sur le film d''animation Little Nemo: Adventures in Slumberland, lui-même inspiré de la bande dessinée Little Nemo in Slumberland et son personnage principal Nemo.', 'https://fr.wikipedia.org/wiki/Little_Nemo:_The_Dream_Master'),
  ('Q2626892', 'Krusty''s Fun House (également Krusty''s Super Fun House suivant les versions) est un jeu vidéo de plates-formes / réflexion développé par Fox Williams et Audiogenic Software et édité par Acclaim et Virgin Games en 1992. Le jeu est sorti sur divers micro-ordinateurs et consoles. Il est basé sur la licence Les Simpson

.', 'https://fr.wikipedia.org/wiki/Krusty%27s_Fun_House'),
  ('Q2617004', 'The Black Onyx est un jeu vidéo de rôle développé et édité par Bullet-Proof Software au Japon en 1984 sur ordinateurs personnels. Premier jeu de rôle à recevoir un succès sur l''archipel avec 150 000 exemplaires écoulés, il a contribué à familiariser le public japonais avec le genre et est généralement considéré comme le premier RPG japonais (ou J-RPG) de l''histoire. Le jeu, conçu par Henk Rogers, est d''abord disponible sur NEC PC-8801 puis porté sur de nombreuses plate-formes, comme le MSX en 1985, sur la console SG-1000 en 1987 ou Famicom en 1988. Cette dernière version, intitulée Super Black Onyx comporte un gameplay complètement modifié, avec de nouvelles cartes.', 'https://fr.wikipedia.org/wiki/The_Black_Onyx'),
  ('Q2629434', 'Tiny Toon Adventures est un jeu vidéo édité et développé par Konami et sorti en 1991 sur NES au Japon et aux États-Unis puis en 1992 en Europe. Il s''agit du premier jeu vidéo inspiré de la série éponyme.', 'https://fr.wikipedia.org/wiki/Tiny_Toon_Adventures_(jeu_vid%C3%A9o)'),
  ('Q2630920', 'Disney''s DuckTales 2 (La Bande à Picsou 2) est un jeu vidéo de plate-forme adapté de la série d''animation éponyme La Bande à Picsou. Le jeu par Capcom est sorti sur NES et sur Game Boy en 1993. Il est la suite du jeu Disney''s DuckTales sorti sur les mêmes plates-formes.

Le 16 mars 2017, Capcom annonce la ressortie le 18 avril de plusieurs titres phares 8 bits de Disney Interactive des années 1990 sous le nom The Disney Afternoon Collection sur Xbox One, PlayStation 4 et PC dont Disney''s Darkwing Duck, Disney''s DuckTales, Disney''s DuckTales 2, Disney''s Chip''n Dale: Rescue Rangers, Disney''s Chip''n Dale: Rescue Rangers 2 et Disney''s TaleSpin.', 'https://fr.wikipedia.org/wiki/Disney%27s_DuckTales_2'),
  ('Q2630928', 'Dragon Ball Z: Le Plan d''éradication des Super Saïyens est un OAV japonais sorti en août 1993 au Japon, produit par Bandaï, servant de solution au jeu vidéo éponyme, paru en août 1993 et destiné à la console Famicom. Jamais diffusé en France, un remake de 30 minutes est inclus dans le jeu Dragon Ball: Raging Blast 2, en VOSTFR seulement. L''OAV sera finalement doublé en français en 2018.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z_:_Le_Plan_d%27%C3%A9radication_des_Super_Sa%C3%AFyens'),
  ('Q2634600', 'Gumshoe est un jeu vidéo de tir au pistolet optique développé et publié par Nintendo sur les bornes d''arcade VS. System et sur la Nintendo Entertainment System. Le jeu sortit en Amérique du Nord en 1986, puis en Europe en 1988. Il ne fut pas distribué au Japon, ce qui était inhabituel pour un jeu de Nintendo. Le jeu a été conçu par Yoshio Sakamoto.', 'https://fr.wikipedia.org/wiki/Gumshoe_(jeu_vid%C3%A9o)'),
  ('Q2660086', 'Little Samson est un jeu vidéo d''action sorti en 1992 sur Nintendo Entertainment System. Le jeu a été développé par Takeru puis édité par Taito. Doté de graphismes très détaillés pour un jeu 8 bits, le jeu n’est pourtant pas parvenu à trouver un public face à des concurrents comme Mega Man de Capcom et la série des Adventure Island.', 'https://fr.wikipedia.org/wiki/Little_Samson'),
  ('Q2659903', 'Jackal, appelé Tokushu Butai Jackal au Japon et Jackal aux États-Unis, est un jeu vidéo d''action en 3D développé par Konami, sorti en 1986 sur borne d''arcade. Le jeu a été adapté sur Amstrad CPC, Commodore 64, DOS, Famicom Disk System, Nintendo Entertainment System et ZX Spectrum.

Il s''agit d''un run and gun en vue de dessus avec des environnements qui se déploient par défilement vertical. Le joueur est aux commandes d''une jeep armée. Le jeu est jouable à deux en simultané.', 'https://fr.wikipedia.org/wiki/Jackal_(jeu_vid%C3%A9o)'),
  ('Q2645897', 'Home Alone 2: Lost in New York est un jeu vidéo de plates-formes sorti en 1992 sur Game Boy, Nintendo Entertainment System, Super Nintendo, Mega Drive et DOS. Le jeu a été développé par Imagineering Inc. et édité par THQ. Il est basé sur le film Maman, j''ai encore raté l''avion ! et fait suite à Home Alone. Le jeu a été dédié à Tom D. Heidt, un programmeur mort peu avant sa sortie.', 'https://fr.wikipedia.org/wiki/Home_Alone_2:_Lost_in_New_York_(jeu_vid%C3%A9o)'),
  ('Q2658381', 'Shadow Warriors, plus connu sous le titre Ninja Gaiden en Amérique du Nord, est un jeu vidéo de plates-formes/action développé et édité par Tecmo pour la NES fin 1988. Le jeu connait une suite Shadow Warriors II: Ninja Gaiden II en 1990.

Il s''agit du premier épisode de la série Ninja Gaiden à être développé spécialement pour une console.', 'https://fr.wikipedia.org/wiki/Shadow_Warriors_(jeu_vid%C3%A9o,_1988)'),
  ('Q2338283', 'Soccer est un jeu vidéo de football développé par Intelligent Systems et édité par Nintendo. Il est sorti sur Nintendo Entertainment System en 1985.', 'https://fr.wikipedia.org/wiki/Soccer_(jeu_vid%C3%A9o)'),
  ('Q2340591', 'Just Breed est un jeu vidéo de genre Tactical RPG sorti le 15 décembre 1992 sur Famicom au Japon. Le jeu n''est jamais sorti en dehors du Japon, mais il existe une traduction en anglais par le groupe de fans Stealth Translations. Le jeu a été développé par Random House et édité par Enix.', 'https://fr.wikipedia.org/wiki/Just_Breed'),
  ('Q2331936', 'Cosmic Spacehead (ou Linus Spacehead''s Cosmic Crusade) est un jeu vidéo sorti en 1993 sur Amiga, DOS, Game Gear, Master System, Mega Drive et NES. Il s''agit d''un jeu d''aventure, où les différentes sections sont reliées par des séquences de plates-formes. Il a été développé et édité par Codemasters.

Ce jeu est la suite de Linus Spacehead, un jeu de plates-formes uniquement paru en tant que l''un des 4 jeux de la cartouche NES Quattro Adventure (en).', 'https://fr.wikipedia.org/wiki/Cosmic_Spacehead'),
  ('Q1010202', 'Legend of the Ghost Lion ou Legend of the White Lion (connu au Japon sous le nom White Lion Densetsu: Pyramid no Kanata ni est un jeu vidéo de rôle au tour par tour, développé et édité par Kemco pour la NES. Il est sorti au Japon le 14 juin 1989, et en Amérique du Nord en octobre 1992. Il s''agit d''une adaptation du film Piramiddo no Kanata ni Howaito Raion Densetsu (1988).', 'https://fr.wikipedia.org/wiki/Legend_of_the_Ghost_Lion'),
  ('Q968105', 'Wild Gunman est un jeu vidéo de tir au pistolet optique développé et édité par Nintendo, sorti en 1984 sur Nintendo Entertainment System. Il se joue avec l''accessoire NES Zapper.', 'https://fr.wikipedia.org/wiki/Wild_Gunman'),
  ('Q1014915', 'BurgerTime (version américaine), appelé également Hamburger (version japonaise), est un jeu vidéo de 1982 créé par la société japonaise Data East pour sa borne DECO Cassette System.', 'https://fr.wikipedia.org/wiki/BurgerTime'),
  ('Q1026656', 'Donkey Kong, Jr. Math, titré au Japon Donkey Kong Jr. no Sansū Asobi, est un jeu vidéo éducatif développé par Nintendo dans lequel les joueurs doivent résoudre des problèmes de mathématiques. Il est d''abord sorti sur Family Computer en 1983 au Japon, puis sur Nintendo Entertainment System (ou NES) deux ans plus tard en Amérique du Nord et dans les régions PAL. Il est également possible de jouer à Donkey Kong Jr. Math dans Animal Crossing et sur Console virtuelle. Il s''agit d''un spin-off de Donkey Kong Jr..

Donkey Kong Jr. Math a reçu un accueil très négatif de la part de la presse spécialisée. Tom Sarris, porte-parole de Nintendo, a lui-même souligné que le jeu n''avait pas été bien reçu et que c''est pour cette raison que Nintendo avait arrêté de développer des jeux éducatifs quelque temps. Le soft a été jugé comme l''un des pires jeux disponibles au lancement d''une console par différentes publications comme Electronic Gaming Monthly et 1UP.com. IGN a également été très critique à l''égard de celui-ci, le désignant comme l''un des pires jeux sur Console virtuelle. Aux États-Unis, Donkey Kong Jr. Math a été, parmi les jeux disponibles au lancement de la NES, celui qui s''est le moins vendu.', 'https://fr.wikipedia.org/wiki/Donkey_Kong_Jr._Math'),
  ('Q2679211', '8 Eyes est un jeu vidéo de plate-forme sorti en 1988 sur Famicom. Le jeu a été développé par Thinking Rabbit et édité par Seta au Japon et Taxan aux États-Unis.

Dans un monde post-apocalyptique, où une guerre nucléaire a anéantit la civilisation, le joueur contrôle Orin, un guerrier. Aidé de son aigle, il doit retrouver 8 joyeaux afin de récupérer la clef qui pourra restaurer la paix.', 'https://fr.wikipedia.org/wiki/8_Eyes'),
  ('Q2669580', '10-Yard Fight est un jeu vidéo de football américain développé et publié par Irem, sorti en 1983 sur borne d’arcade. En 1985, il fait l’objet d’un portage sur Nintendo Entertainment System où il figure parmi les dix-sept jeux au lancement de la console aux États-Unis. Il est également publié sur MSX en 1986. La version arcade est commercialisée le 2 mai 2018 sur le Nintendo eShop au sein de la collection Arcade Archives, produite par Hamster.', 'https://fr.wikipedia.org/wiki/10-Yard_Fight'),
  ('Q2660330', 'Abadox: The Deadly Inner War (connu au Japon simplement sous le titre Abadox) est un shoot them up à défilement horizontal sorti en 1989 sur Nintendo Entertainment System. Le jeu a été co-développé par Natsume, ITL Co et Dynamic Planning, et fut édité par Natsume au Japon et par MB aux États-Unis.', 'https://fr.wikipedia.org/wiki/Abadox:_The_Deadly_Inner_War'),
  ('Q2680533', 'Lot Lot est un jeu vidéo de puzzle sorti en 1985 sur borne d''arcade puis sur Famicom, MSX et PC-88. Le jeu a été développé par Tokuma Shoten et édité par Irem.', 'https://fr.wikipedia.org/wiki/Lot_Lot'),
  ('Q2684056', 'Indiana Jones and the Last Crusade: The Action Game est un jeu vidéo d''action sorti en 1989 sur Amiga, Amstrad CPC, Atari ST, Commodore 64, MSX et ZX Spectrum. Il a ensuite été réédité sur Master System en 1990, sur Game Gear, Mega Drive et PC en 1992, et sur Game Boy en 1994. Le jeu a été développé par Tiertex et édité par U.S. Gold. Il est basé sur le film Indiana Jones et la Dernière Croisade sorti la même année.', 'https://fr.wikipedia.org/wiki/Indiana_Jones_and_the_Last_Crusade:_The_Action_Game'),
  ('Q1058037', 'Super Pitfall est un jeu vidéo développé par Micronics et édité par Pony Canyon et par Activision. Il est sorti en 1986 au Japon et en 1987 en Amérique du Nord sur Nintendo Entertainment System. Il s''agit de la suite de Pitfall! sur Atari 2600.', 'https://fr.wikipedia.org/wiki/Super_Pitfall'),
  ('Q1066035', 'Gradius II: Gofer no Yabō, nommé Vulcan Venture en Europe, est un jeu vidéo de type shoot them up développé et édité par Konami en 1988 sur borne d''arcade. Il s''agit d''une autre suite de Gradius.', 'https://fr.wikipedia.org/wiki/Gradius_II:_Gofer_no_Yab%C5%8D'),
  ('Q1066657', 'Ice Climber est un jeu vidéo de plates-formes développé par Nintendo R&D1 et édité par Nintendo, sorti sur arcade en 1984, sur Nintendo Entertainment System en 1985, puis sur Famicom Disk System en 1988. La version arcade est appelée Vs. Ice Climber. La version Game and Watch se nomme Climber et fut sortie en 1986.', 'https://fr.wikipedia.org/wiki/Ice_Climber'),
  ('Q2700588', 'Tennis est un jeu vidéo de tennis développé et édité par Nintendo, sorti en 1984.', 'https://fr.wikipedia.org/wiki/Tennis_(jeu_vid%C3%A9o,_1984)'),
  ('Q2705496', 'Mike Tyson''s Punch-Out!! est un jeu vidéo sorti sur Nintendo Entertainment System (NES) en 1987, puis ressorti sous le nom de Punch-Out!! en 1990. Ce jeu est basé sur le jeu d''arcade Punch-Out!! sorti en 1983.', 'https://fr.wikipedia.org/wiki/Mike_Tyson%27s_Punch-Out!!'),
  ('Q2705249', 'The Addams Family: Pugsley''s Scavenger Hunt est un jeu vidéo de plates-formes développé et édité par Ocean Software en 1993 sur Super Nintendo, Game Boy et Nintendo Entertainment System.

Les versions NES et Game Boy ne sont pas directement liées à la version Super Nintendo de Pugsley''s Scavenger Hunt, seul le personnage de Pugsley a été repris. Ces deux versions sont une adaptation du précédent jeu The Addams Family, publié en 1992.', 'https://fr.wikipedia.org/wiki/The_Addams_Family:_Pugsley%27s_Scavenger_Hunt'),
  ('Q2701304', 'Mario et la Machine à remonter le temps (Mario''s Time Machine) est un jeu vidéo éducatif sorti sur NES en 1993. Il est également sorti sur Super Nintendo et DOS. Les joueurs le considèrent comme la suite de Mario a disparu !.

Il a été développé par The Software Toolworks (en) pour le MS-DOS et développé par Radical Entertainment pour la NES et la Super Nintendo et édité par Mindscape.', 'https://fr.wikipedia.org/wiki/Mario_et_la_Machine_%C3%A0_remonter_le_temps'),
  ('Q2710703', 'Blades of Steel est un jeu vidéo de hockey sur glace publié par Konami sur borne d''arcade en 1987, et sortie sur la Nintendo Entertainment System et le Commodore 64 en 1988 et adapté en 1991 sur Game Boy, DOS et Amiga. Toutes les équipes utilisent des noms fictifs mais basée sur de véritables villes canadiennes et américaines, et partagent les couleurs du monde réel. Le jeu est connu pour son action rapide du hockey et en particulier pour les combats. Il s''agit d''un jeu à un ou deux joueurs. Lorsque vous jouez contre l''ordinateur, il y a trois niveaux de difficulté au choix: Junior, College, et Pro (Pro étant le plus difficile et le plus facile étant Junior). Chaque équipe se compose de trois ailiers, deux défenseurs et un gardien de but.', 'https://fr.wikipedia.org/wiki/Blades_of_Steel'),
  ('Q2717834', 'Wizardry II: The Knight of Diamonds (Sorcellerie II: Le Chevalier de diamant dans sa première version française) est un jeu vidéo de type dungeon crawler développé et publié par Sir-Tech à partir de 1982 sur Apple II, Commodore 64, DOS, NES, PC booter, PC-98 et Macintosh. Le jeu est le deuxième opus de la série Wizardry. Techniquement, il est quasiment identique à son prédécesseur. Il propose néanmoins un nouveau scénario ainsi que de nouvelles zones à explorer. L’objectif du joueur est de retrouver le bâton de Gilna, un objet magique qui protégeait jusque-là la cité de Llylgamyn mais qui a été volé par un être maléfique, Davalpus. Pour le récupérer, le joueur doit d’abord se procurer les cinq pièces de l’armure du Chevalier de Diamant qui sont éparpillées dans un donjon. Le jeu nécessite initialement d’avoir terminé Wizardry: Proving Grounds of the Mad Overlord, l’idée étant de continuer l’aventure avec les mêmes personnages, comme dans une extension. Ce système se révèle cependant être un échec et les versions suivantes du jeu permettent de créer de nouveaux personnages ou d’utiliser un groupe déjà créé. Le donjon étant calibré pour des personnages de niveau 13, un groupe nouvellement créé n’a cependant que peu de chances de survivre aux premiers combats. À sa sortie en 1982, le magazine Softline salue la variété des monstres du jeu ainsi que les quêtes associées à chaque niveau du donjon.', 'https://fr.wikipedia.org/wiki/Wizardry_II:_The_Knight_of_Diamonds'),
  ('Q2716205', 'Wario’s Woods est un jeu vidéo de puzzle sorti en 1994 sur Nintendo Entertainment System et sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Wario%27s_Woods'),
  ('Q2731595', 'Golf est un jeu vidéo de golf sorti en 1984, développé et édité par Nintendo. Le personnage principal est parfois identifié comme Mario, bien qu''il soit de taille plus grande.', 'https://fr.wikipedia.org/wiki/Golf_(jeu_vid%C3%A9o)'),
  ('Q1041292', 'Baseball est un jeu vidéo de baseball sorti en 1983, développé par Nintendo R&D1 et édité par Nintendo.', 'https://fr.wikipedia.org/wiki/Baseball_(jeu_vid%C3%A9o)'),
  ('Q1043375', 'Castlevania, intitulé Akumajō Dracula au Japon, est un jeu vidéo d''action et de plates-formes développé et édité par Konami, sorti le 26 septembre 1986 sur Famicom Disk System. Il a été adapté sur Nintendo Entertainment System, borne d''arcade, Amiga, Commodore 64 et DOS. Il est le premier opus de la série Castlevania.', 'https://fr.wikipedia.org/wiki/Castlevania_(jeu_vid%C3%A9o,_1986)'),
  ('Q1043534', 'Galaga est un jeu vidéo de type shoot ''em up développé par Namco et commercialisé sur borne d''arcade en 1981. Il s''agit de la suite de Galaxian.

Galaga est le premier jeu d''arcade permettant à un seul joueur de jouer avec deux vaisseaux simultanément. C''est aussi le premier jeu d''arcade à comporter des « niveaux bonus » (appelés « challenging stages ») entre les niveaux.', 'https://fr.wikipedia.org/wiki/Galaga'),
  ('Q1076255', 'Choplifter! (Choplifter) est un jeu vidéo de type shoot ''em up développé par Dan Gorlin et publié par Brøderbund Software sur Apple II en mai 1982. Il est ensuite porté sur Atari 8-bit, Commodore 64, Commodore VIC-20 (par Creative Software), Atari 5200 (par Atari), ColecoVision, Master System, NES, MSX, Thomson MO5 et TO7 (Par France Image Logiciel en 1985). Il est également porté sur le système d''arcade System 1 par Sega en 1985. Un portage Intellivision était en cours de développement mais fut abandonné. Dans Choplifter, le joueur contrôle un hélicoptère en vue de côté à défilement horizontal et a pour objectif de délivrer des otages emprisonnés dans des casernes en territoire ennemi. Au cours de ses missions, il est amené à affronter trois types d’ennemis: des chars d’assauts, des chasseurs et des mines antiaériennes.', 'https://fr.wikipedia.org/wiki/Choplifter!'),
  ('Q1081036', 'Rocket Ranger est un jeu vidéo d''action-aventure inspiré de Rocketeer qui marqua les esprits des possesseurs de 16/32 bits par ses qualités artistiques très poussées et emblématiques du studio Cinemaware, déjà auteur du fameux Defender of the Crown (1986) et en 1990 de Wings.', 'https://fr.wikipedia.org/wiki/Rocket_Ranger'),
  ('Q1075814', 'Solomon''s Key est un jeu vidéo de plates-formes/réflexion développé et commercialisé par Tecmo en 1986 sur borne d''arcade. Le jeu fut porté sur divers plates-formes familiales à partir de 1987.Ce jeu a eu une suite dont le titre original est Solomon no Kagi 2. Cette fois le principe est d''éteindre des flammes dans une centaine de salles en manipulant et créant des blocs de glace.', 'https://fr.wikipedia.org/wiki/Solomon%27s_Key'),
  ('Q150146', 'Fire Emblem: Shadow Dragon & the Blade of Light est le premier jeu de la série Fire Emblem. C''est un tactical RPG sorti exclusivement au Japon en 1990 sur Famicom. Le jeu a été développé par l''unité Nintendo R&D 1 et Intelligent Systems et édité par Nintendo.

Un remake légèrement raccourci apparaît dans Fire Emblem: Mystery of the Emblem, sorti en 1994 sur Super Famicom, en plus d''une suite à l''histoire du jeu. Un remake intégral connu sous le nom de Fire Emblem: Shadow Dragon est également sorti sur Nintendo DS en 2008.

Empruntant des éléments de gameplay aux jeux vidéo de rôle, tels que Dragon Quest ou Final Fantasy, et aux jeux de tactique comme sa série sœur Nintendo Wars, Fire Emblem: Shadow Dragon & the Blade of Light est l''un des premiers jeux à inaugurer le genre du tactical RPG, et a fortiori l''un des premiers jeux de tactique sur console de salon, genre traditionnellement associé au support PC. Les jeux suivants offriront de nombreux changements et améliorations dans le gameplay.', 'https://fr.wikipedia.org/wiki/Fire_Emblem:_Shadow_Dragon_%26_the_Blade_of_Light'),
  ('Q2015406', 'WWF WrestleMania Challenge est un jeu vidéo de catch professionnel commercialisé sur console NES en 1990 aux États-Unis, et en 1992 en Europe. Ce jeu est la suite de WWF WrestleMania, commercialisé trois ans plus tôt. Aux États-Unis, le jeu est sorti juste après WrestleMania VI, lorsque l''Ultimate Warrior était champion de la fédération, ce catcheur est d''ailleurs mis en avant dans le jeu. Le jeu met en scène neuf personnages: The Ultimate Warrior, Hulk Hogan, "Macho King" Randy Savage, André le Géant, Hacksaw Jim Duggan, The Big Boss Man, Ravishing Rick Rude, Brutus "The Barber" Beefcake, et "Yourself" (personnage générique). Dans un mode à un-contre-un, les joueurs peuvent choisir une version différente du personnage générique.', 'https://fr.wikipedia.org/wiki/WWF_WrestleMania_Challenge'),
  ('Q2017429', 'American Gladiators est un jeu vidéo d''action et de combat développé par Incredible Technologies et édité par GameTek en 1991 sur Nintendo Entertainment System. Le jeu a par la suite été adapté sur Amiga, Atari ST, DOS, Mega Drive et Super Nintendo par Imagitec Design.

Le jeu s''inspire de l''émission de télévision américaine American Gladiators.', 'https://fr.wikipedia.org/wiki/American_Gladiators_(jeu_vid%C3%A9o)'),
  ('Q2022792', 'Super Spy Hunter (Battle Formula au Japon) est un jeu vidéo de combat motorisé développé et édité par Sunsoft, sorti en 1991 sur NES.', 'https://fr.wikipedia.org/wiki/Super_Spy_Hunter'),
  ('Q2015463', 'WWF WrestleMania: Steel Cage Challenge est un jeu vidéo de catch professionnel basé sur la World Wrestling Federation, commercialisé en 1992 par Acclaim Entertainment sur consoles NES et Sega Master System ainsi que sur console portable Sega Game Gear. Les modes varient entre matchs à un contre un, tag team, WWF Championship (dans lequel le joueur choisit son personnage et combat les autres pour devenir WWF Champion) et Tag Team Championship.

La version NES expose dix personnages: Hulk Hogan, Randy Savage, I.R.S., Ted DiBiase, Jake Roberts, Roddy Piper, Bret Hart, Sid Justice, The Undertaker et The Mountie.', 'https://fr.wikipedia.org/wiki/WWF_WrestleMania:_Steel_Cage_Challenge'),
  ('Q2017774', 'Super Off Road (Ivan "Ironman" Stewart''s Super Off Road) est un jeu vidéo de course développé par Leland Corporation, sorti en 1989 sur borne d''arcade. Il a été adapté sur divers consoles de jeu et ordinateurs personnels.', 'https://fr.wikipedia.org/wiki/Super_Off_Road'),
  ('Q2016893', 'TouchDown Fever est un jeu vidéo de football américain développé et édité par SNK, sorti en 1987 sur borne d''arcade (sur le système Psycho Soldier). Il est porté en 1988 sur NES.', 'https://fr.wikipedia.org/wiki/TouchDown_Fever'),
  ('Q1967469', 'RoadBlasters est un jeu vidéo de course développé et commercialisé par Atari Games en 1987 sur borne d''arcade. Il a été adapté sur Amiga, Atari ST, Amstrad CPC, Commodore 64, ZX Spectrum en 1988, Nintendo Entertainment System et Lynx en 1990 et Mega Drive en 1991.', 'https://fr.wikipedia.org/wiki/RoadBlasters'),
  ('Q1953575', 'Qix (prononcé /kɪks/) est un jeu d''arcade sorti en 1981 par Taito. Il a pour suite Super Qix.', 'https://fr.wikipedia.org/wiki/Qix'),
  ('Q1973612', 'Nebulus (également connu sous les noms de Castelian, Kyorochan Land et Tower Toppler) est un jeu vidéo de plates-formes publié à la fin des années 1980.', 'https://fr.wikipedia.org/wiki/Nebulus'),
  ('Q1950716', 'The Guardian Legend est un jeu vidéo développé par Compile sous la direction de Masamitsu Niitani et sorti en 1988. Le jeu se déroule en deux phases distinctes, une ou l''on dirige l''héroïne à pied et de genre action-aventure et une ou l''on dirige un vaisseau et qui est de genre shoot them up. Le joueur contrôle une jeune femme qui doit empêcher Naju, une planète extraterrestre, d''entrer en collision avec la Terre.', 'https://fr.wikipedia.org/wiki/The_Guardian_Legend'),
  ('Q2449283', 'The Transformers: Mystery of Convoy (戦え! 超ロボット生命体トランスフォーマー コンボイの謎, Tatakae! Chō Robotto Seimeitai Toransufōmā: Konboi no Nazo) est un jeu vidéo de type run and gun développé par ISCO et édité par Takara, sorti en 1986 sur NES.', 'https://fr.wikipedia.org/wiki/The_Transformers:_Mystery_of_Convoy'),
  ('Q2442526', 'Astérix est un jeu vidéo de plates-formes développé par New Frontier et Infogrames et édité par Infogrames. Le jeu est sorti en 1993, uniquement en Europe, sur Nintendo Entertainment System, Super Nintendo et Game Boy. Le jeu est basé sur la série de bande dessinée du même nom d''Uderzo et Goscinny.

Il a été suivi par Astérix et Obélix, des mêmes développeurs, en 1995.', 'https://fr.wikipedia.org/wiki/Ast%C3%A9rix_(jeu_vid%C3%A9o,_1993)'),
  ('Q2441363', 'A Nightmare on Elm Street est un jeu vidéo de type action sur NES édité par LJN et développé par Rare. Il est sorti en octobre 1990. Il met en scène Freddy Krueger, le personnage du film Les Griffes de la Nuit.', 'https://fr.wikipedia.org/wiki/A_Nightmare_on_Elm_Street_(jeu_vid%C3%A9o)'),
  ('Q2414730', 'Joe and Mac: Caveman Ninja, ou Caveman Ninja, plus connu au Japon sous le titre Tatakae Genshijin: Joe and Mac, est un jeu vidéo de plates-formes développé par Data East, sorti en 1991 sur borne d''arcade. Le jeu a été adapté sur diverses consoles et ordinateurs dont les versions européennes furent éditées par Elite Systems', 'https://fr.wikipedia.org/wiki/Joe_and_Mac:_Caveman_Ninja'),
  ('Q187339', 'Zelda II: The Adventure of Link (ou simplement Zelda II ou The Adventure of Link) est un jeu vidéo de type action-RPG développé et édité par Nintendo en janvier 1987 au Japon sur Famicom Disk System, l''extension de la Famicom. Il s''agit du deuxième épisode de la série The Legend of Zelda, suite directe du jeu éponyme sorti un an auparavant. Il est porté sur NES et édité fin 1988 aux États-Unis et en Europe.

Quelques années après la victoire de Link dans le premier opus, le royaume d''Hyrule est mis à mal par les sbires de Ganon qui cherchent à mettre la main sur Link, afin d''accomplir la résurrection de leur chef. Link repart à l''aventure pour trouver la Triforce du Courage qui va lui permettre de réveiller la princesse Zelda, endormie depuis de nombreuses années par un sort maléfique, et empêcher le retour de Ganon.', 'https://fr.wikipedia.org/wiki/Zelda_II:_The_Adventure_of_Link'),
  ('Q204105', 'Dig Dug est un jeu vidéo développé par Namco, sorti en 1982 sur borne d''arcade.

Dig Dug est un classique de l''âge d''or des jeux d''arcade. Il a été adapté sur Apple II, Atari 2600, Atari 5200, Atari 7800, ColecoVision, Commodore 64, Commodore VIC-20, Famicom, Famicom Disk System, Game Boy, IBM PC, Intellivision, MSX, TI-99/4A et en téléchargement sur Xbox 360 et sur Wii.', 'https://fr.wikipedia.org/wiki/Dig_Dug'),
  ('Q173626', 'Pac-Man (initialement intitulé Puckman) est un jeu vidéo créé par Tōru Iwatani pour l’entreprise japonaise bandai Namco, sorti au Japon le 22 mai 1980. Le jeu consiste à déplacer Pac-Man, un personnage qui, vu de profil, ressemble à un diagramme circulaire à l’intérieur d’un labyrinthe, afin de lui faire manger toutes les pac-gommes qui s’y trouvent en évitant d’être touché par des fantômes.

Lorsque Pac-Man est sorti, les jeux vidéo d''arcade les plus populaires étaient les jeux de tir, en particulier les Space Invaders et Asteroids. La minorité la plus visible était des jeux de sport pour la plupart dérivés de Pong. Pac-Man leur a succédé en créant un nouveau genre. Pac-Man est souvent crédité en tant que point de repère dans l''histoire du jeu vidéo, et est parmi les plus célèbres jeux d''arcade de tous les temps. Il est également l''un des jeux vidéo avec les plus grosses recettes de tous les temps, ayant généré plus de 2,5 milliards de $ au cours des trimestres des années 1990.', 'https://fr.wikipedia.org/wiki/Pac-Man'),
  ('Q2470724', 'WWF WrestleMania est un jeu vidéo de catch développé par Rare et édité par Acclaim commercialisé sur la Nintendo Entertainment System (NES) en 1989 aux États-Unis et en Europe. Il s''agit du tout premier jeu vidéo de catch sur console à exploiter une licence officielle de la World Wrestling Federation (WWF, aujourd''hui WWE). Bien que le jeu utilise le slogan "Bigger, Badder, Better" de WrestleMania III, sa commercialisation se rapproche plutôt durant la période de WrestleMania V.

WWF WrestleMania s''est avéré décevant, même pour les moyens techniques limités de l''époque, surtout si on le comparait à Pro Wrestling, qui bien que ne mettant pas en scène des superstars du catch existantes, se voulait beaucoup plus amusant et mieux réalisé.', 'https://fr.wikipedia.org/wiki/WWF_WrestleMania_(jeu_vid%C3%A9o,_1989)'),
  ('Q2466720', 'Tecmo World Wrestling (Gekitou Puroresu!!: Toukon Densetsu au Japon) est un jeu vidéo de catch sorti en 1989 sur Nintendo Entertainment System. Le jeu a été développé et édité par Tecmo.', 'https://fr.wikipedia.org/wiki/Tecmo_World_Wrestling'),
  ('Q2490098', 'Menace Beach est un jeu vidéo de plate-forme non licencié développé par Color Dreams et édité par Color Dreams en Europe et en Amérique du Nord et par Hacker International en Asie. Le jeu est sorti en 1990 sur NES et en 1992 dans la compilation Maxivision 15-in-1 de American Video Entertainment. Il est sorti en Asie sous le nom de Miss Peach World.', 'https://fr.wikipedia.org/wiki/Menace_Beach'),
  ('Q2459946', 'Arkanoid: Revenge of Doh est un jeu d''arcade de type casse-briques développé et édité par Taito en 1987. Le jeu fut porté sur divers plates-formes. C’est le deuxième jeu de la série Arkanoid.', 'https://fr.wikipedia.org/wiki/Arkanoid:_Revenge_of_Doh'),
  ('Q2465356', 'SilkWorm est un jeu vidéo de type shoot them up à défilement horizontal développé et manufacturé par Tecmo en 1988 sur borne d''arcade. Le jeu a été adapté sur Amiga, Atari ST, Amstrad CPC, Commodore 64, ZX Spectrum en 1989 et sur Nintendo Entertainment System en 1990. Il a donné suite à SWIV en 1991.', 'https://fr.wikipedia.org/wiki/SilkWorm'),
  ('Q2468410', 'Shinobi est un jeu vidéo d''action développé par Sega AM1, sorti en 1987 sur borne d''arcade. Le jeu a été porté sur Master System en 1988 puis sur diverses consoles et micro-ordinateurs.

Il s''agit du premier épisode de la série.', 'https://fr.wikipedia.org/wiki/Shinobi_(jeu_vid%C3%A9o,_1987)'),
  ('Q2473951', 'The Adventures of Rocky and Bullwinkle and Friends est un jeu vidéo de plates-formes développé par Imagineering sur Game Boy et Radical Entertainment sur NES, édité par THQ en 1992. Le jeu est porté par Imagineering un an après sur Super Nintendo et Mega Drive.

Le jeu est basé sur le dessin animé The Rocky and Bullwinkle Show.', 'https://fr.wikipedia.org/wiki/The_Adventures_of_Rocky_and_Bullwinkle_and_Friends'),
  ('Q2495808', 'Crisis Force est un shoot them up à scrolling vertical sorti en 1991 sur Famicom. Le jeu a été édité par Konami et est seulement sorti au Japon.', 'https://fr.wikipedia.org/wiki/Crisis_Force'),
  ('Q2491737', 'Action in New York, ou Final Mission au Japon, ou bien S.C.A.T.: Special Cybernetic Attack Team en Amérique du Nord, est un jeu vidéo de type shoot them up développé par l''entreprise japonaise Natsume. Il est sorti sur la Famicom en 1990, sur NES US en 1991 et sur NES EUR en 1992.', 'https://fr.wikipedia.org/wiki/Action_in_New_York'),
  ('Q2513509', 'Pro Wrestling est un jeu vidéo de catch développé par Nintendo. Il est sorti au Japon en 1986 sur Famicom Disk System, puis en 1987, aux États-Unis et en Europe, sur Nintendo Entertainment System.

Le jeu fut codé par Masato Matsuda pour Nintendo, après qu''un portage de Exciting Hour ne tombe à l''eau; Matsuda créa et programma le jeu seul, et un de ses amis créa les personnages et leurs animations de prises. Matsuda quitta Nintendo avant la sortie du jeu pour travailler chez TRY, qui devint rapidement Human Entertainment; là-bas, il créa la série de jeux Fire Pro Wrestling, qui commença avec Fire Pro Wrestling Combination Tag en 1989.', 'https://fr.wikipedia.org/wiki/Pro_Wrestling_(jeu_vid%C3%A9o,_1986,_Nintendo)'),
  ('Q2498075', 'Blue Shadow, connu au Japon sous le nom Yami no Shigotonin KAGE, ou bien Shadow of the Ninja en Amérique du Nord, est un jeu vidéo d''action - plates-formes développé et édité par Natsume en 1990 sur la console Nintendo.', 'https://fr.wikipedia.org/wiki/Blue_Shadow'),
  ('Q2517563', 'Mario a disparu ! (ou Mario Is Missing!) est un jeu vidéo éducatif de géographie sur les villes du monde, sorti sur MS-DOS en 1992, sur Super Nintendo et Nintendo Entertainment System en 1993. Le personnage principal est pour la première fois Luigi. Les versions MS-DOS et Super Nintendo ont été développés par The Software Toolworks, alors que Radical Entertainment s''occupa de la version NES. Les trois versions ont été éditées par Mindscape.', 'https://fr.wikipedia.org/wiki/Mario_a_disparu_!'),
  ('Q2532009', 'Wrecking Crew est un jeu vidéo développé par Nintendo R&D1 et Intelligent Systems et édité par Nintendo.

Le joueur contrôle Mario, lequel doit détruire toutes les briques d''un bâtiment sans se faire toucher par les ennemis et éviter Spike, le méchant du jeu.

Il s''agit du premier jeu imaginé par Yoshio Sakamoto.', 'https://fr.wikipedia.org/wiki/Wrecking_Crew'),
  ('Q2521832', 'Ultima V: Warriors of Destiny est un jeu vidéo de rôle développé et publié par Origin Systems en 1988. Le jeu est le cinquième de la série de jeux de rôle Ultima créée par Richard Garriott.', 'https://fr.wikipedia.org/wiki/Ultima_V:_Warriors_of_Destiny'),
  ('Q2530723', 'Metroid est un jeu vidéo d''action-aventure développé par Nintendo R&D1 et Intelligent Systems, et édité par Nintendo en 1986 sur Famicom Disk System, l''extension de la Famicom. Il sort à partir de 1987 sur NES en Amérique du Nord, puis dans le reste du monde et en arcade cette même année. Le jeu est tardivement réédité à partir de 2004 sur Game Boy Advance au Japon, en Amérique du Nord et en Europe. Il est réédité en version dématérialisée sur les consoles Wii en 2007, 3DS en 2012 et Wii U en 2013, mais aussi sous forme de bonus dans les jeux Metroid Prime et Zero Mission.', 'https://fr.wikipedia.org/wiki/Metroid_(jeu_vid%C3%A9o)'),
  ('Q2354748', 'Yo! Noid est un jeu vidéo de plates-formes-action développé par Now Production et édité par Capcom en novembre 1990 sur PlayChoice-10 sous licence Nintendo.', 'https://fr.wikipedia.org/wiki/Yo!_Noid'),
  ('Q2353348', 'Karateka est un jeu vidéo de combat créé en 1984 par Jordan Mechner, le créateur de Prince of Persia (1989). Le jeu a initialement été développé sur Apple II et fut porté sur de nombreux supports.

Il s''agit du premier jeu de Mechner jamais édité. Il l''a développé alors qu''il était encore étudiant à l''Université Yale. Le jeu s''est fait remarquer par la presse spécialisée pour la grosseur des sprites et la fluidité de l''animation. Il se vend à plus de 500 000 exemplaires en 1984.', 'https://fr.wikipedia.org/wiki/Karateka_(jeu_vid%C3%A9o)'),
  ('Q88921', 'Cabal est un jeu vidéo de tir à la troisième personne développé par TAD, sorti en 1988 sur borne d''arcade. Il a été adapté sur divers supports familiaux et a connu une suite: Blood Bros. (1990)', 'https://fr.wikipedia.org/wiki/Cabal_(jeu_vid%C3%A9o)'),
  ('Q88759', 'Bubble Bobble est un jeu vidéo de plates-formes développé par la société japonaise Taito, sorti en 1986. À l’origine commercialisé sur borne d’arcade, le jeu a été porté sur de nombreux systèmes familiaux et a connu plusieurs suites. L’univers de jeu a aussi été décliné dans une autre série, Puzzle Bobble (Bust-a-Move), des jeux de puzzle également très populaires.', 'https://fr.wikipedia.org/wiki/Bubble_Bobble_(jeu_vid%C3%A9o)'),
  ('Q88240', '720° est un jeu vidéo de skateboard sorti en 1986 sur borne d''arcade et qui fut ensuite porté sur Amstrad CPC, Commodore 64, Game Boy Color, Nintendo Entertainment System et ZX Spectrum. Développé par Atari Games, le jeu a été conçu par John Salwitz et Dave Ralston.', 'https://fr.wikipedia.org/wiki/720%C2%B0'),
  ('Q88855', 'California Games est un jeu vidéo de sport multi-épreuves développé et édité par Epyx, sorti en 1987 sur Commodore 64 et Apple II. Le jeu a été porté sur de nombreux ordinateurs personnels et consoles de jeu.

Dans la lignée des jeux du même développeur Summer Games (1984) et Winter Games (1985), California Games propose différentes épreuves sportives populaires sous le soleil de Californie.', 'https://fr.wikipedia.org/wiki/California_Games'),
  ('Q88582', 'Heroes of the Lance est un jeu vidéo d''action et de plates-formes développé par U.S. Gold et publié par Strategic Simulations (SSI) en 1988 sur Amiga, Amstrad CPC, Atari ST, Commodore 64, MS-DOS, ZX Spectrum. Le jeu a ensuite été porté sur PC-88 en 1989 puis sur NES, MSX2 et Sega Master System en 1991.

Même s''il s''agit d''un jeu d''action et de plates-formes, Heroes of the Lance est basé sur le jeu de rôle fantasy Donjons et Dragons, publié par TSR. Il est le premier volet d’une trilogie se déroulant dans l’univers de Lancedragon, deux suites (baptisées Dragons of Flame et Shadow Sorcerer) ayant respectivement été publiées en 1989 et 1991.', 'https://fr.wikipedia.org/wiki/Heroes_of_the_Lance'),
  ('Q88947', 'Renegade est un jeu d''arcade de type beat them all développé par Technos Japan en 1986. Le jeu a été adapté sur Amiga, Amstrad CPC, Apple II, Atari ST, Commodore 64, DOS, Master System, NES, Thomson et ZX Spectrum.

Pionnier du jeu de combat à progression, le jeu préfigure la série Double Dragon.', 'https://fr.wikipedia.org/wiki/Renegade_(jeu_vid%C3%A9o)'),
  ('Q2748771', 'Dr. Chaos est un jeu vidéo de plate-forme sorti en 1987 sur Famicom Disk System au Japon et en 1988 sur Nintendo Entertainment System aux États-Unis. Le jeu a été édité par Pony Canyon au Japon et par FCI aux États-Unis.', 'https://fr.wikipedia.org/wiki/Dr._Chaos'),
  ('Q2749049', 'Goal! est un jeu vidéo de football développé et édité par Jaleco en 1988 sur Nintendo Entertainment System.

Le jeu consiste à disputer et remporter la Coupe du monde de football.', 'https://fr.wikipedia.org/wiki/Goal!_(jeu_vid%C3%A9o,_1988)'),
  ('Q2746198', 'Rolling Thunder est un jeu vidéo d''action, de type run and gun en vue de profil, développé et commercialisé par Namco en 1986 sur borne d''arcade. Le jeu a été adapté sur systèmes familiaux.', 'https://fr.wikipedia.org/wiki/Rolling_Thunder_(jeu_vid%C3%A9o)'),
  ('Q2742194', 'Arch Rivals est un jeu vidéo de basket-ball développé par Bally Midway en 1989 sur borne d''arcade. Le jeu a été adapté sur Nintendo Entertainment System en 1990 et sur Game Gear et Mega Drive en 1992.

Le jeu transforme les règles du basket-ball pour en faire un jeu violent.', 'https://fr.wikipedia.org/wiki/Arch_Rivals'),
  ('Q2732183', 'Circus Charlie est un jeu vidéo d''action développé et édité par Konami, sorti en 1984 sur borne d''arcade, Commodore 64, MSX, ColecoVision, NES et SG-1000.', 'https://fr.wikipedia.org/wiki/Circus_Charlie'),
  ('Q1935772', 'Disney''s Chip''n Dale: Rescue Rangers 2 est un jeu vidéo de plates-formes par Capcom sur Nintendo Entertainment System en 1993. Il est tiré de la série télévisée d''animation Tic et Tac, les rangers du risque créée par Disney.

Le 16 mars 2017, Capcom annonce la ressortie le 18 avril de plusieurs titres phares 8 bits de Disney Interactive des années 1990 sous le nom The Disney Afternoon Collection sur Xbox One, PlayStation 4 et PC dont Disney''s Darkwing Duck, Disney''s DuckTales, Disney''s DuckTales 2, Disney''s Chip''n Dale: Rescue Rangers, Disney''s Chip''n Dale: Rescue Rangers 2 et Disney''s TaleSpin.', 'https://fr.wikipedia.org/wiki/Disney%27s_Chip%27n_Dale:_Rescue_Rangers_2'),
  ('Q1920147', 'Super Contra est un jeu vidéo d''action de type run and gun développé et édité par la société japonaise Konami en 1988 sur borne d''arcade.

Il est porté sur Nintendo Entertainment System en 1990 avec comme titre Super C en Amérique du Nord. Puis en 1992, la version européenne est distribuée sous le nom Probotector II: Return of the Evil Forces. Il s''agit du deuxième opus distribué sur NES.

Super Contra et sa version NES nord-américaine Super C font tous les deux partie de la compilation Contra Anniversary Collection parue en 2019 pour PC, PlayStation 4, Xbox One et Nintendo Switch. Quelque temps après la sortie initiale de la compilation, les versions japonaises ont été ajoutées à la collection lors d''une mise à jour gratuite de Konami.', 'https://fr.wikipedia.org/wiki/Probotector_II:_Return_of_the_Evil_Forces'),
  ('Q1932678', 'Disney''s Chip''n Dale: Rescue Rangers est un jeu vidéo de plates-formes développé et édité par Capcom en 1990 sur NES. Ce jeu basé sur la série télévisée d''animation Tic et Tac, les rangers du risque, est sorti sous licence Nintendo et les personnages sont sous licence The Walt Disney Company. Le jeu d''arcade est porté sur PlayChoice-10 en 1990.

Le 16 mars 2017, Capcom annonce la ressortie le 18 avril de plusieurs titres phares 8 bits de Disney Interactive des années 1990 sous le nom The Disney Afternoon Collection sur Xbox One, PlayStation 4 et PC dont Disney''s Darkwing Duck, Disney''s DuckTales, Disney''s DuckTales 2, Disney''s Chip''n Dale: Rescue Rangers, Disney''s Chip''n Dale: Rescue Rangers 2 et Disney''s TaleSpin.', 'https://fr.wikipedia.org/wiki/Disney%27s_Chip%27n_Dale:_Rescue_Rangers'),
  ('Q2774261', 'Golgo 13: Top Secret Episode est un jeu vidéo d''action édité et développé par Vic Tokai. Il est sorti sur Nintendo Entertainment System en 1988. Le jeu est basé sur le manga Golgo 13.

Le joueur prend le rôle de Golgo 13, un assassin dont l''objectif est d''éliminer le dirigeant du groupe Drek. Durant son aventure, Golgo 13 doit voyager à plusieurs endroits, comme Berlin-Est, Athènes et l''île Alexandre-Ier, qui se situe en Antarctique.', 'https://fr.wikipedia.org/wiki/Golgo_13:_Top_Secret_Episode'),
  ('Q2795318', 'Crystal Mines est un jeu vidéo de genre puzzle-labyrinthe en deux dimensions, développé et édité par Color Dreams en 1989 sur la console Nintendo uniquement en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Crystal_Mines'),
  ('Q2757019', 'Volleyball est un jeu vidéo de sport développé par Nintendo R&D1 et édité par Nintendo, sorti en 1986 sur Nintendo Entertainment System.

C''est une adaptation du jeu Attack Four créé par Pax Softnica pour le MSX.', 'https://fr.wikipedia.org/wiki/Volleyball_(jeu_vid%C3%A9o)'),
  ('Q2752616', 'Pac-Land est un jeu vidéo sorti sur borne d''arcade en 1984. Il a été développé par Namco et est basé sur la série animée de Hanna-Barbera Productions.', 'https://fr.wikipedia.org/wiki/Pac-Land'),
  ('Q2783606', 'Impossible Mission 2 est un jeu vidéo de plate-forme développé par Novotrade et édité par Epyx en 1988. Il est aussi sorti sur Amiga, Amstrad CPC, Atari ST, Commodore 64, DOS, NES et ZX Spectrum. Il s''agit de la suite directe de Impossible Mission (1984) et en reprend le principe, tout en le développant.', 'https://fr.wikipedia.org/wiki/Impossible_Mission_2'),
  ('Q2786897', 'Victory Road (Dogosoken au Japon) est un jeu vidéo de type run and gun développé et édité par SNK, sorti en 1986 sur borne d''arcade (sur le système Psycho Soldier).', 'https://fr.wikipedia.org/wiki/Victory_Road_(jeu_vid%C3%A9o)'),
  ('Q2780594', 'Baseball Stars: Be a Champ! est un jeu vidéo de sport de baseball développé et commercialisé par SNK en 1989 sur borne d''arcade PlayChoice-10.', 'https://fr.wikipedia.org/wiki/Baseball_Stars:_Be_a_Champ!'),
  ('Q2364724', 'Blaster Master est un jeu vidéo développé et édité par Sunsoft en 1988 sur la console Nintendo Entertainment System. Il s''agit d''une adaptation du titre japonais Chō Wakusei Senki Metafight sur Famicom. Si les graphismes et le gameplay ont été conservés, le scénario a été modifié pour le marché américain.', 'https://fr.wikipedia.org/wiki/Blaster_Master'),
  ('Q2381494', 'Disney''s Darkwing Duck est un jeu d''action Plates-Formes en 2D tiré de la sérié télévisée Myster Mask créée par Disney. Le jeu fut développé et édité par Capcom sur Nintendo Entertainment System en 1992 et sur Game Boy en 1993. Il est distinct du jeu du même nom sorti en 1992 sur PC-Engine par Turbo Technologies, Inc..

Le 16 mars 2017, Capcom annonce la ressortie le 18 avril de plusieurs titres phares 8 bits de Disney Interactive des années 1990 sous le nom The Disney Afternoon Collection sur Xbox One, PlayStation 4 et PC dont Disney''s Darkwing Duck, Disney''s DuckTales, Disney''s DuckTales 2, Disney''s Chip''n Dale: Rescue Rangers, Disney''s Chip''n Dale: Rescue Rangers 2 et Disney''s TaleSpin.', 'https://fr.wikipedia.org/wiki/Disney%27s_Darkwing_Duck'),
  ('Q1995635', 'Gun.Smoke est un jeu vidéo développé et édité par Capcom. Il s''agit d''un shoot them up de type run and gun bâti sur le même modèle que 1942 (l''avion chasseur laissant ici la place à un chasseur de primes). Il est sorti en 1985 sur système d''arcade Commando. Il se déroule dans un décor de western où le personnage principal, un chasseur de primes nommé Billy Bob, poursuit de dangereux criminels.', 'https://fr.wikipedia.org/wiki/Gun.Smoke'),
  ('Q2001519', 'TwinBee est un jeu vidéo de type shoot ''em up développé et édité par Konami, sorti en 1985 sur borne d''arcade Konami GX400, Windows, MSX, X68000, NES, Wii, PlayStation 4, Xbox 360, Game Boy Advance, Nintendo DS, Nintendo 3DS, PlayStation Portable et téléphone mobile.', 'https://fr.wikipedia.org/wiki/TwinBee_(jeu_vid%C3%A9o)'),
  ('Q2000330', 'North and South est un jeu vidéo développé et édité par Infogrames. Mélange de stratégie au tour par tour et d’action, il est sorti à la fin des années 1980 sur Amiga, Atari ST, Commodore 64, DOS, Amstrad CPC, ZX Spectrum et NES. Adaptation de la bande dessinée Les Tuniques bleues, le jeu a pour toile de fond la Guerre de Sécession.

En juin 2012, l''éditeur Anuman Interactive lance un remake du jeu d''origine, doté de nouveaux graphismes, sur PC/Mac, iPhone, iPad et Android sous le titre Les Tuniques bleues: Nord vs Sud.', 'https://fr.wikipedia.org/wiki/North_and_South_(jeu_vid%C3%A9o)'),
  ('Q1992811', 'The Adventures of Bayou Billy, connu au Japon sous le nom de Mad City, est un jeu vidéo d''action de Konami, sorti sur NES en 1988 au Japon, en 1989 aux États-Unis et en Europe en 1991.', 'https://fr.wikipedia.org/wiki/The_Adventures_of_Bayou_Billy'),
  ('Q2386654', 'Jordan vs. Bird: One-on-One (parfois Jordan vs. Bird: Super One on One) est un jeu vidéo de basket-ball sorti en 1988 et fonctionne sur Mega Drive, Commodore 64, DOS, Nintendo Entertainment System et Game Boy. Le jeu a été développé et édité par Electronic Arts.

Il tient son nom de joueurs Michael Jordan et Larry Bird.', 'https://fr.wikipedia.org/wiki/Jordan_vs._Bird:_One-on-One'),
  ('Q2398028', 'Gemfire, appelé Royal Blood au Japon, est un jeu vidéo de rôle et de stratégie sorti en 1991 et fonctionne sur DOS, Mega Drive, MSX, Nintendo Entertainment System et Super Nintendo. Le jeu a été développé et édité par Koei.', 'https://fr.wikipedia.org/wiki/Gemfire'),
  ('Q2399220', 'Adventures in the Magic Kingdom est un jeu vidéo de plates-formes, développé et édité par Capcom, sorti en 1990 sur Nintendo Entertainment System.', 'https://fr.wikipedia.org/wiki/Adventures_in_the_Magic_Kingdom'),
  ('Q2383859', 'The Goonies II est un jeu vidéo pour la Nintendo Entertainment System, sorti en 1987, développé et édité par Konami.

Il est la suite du premier jeu The Goonies sorti en 1986 sur console uniquement au Japon. En Amérique du Nord, le premier jeu était sorti sur Vs. System et PlayChoice-10 mais pas sur la Nintendo Entertainment System. Cela a conduit beaucoup de gens à l''extérieur du Japon à croire que The Goonies II était censé être une suite du film Les Goonies. L''intrigue, cependant, se prête comme un possible deuxième chapitre de ce film. En tant que Mikey, votre quête est de sauver les six autres Goonies et Annie la sirène qui ont été enlevés par le gang Fratelli — récemment évadé de prison une fois de plus.', 'https://fr.wikipedia.org/wiki/The_Goonies_II'),
  ('Q2002828', 'Bomberman II (Dynablaster en Europe) est un jeu vidéo d''action et de labyrinthe développé et édité par Hudson Soft, sorti en 1991 sur NES.', 'https://fr.wikipedia.org/wiki/Bomberman_II'),
  ('Q2008751', 'The Simpsons: Bartman Meets Radioactive Man est un jeu vidéo sorti en décembre 1992 sur NES et Game Gear. Développé par Imagineering et édité par Acclaim, ce jeu est basé sur la série télévisée Les Simpson.', 'https://fr.wikipedia.org/wiki/The_Simpsons:_Bartman_Meets_Radioactive_Man'),
  ('Q91268', 'Archon: The Light and the Dark est un jeu vidéo de stratégie au tour par tour développé par Free Fall Associates et publié par Electronic Arts en 1983. Il reprend le principe des échecs en y ajoutant des phases de combat. Le jeu est à l''origine développé pour l''Atari 8-bit puis est porté sur Apple II, Commodore 64, Amstrad CPC, ZX Spectrum, Amiga, IBM PC, Macintosh, PC-88 et NES.', 'https://fr.wikipedia.org/wiki/Archon:_The_Light_and_the_Dark'),
  ('Q134138', 'Le Roi lion (The Lion King) est un jeu vidéo de plates-formes édité par Virgin Interactive en 1994. L''univers du jeu est tiré du dessin animé Le Roi lion des studios Disney. Le jeu a été décliné sur de nombreuses plateformes par des développeurs variés.

Le jeu est publié le 9 novembre 1994 en Amérique du Nord sur Super Nintendo et Genesis. En Europe, il est d''abord publié sur Mega Drive le 4 novembre 1994 puis sur Super Nintendo le 11 novembre 1994. Au Japon, Lion King est publié le sur Mega Drive et Super Nintendo le 9 décembre 1994.', 'https://fr.wikipedia.org/wiki/Le_Roi_lion_(jeu_vid%C3%A9o,_1994)'),
  ('Q90994', 'Chase H.Q. est un jeu vidéo de combat motorisé et de course développé et édité par Taito, sorti en 1988 sur borne d''arcade, Amiga, Amstrad CPC, Atari ST, Commodore 64, FM Towns, MSX, X68000, ZX Spectrum, PC-Engine, Master System, Mega Drive, Saturn, NES, Super Nintendo, Game Boy, Game Boy Color et Game Gear.

Le policier Tony Gibson, avec son partenaire Raymond Broady, membres du "Chase Special Investigation Department", avec leur Porsche 928 noire équipée d’un turbo, doivent rattraper et empêcher des criminels de fuir à bord de leur véhicule.', 'https://fr.wikipedia.org/wiki/Chase_H.Q.'),
  ('Q130641', 'Baby Boomer est un jeu vidéo de tir non licencé, édité par Color Dreams, développé par Jim Meuer et sorti en 1989 sur NES. C''est le premier jeu de Color Dreams et comme leurs autres jeux non licenciés, la cartouche du jeu est bleu clair et n''a pas le même design que les cartouches traditionnelles de la NES.', 'https://fr.wikipedia.org/wiki/Baby_Boomer_(jeu_vid%C3%A9o)'),
  ('Q91282', 'Arkanoid est un jeu d’arcade de type casse-briques développé par Taito en 1986 et porté sur de nombreux supports familiaux. C’est le premier jeu de la série Arkanoid. Le jeu est basé sur le même principe que Breakout d''Atari Inc. (1976).', 'https://fr.wikipedia.org/wiki/Arkanoid_(jeu_vid%C3%A9o)'),
  ('Q91220', 'Yie Ar Kung-Fu est un jeu vidéo de combat développé par Konami, sorti sur borne d''arcade en 1985. Il a été porté sur divers consoles de jeu et micro-ordinateurs 8 bits.

Le jeu a eu une suite en 1986, Yie Ar Kung-Fu II.', 'https://fr.wikipedia.org/wiki/Yie_Ar_Kung-Fu'),
  ('Q146124', 'Excitebike est un jeu vidéo de course de moto développé et édité par Nintendo. Il est sorti en 1984 au Japon sur Famicom, en 1985 en Amérique du Nord sur Nintendo Entertainment System et en 1986 en Europe sur la même console.', 'https://fr.wikipedia.org/wiki/Excitebike'),
  ('Q2042716', 'Guerrilla War (Guevara au Japon) est un jeu d''arcade développé et édité par SNK, sorti en mars 1988 sur borne d''arcade (sur le système Psycho Soldier). C''est un shoot them up du style run and gun.', 'https://fr.wikipedia.org/wiki/Guerrilla_War'),
  ('Q2044254', 'Solar Jetman: Hunt for the Golden Warpship est un jeu vidéo de shoot ''em up développé par Zippo Games et Rare et publié par Tradewest sur NES le 14 octobre 1990 en Amérique du Nord et le 26 septembre 1991 en Europe. Il a également été publié sur les systèmes d’arcades PlayChoice-10 en 1990 aux États-Unis. C’est le troisième jeu de la série Jetman après Jetpac et Lunar Jetman publiés en 1983 par Ultimate Play the Game. Le joueur y incarne Jetman, un astronaute devant manœuvrer son vaisseau spatial dans les cavernes de différentes planètes afin de retrouver les pièces du Golden Warpship.

Le jeu a été en grande partie développé par Zippo Games sous le titre de Iota avant que Rare ne leur impose d’en faire une suite à Jetman. En plus de la version NES, des versions ZX Spectrum, Commodore 64 et Atari ST du jeu ont également été développées mais celles-ci n’ont jamais été publiées du fait du faible succès de la version originale. À sa sortie, le jeu reçoit pourtant un accueil plutôt positif de la presse spécialisée, les critiques saluant notamment ses graphismes mais regrettant la trop grande difficulté du jeu. En 2015, il a été republié dans une compilation publiée sous le titre Rare Replay sur Xbox One. Le jeu devient ensuite disponible à partir du 4 juillet 2024 sur le service Nintendo Switch Online.', 'https://fr.wikipedia.org/wiki/Solar_Jetman'),
  ('Q2045651', 'Tag Team Match: M.U.S.C.L.E. est un jeu vidéo inspiré du manga Muscleman, développé par TOSE et édité par Bandai en 1985 sur Famicom.', 'https://fr.wikipedia.org/wiki/Tag_Team_Match:_MUSCLE'),
  ('Q2045111', 'Micro Machines est un jeu vidéo de course développé et édité par Codemasters, sorti en 1991 sur NES. Le jeu a été adapté à partir de 1993 sur Amiga, CD-i, DOS, Master System, Mega Drive, Super Nintendo, Game Boy et Game Gear.', 'https://fr.wikipedia.org/wiki/Micro_Machines_(jeu_vid%C3%A9o,_1991)'),
  ('Q1980593', 'Road Fighter est un jeu vidéo de combat motorisé développé et édité par Konami à partir de 1984 sur borne d''arcade, MSX, Windows, NES, Xbox 360 et téléphone mobile.

Il a pour suite Midnight Run: Road Fighter 2.', 'https://fr.wikipedia.org/wiki/Road_Fighter'),
  ('Q1990991', 'Toobin'' est un jeu vidéo de sport développé par Atari Games et édité par Domark et Harmony Gold, sorti en 1988 sur borne d''arcade, DOS, Amiga, Amstrad CPC, Atari ST, Commodore 64, MSX, ZX Spectrum, NES et Game Boy Color.

Il est basé sur le tubing, une activité sportive consistant à glisser sur un pneumatique.

Le jeu fait partie des compilations Arcade Party Pak (1999), Midway Arcade Treasures (2003) et Midway Arcade Origins (2012).', 'https://fr.wikipedia.org/wiki/Toobin%27'),
  ('Q1985756', 'RoboCop est un jeu vidéo d''action de type run and gun distribué par Data East sur borne d''arcade en 1988. Il est ensuite porté par Ocean Software sur divers ordinateurs. C''est un produit dérivé du film RoboCop sorti une année auparavant au cinéma.', 'https://fr.wikipedia.org/wiki/RoboCop_(jeu_vid%C3%A9o,_1988)'),
  ('Q1974580', 'Le Livre de la jungle (ou Walt Disney''s The Jungle Book) est un jeu vidéo de plate-forme de David Perry pour Virgin Interactive, sorti sur Mega Drive, Super Nintendo, DOS, Windows, Master System, Game Gear et NES en 1994, d''après le film Le Livre de la jungle de Disney, sorti 27 ans plus tôt.

Le style qui fera le succès de David Perry sur les consoles 16 bits est déjà reconnaissable (voir aussi Global Gladiators, Cool Spot, Earthworm Jim et Aladdin): les critiques ont souligné que l''animation est très réussie, fine et en avance sur son temps (le rendu est plus proche d''un dessin animé que d''un jeu vidéo de cette époque), les graphismes sont soignés.', 'https://fr.wikipedia.org/wiki/Le_Livre_de_la_jungle_(jeu_vid%C3%A9o)'),
  ('Q1977905', 'Mighty Final Fight est un jeu vidéo de type beat them all développé et édité par Capcom, sorti en 1993 sur NES.

Le jeu est intégré dans la compilation Capcom Classics Mini-Mix sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Mighty_Final_Fight'),
  ('Q1982008', 'Karnov, ou Karunofu au Japon, est un jeu vidéo d''action plates-formes en 2D, sorti en arcade en janvier 1987.

Il a été édité par sur NES, le 18 décembre 1987 au Japon, suivi de l''Amérique du Nord en 1988. Le personnage Karnov deviendra par la suite la mascotte de la société Data East.', 'https://fr.wikipedia.org/wiki/Karnov'),
  ('Q1194412', 'Street Gangs, plus connu au Japon sous le titre Downtown Nekketsu Monogatari, ou River City Ransom en Amérique du Nord, est un jeu vidéo de type beat them all développé par Technos Japan sur Nintendo.

Il est porté sur l''ordinateur Sharp X68000 en 1990, sur Super CD-ROM² en 1993, puis sur Game Boy Advance en 2004 avec le sous-titre EX.

Le jeu a connu une suite en 2017 sous le titre River City Ransom: Underground.', 'https://fr.wikipedia.org/wiki/Street_Gangs'),
  ('Q2881381', 'Balloon Kid est un jeu vidéo de plates-formes pour la Game Boy développé par Nintendo R&D1 et Pax Softnica et publié par Nintendo. Le jeu est d''abord sorti en Amérique en octobre 1990, puis en Europe le 31 janvier 1991; il n''est jamais sorti au Japon dans cette version. Il s''agit de la suite de Balloon Fight sorti en 1984. Vous incarnez Alice, une jeune fille dont le petit frère s''est envolé par hasard accroché à des ballons gonflés à l''hélium. Vous devez parcourir plusieurs niveaux pour tenter de le sauver.', 'https://fr.wikipedia.org/wiki/Balloon_Kid'),
  ('Q2565163', 'The Flintstones: The Rescue of Dino and Hoppy est un jeu vidéo de plates-formes, sorti en 1991 sur Nintendo Entertainment System par Taito. Le jeu est basé sur la série télévisée Les Pierrafeu.', 'https://fr.wikipedia.org/wiki/The_Flintstones:_The_Rescue_of_Dino_and_Hoppy'),
  ('Q1133627', 'Pool of Radiance est un jeu vidéo de rôle développé et publié par Strategic Simulations (SSI) en 1988. Il est la première adaptation en jeu vidéo du jeu de rôle médiéval-fantastique Donjons et Dragons publié par TSR. Il est également le premier volet d''une série d’une douzaine de jeux vidéo de rôle, généralement désignée par le titre Gold Box, publiés par Strategic Simulations et basés sur le même moteur de jeu. Le jeu se déroule dans l’univers fantastique des Royaumes oubliés, un décor de campagne de Donjons et Dragons, dans lequel le joueur contrôle un groupe d’aventuriers recrutés pour défendre la cité portuaire de Phlan contre une invasion de créatures démoniaques.', 'https://fr.wikipedia.org/wiki/Pool_of_Radiance'),
  ('Q2881676', 'Baltron est un shoot them up à défilement horizontal sorti en 1986 sur Famicom. Le jeu a été développé par Shouei System et édité par Toei Animation et est seulement sorti au Japon.', 'https://fr.wikipedia.org/wiki/Baltron'),
  ('Q205508', 'Ballblazer est un jeu vidéo d’action et de sport développé par Lucasfilm Games. Initialement commercialisé sur Atari 5200 et Atari 8-bit en mars 1984, le jeu est ensuite publié sur Amstrad CPC, Apple II, Commodore 64, TRS-80, MSX, NES et ZX Spectrum.

Dans le jeu, deux équipes, contrôlées par des joueurs ou par l''intelligence artificielle, s''affrontent dans un sport similaire au basketball ou au football. L''objectif est d''envoyer une balle flottante dans le but adverse.

En 1990, LucasArts et Rainbow Arts ont publié une suite, intitulée Masterblazer, sur Amiga, Atari ST et PC. Le jeu a également inspiré Space Football: One on One, développé par Triffix, qui est publié sur Super NES en 1992. Enfin, un remake du jeu baptisé Ballblazer Champions est publié le 31 mars 1997 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Ballblazer'),
  ('Q2533175', 'The Blues Brothers est un jeu vidéo développé et édité par Titus Software, sorti en 1991 et porté sur différents micro-ordinateurs et consoles dans les années qui ont suivi. C’est un jeu de plates-formes basé sur le film homonyme à propos du groupe de musique américain The Blues Brothers. Le jeu est sorti sur PC, Amstrad CPC, Amiga, Commodore 64 et Atari ST en 1991, puis sur NES en 1992 et sur la Game Boy en 1994. La musique du jeu est composée par Dimitri Yerasimos, plus connu sous le nom de Dimitri from Paris.

Une suite du jeu, intitulée The Blues Brothers: Jukebox Adventure, est sortie en 1993 sur PC et sur Super Nintendo, puis en 1994 sur la Game Boy.', 'https://fr.wikipedia.org/wiki/The_Blues_Brothers_(jeu_vid%C3%A9o)'),
  ('Q1142493', 'Kid Icarus est un jeu vidéo de plates-formes, le premier de la série qui porte son nom. Développé par Nintendo R&D1 et édité par Nintendo, le jeu est sorti sur Famicom Disk System en 1986 au Japon. Il sort ensuite sur Nintendo Entertainment System en 1987 aux États-Unis et en Europe. Une réédition sort au Japon en 2004 sur Game Boy Advance dans le cadre de la collection Famicom Mini. Le jeu est également ressorti, en février 2007, sur la Console virtuelle de la Wii.

Le développement de Kid Icarus, comme celui de Metroid — jeu avec lequel il partage beaucoup de points communs — a débuté après une période où Nintendo avait sorti un grand nombre de jeux à succès. Le titre a été produit par Gunpei Yokoi et réalisé par Satoru Okada; sa musique a été composée par Hirokazu Tanaka. L''action du jeu se déroule dans le Royaume des Anges et suit l''histoire de Pit, dont la quête va être de sauver le royaume et la déesse de la Lumière, Palutena, de Médusa, la déesse des Ténèbres.', 'https://fr.wikipedia.org/wiki/Kid_Icarus_(jeu_vid%C3%A9o)'),
  ('Q1194285', 'Mario and Yoshi, connu sous le nom de Yoshi en Amérique du Nord, est un jeu vidéo de puzzle sorti sur Nintendo Entertainment System et Game Boy en 1991.', 'https://fr.wikipedia.org/wiki/Mario_and_Yoshi'),
  ('Q1141199', 'Super Sprint est un jeu vidéo de course sorti en 1986 sur borne d''arcade. Le jeu a été développé et édité par Atari Games.

Le jeu fait partie de la série Sprint, débutée en 1976, commercialisé la même année que Championship Sprint.', 'https://fr.wikipedia.org/wiki/Super_Sprint'),
  ('Q2885286', 'Low G Man: The Low Gravity Man est un jeu vidéo d''action-plates-formes à thème futuriste développé par la société japonaise KID et édité par Taxan sur la console Nintendo en 1990/1991.', 'https://fr.wikipedia.org/wiki/Low_G_Man:_The_Low_Gravity_Man'),
  ('Q2886732', 'Bases Loaded 3 est un jeu vidéo de baseball sorti en 1990 sur Famicom au Japon et en 1991 sur NES aux États-Unis. Le jeu a été développé par TOSE et édité par Jaleco.', 'https://fr.wikipedia.org/wiki/Bases_Loaded_3'),
  ('Q2542131', 'Bucky O''Hare (バッキー オヘア (Bakkī Ohea)) est un jeu d''action plates-formes en 2D développé et édité par Konami en janvier 1992 sur NES. Il s''agit d''une adaptation du dessin animé Bucky O''Hare et du comics original, Bucky O''Hare. Ce jeu est différent du jeu de combat Bucky O''Hare sorti sur Arcade.', 'https://fr.wikipedia.org/wiki/Bucky_O%27Hare_(jeu_vid%C3%A9o)'),
  ('Q2557573', 'Plotting (ou Flipull) est un jeu vidéo d''arcade sorti en 1989 sur arcade. Le jeu a été développé et édité par Taito.', 'https://fr.wikipedia.org/wiki/Plotting'),
  ('Q2836804', 'Alien 3 est un jeu vidéo d''action et de plates-formes développé par Probe Software, sorti en 1992 et édité sur Amiga, Commodore 64, Game Gear, Master System, Mega Drive et Nintendo Entertainment System.

Le jeu se base sur le film Alien 3.', 'https://fr.wikipedia.org/wiki/Alien_3_(jeu_vid%C3%A9o)');

insert into import_summary (wikidata_id, summary, source) values
  ('Q2544020', 'Cybernoid: The Fighting Machine est un jeu vidéo de type shoot''em up publié par Hewson Consultants en 1988. Il est initialement développé par Raffaele Cecco sur ZX Spectrum et Amstrad CPC puis porté sur Commodore 64, Atari ST, Amiga et NES.', 'https://fr.wikipedia.org/wiki/Cybernoid'),
  ('Q2891548', 'Batman Returns est un jeu vidéo de type beat them all développé et édité par Konami sur Nintendo et Super Nintendo en 1993. Il est inspiré du film du même nom sorti en 1992, Batman Returns (Batman, le défi).', 'https://fr.wikipedia.org/wiki/Batman_Returns_(jeu_vid%C3%A9o,_1993)'),
  ('Q1188338', 'Mappy est un jeu vidéo de plates-formes créé par la société japonaise Namco, sorti en 1983 sur borne d''arcade. Le jeu a été conçu par Tōru Iwatani, l''auteur du célèbre Pac-Man. Le jeu a été adapté sur les ordinateurs FM-7, MSX, PC-88 et les consoles Famicom et Game Gear.

Mappy a eu une suite sur borne d''arcade en 1986, Hopping Mappy, et deux autres sur la console NES: Mappy-Land en 1986 et Mappy Kids en 1989.', 'https://fr.wikipedia.org/wiki/Mappy_(jeu_vid%C3%A9o)'),
  ('Q1192514', 'Galaxian est un jeu vidéo de type shoot ''em up de Namco, sorti en 1979 sur borne d''arcade Galaxian. Inspiré de Space Invaders, le jeu a été adapté sur de nombreux ordinateurs personnels et consoles de jeux.', 'https://fr.wikipedia.org/wiki/Galaxian'),
  ('Q2534019', 'The Simpsons: Bart vs. the World est un jeu vidéo sorti en 1991 et 1992 sur NES, Game Boy, Game Gear et Master System; et, en 1993 sur Atari ST et Amiga. Il a été développé par Imagineering et édité sur Acclaim.', 'https://fr.wikipedia.org/wiki/The_Simpsons:_Bart_vs._the_World'),
  ('Q2891857', 'Battleship est un jeu vidéo de stratégie au tour par tour édité et développé par Mindscape et sorti en 1993 sur NES et Game Gear.', 'https://fr.wikipedia.org/wiki/Battleship_(jeu_vid%C3%A9o,_1993)'),
  ('Q2877818', 'Babel no Tō est un jeu vidéo de puzzle sorti en 1986 sur Famicom. Le jeu a été développé puis édité par Namco.', 'https://fr.wikipedia.org/wiki/Babel_no_T%C5%8D'),
  ('Q2532676', 'Battletoads and Double Dragon: The Ultimate Team est jeu vidéo de type beat them all développé par Rare et édité par Tradewest en 1993. Le jeu est sorti initialement sur NES puis a ensuite été porté sur Mega Drive, Super Nintendo, et Game Boy.

Battletoads and Double Dragon: The Ultimate Team est un crossover entre Double Dragon de Technos Japan et Battletoads de Rare, bien que Technos soit peu impliqué dans le développement du jeu. Le joueur peut contrôler les personnages de la série Double Dragon, Billy et Jimmy Lee, ainsi que les trois crapauds humanoïdes du jeu Battletoads. Il est aussi le premier jeu Battletoads à proposer les trois crapauds en tant que personnages jouables. Le moteur et le game design sont directement basés sur la série Battletoads.', 'https://fr.wikipedia.org/wiki/Battletoads_and_Double_Dragon:_The_Ultimate_Team'),
  ('Q1115150', 'Commando est un jeu vidéo d''action en 2D développé par Capcom et sorti en 1985 sur système d''arcade Commando.

Archétype du run and gun en vue de dessus, Commando a influencé de nombreux jeux du genre comme Ikari Warriors ou Rambo: First Blood Part II.', 'https://fr.wikipedia.org/wiki/Commando_(jeu_vid%C3%A9o)'),
  ('Q1131067', 'Pipe Mania (Pipe Dream en Amérique du Nord) est un jeu vidéo de puzzle développé par The Assembly Line et sorti en 1989 sur Amiga puis porté sur borne d''arcade, DOS, Windows, Mac, Acorn Archimedes, Amstrad CPC, Apple II, Apple IIGS, Atari ST, BBC Micro, Commodore 64, PC-88, PC-98, Psion 3a, SAM Coupé, X68000, ZX Spectrum, NES, Super Nintendo et Game Boy.', 'https://fr.wikipedia.org/wiki/Pipe_Mania'),
  ('Q1098202', 'Quarth, ou Block Hole, est un jeu vidéo de type puzzle et shoot ''em up développé et édité par Konami, sorti en 1989 sur borne d''arcade, MSX2, NES, Game Boy et téléphone mobile.', 'https://fr.wikipedia.org/wiki/Quarth'),
  ('Q1114374', 'Captain Tsubasa est un jeu vidéo de football sorti en 1988 sur Famicom. Le jeu a été développé et édité par Tecmo, uniquement au Japon. Il est basé sur le manga et l''anime éponymes.

Le jeu a connu une adaptation sortie en 1992 sur Nintendo Entertainment System qui porte le nom de Tecmo Cup Football Game.', 'https://fr.wikipedia.org/wiki/Captain_Tsubasa_(jeu_vid%C3%A9o,_1988)'),
  ('Q1090190', 'F-1 Race est un jeu vidéo de course sorti en 1984 sur Nintendo Entertainment System et en 1990 sur Game Boy. Le jeu a été développé et édité par Nintendo.', 'https://fr.wikipedia.org/wiki/F-1_Race'),
  ('Q1198580', 'Dr. Mario est un jeu vidéo de puzzle développé et édité par Nintendo, sorti sur NES et Game Boy en 1990. Il a été conçu par Gunpei Yokoi et produit par Takahiro Harada; la musique a été composée par Hirokazu Tanaka.

Le jeu met en scène Mario mais ne reprend pas davantage l''univers de la série éponyme. Ce dernier est devenu docteur et doit éradiquer des virus mortels. Chaque niveau est constitué d''une bouteille contaminée par un certain nombre de virus, représentés à l''écran par des cases de couleurs. Pour les éliminer, Mario jette dans la bouteille des capsules de vitamines bicolores formées de deux blocs. Ces capsules disparaissent si quatre blocs de même couleur sont alignés. Le niveau est terminé lorsque tous les virus ont disparu.', 'https://fr.wikipedia.org/wiki/Dr._Mario_(jeu_vid%C3%A9o)'),
  ('Q1214813', 'Challenger est un jeu vidéo d''action et de plates-formes sorti en 1985 sur Famicom. Le jeu est développé et édité par Hudson Soft et sort seulement au Japon. Il est réédité en 2005 sur mobile et par Konami en 2013 sur Nintendo 3DS.', 'https://fr.wikipedia.org/wiki/Challenger_(jeu_vid%C3%A9o)'),
  ('Q1201014', 'Balloon Fight est un jeu vidéo de plates-formes développé par Nintendo R&D1 et édité par Nintendo, sorti sur arcade en 1984. La version arcade est appelée Vs. Balloon Fight. Le jeu sort ensuite sur Nintendo Entertainment System en 1985 au Japon, en 1986 en Amérique du Nord et en 1987 en Europe, en même temps que la sortie de la console dans cette région.

Son gameplay est similaire à celui de Joust, créé par la société américaine Williams Electronics, et sorti en 1982 sur borne d''arcade.', 'https://fr.wikipedia.org/wiki/Balloon_Fight'),
  ('Q1199765', 'Pooyan est un jeu d''arcade de type shoot them up publié par Konami en 1982.', 'https://fr.wikipedia.org/wiki/Pooyan'),
  ('Q2585558', 'The Legend of Kage est un jeu vidéo d''action à thème de ninja d''abord sorti sur borne d''arcade en 1985 puis porté sur consoles. Il a été développé et édité par Taito. Le jeu a connu une suite, The Legend of Kage 2 sur Nintendo DS.', 'https://fr.wikipedia.org/wiki/The_Legend_of_Kage'),
  ('Q2568153', 'Raid on Bungeling Bay est le premier jeu de Will Wright, sorti d''abord sur MSX puis sur Commodore 64 en 1984 et sur NES en 1985. Il sortit également sur borne d''arcade. Il fut édité par Brøderbund Software puis produit par Sony. Le jeu se jouait uniquement en solo; on y pilote un petit hélicoptère, le Thunder Chopper, qui devait détruire successivement six usines avec des bombes.', 'https://fr.wikipedia.org/wiki/Raid_on_Bungeling_Bay'),
  ('Q2592213', 'The Immortal est un jeu vidéo d''action-aventure et de rôle conçu par Will Harvey, développé par Sandcastle et publié par Electronic Arts en 1990. Le jeu est sorti sur Apple IIGS, Amiga, Atari ST, DOS, Mega Drive et NES. Il se déroule dans un univers médiéval-fantastique dans lequel le joueur incarne un magicien.', 'https://fr.wikipedia.org/wiki/The_Immortal_(jeu_vid%C3%A9o)'),
  ('Q1153074', 'City Connection est un jeu vidéo de plates-formes développé par Jaleco et sorti en 1985 sur borne d''arcade, Windows, MSX, ZX Spectrum, NES et téléphone mobile.', 'https://fr.wikipedia.org/wiki/City_Connection'),
  ('Q1182594', 'Defender of the Crown est un jeu vidéo développé par Master Designer et édité par Cinemaware en 1986. Précurseur du jeu de stratégie au tour par tour, il fut un succès marquant des micro-ordinateurs Amiga et Atari ST.

Il montre une carte de l''Angleterre coupée en une vingtaine de provinces.', 'https://fr.wikipedia.org/wiki/Defender_of_the_Crown'),
  ('Q1152426', 'Snake''s Revenge est un jeu vidéo d''action-infiltration développé et édité par Konami en 1990 sur Nintendo Entertainment System. Il se veut une suite de la version MSX de Metal Gear, la version nes n''ayant aucun appel a une suite après générique, et l''infiltration dans la base commencant par les notes du theme de Tara, présent uniquement sur MSX. Il faut cependant différencier ce jeu de Metal Gear 2: Solid Snake sur MSX2, véritable suite de Metal Gear et conçue par Hideo Kojima. Snake''s Revenge est plus orienté action que le premier opus et est considéré comme un épisode hors-série.', 'https://fr.wikipedia.org/wiki/Snake%27s_Revenge'),
  ('Q1154059', 'Kirby''s Adventure est un jeu vidéo de plate-forme sorti sur Nintendo Entertainment System développé par HAL Laboratory en 1993. Il a pour héros Kirby.

C''est le deuxième jeu mettant en scène la petite boule rose, mais le premier sur une console de salon de Nintendo. Kirby saute, vole, nage, gobe des ennemis et peut s''approprier leurs pouvoirs. Le joueur doit traverser 8 niveaux divisés en une dizaine de zones pour libérer le monde coloré de Dreamland de l''emprise du roi pingouin Dadidou. La cartouche intègre 3 sauvegardes et des mini-jeux en bonus.

C''est l''un des derniers jeux de la NES.', 'https://fr.wikipedia.org/wiki/Kirby%27s_Adventure'),
  ('Q1184959', 'Spelunker est un jeu vidéo de plates-formes développé par Tim Martin et MicroGraphic Image. Initialement publié par MicroGraphic Image (en) sur Atari 8-bit en 1983, il est ensuite réédité par Brøderbund Software sur Atari 8-bit et Commodore 64. Une version arcade du jeu est publiée en 1985. Il est ensuite publié sur NES en décembre 1985 au Japon puis en septembre 1987 en Amérique du Nord. Il est également porté sur MSX en 1986. Une suite baptisée Spelunker II: Yūsha e no Chōsen est publiée uniquement au Japon par Irem sur arcade et pour la NES le 18 septembre 1987. Le jeu est réédité sur la console virtuelle de la Wii en Amérique du Nord le 17 mars 2008 et en Europe le 5 septembre 2008. Spelunker HD pour le PlayStation Network est publié le 23 novembre 2010 par Tozai.', 'https://fr.wikipedia.org/wiki/Spelunker'),
  ('Q1152295', 'Snow Bros.: Nick and Tom est un jeu vidéo de plates-formes sorti en 1990 sur borne d''arcade. Le jeu a été développé et commercialisé par Toaplan.', 'https://fr.wikipedia.org/wiki/Snow_Bros.:_Nick_and_Tom'),
  ('Q1143274', 'Wizards and Warriors est un jeu vidéo de plates-formes développé par Rare et édité sur Nintendo Entertainment System par Acclaim Entertainment en décembre 1987 en Amérique du Nord, et en janvier 1990 en Europe. Le jeu est également publié au Japon par Jaleco en 1988 sous le titre Densetsu no Kishi Elrond. C’est le deuxième jeu développé pour la NES par le studio Rare après Slalom.

Dans le jeu, le joueur incarne le guerrier Kuros dans sa quête pour vaincre le sorcier démoniaque Malkil qui retient captive une princesse dans son château de la forêt d’Elrond. Pour cela, le joueur doit traverser des forêts, des tunnels et des souterrains en combattant des monstres et en évitant des pièges. À sa sortie, le jeu est très bien accueilli par la presse spécialisée qui salue ses graphismes, ses effets sonores, sa difficulté et son système de jeu.', 'https://fr.wikipedia.org/wiki/Wizards_and_Warriors'),
  ('Q1145485', 'Nintendo World Cup, connu au Japon sous le nom de Nekketsu Kōkō Dodgeball-bu: Soccer-hen est un jeu vidéo de football développé par Technos Japan et édité par Nintendo en 1990 pour sa console Nintendo Entertainment System et par la suite pour la console portable Game Boy. Ce jeu fait partie de la franchise Nekketsu Kōha Kunio-kun.

Le jeu original, retraduit en "Nekketsu High School Dodgeball Club - Soccer Story", sortira finalement traduit en anglais, en 2020 en occident via la compilation sur Nintendo Switch "Double Dragon & Kunio-kun: Retro Brawler Bundle"', 'https://fr.wikipedia.org/wiki/Nintendo_World_Cup'),
  ('Q1151856', 'Rygar est un jeu vidéo d''action/plates-formes développé et commercialisé par Tecmo en 1986 sur borne d''arcade. Il a été porté sur divers supports familiaux.

Le sous-titre pour la version arcade est Legendary Warrior.', 'https://fr.wikipedia.org/wiki/Rygar'),
  ('Q2933783', 'Clash at Demonhead, sorti au Japon sous le nom Dengeki Big Bang! est un jeu vidéo d''action et de plates-formes non linéaire en 2D développé et édité par Vic Tokai sur NES. Il est sorti le 27 janvier 1989 au Japon puis en Amérique du Nord en 1990.', 'https://fr.wikipedia.org/wiki/Clash_at_Demonhead'),
  ('Q2955894', 'Championship Pool est un jeu vidéo de billard sorti en 1993 et fonctionne sur Game Boy, Mega Drive, Nintendo Entertainment System et Super Nintendo. Le jeu a été développé par Bitmasters et édité par Mindscape.', 'https://fr.wikipedia.org/wiki/Championship_Pool'),
  ('Q2937645', 'Captain Planet and the Planeteers, aussi connu sous le titre Captain Planet, est un jeu vidéo d''action/plates-formes édité par Mindscape en 1991. Le jeu est sorti en plusieurs versions: une sur NES, une sur Amiga et Atari ST, une autre sur Amstrad CPC et ZX Spectrum, et une dernière sur Mega Drive.

Le jeu s''inspire de la série d''animation Capitaine Planète.', 'https://fr.wikipedia.org/wiki/Captain_Planet_and_the_Planeteers_(jeu_vid%C3%A9o)'),
  ('Q285402', 'Panic Restaurant, ou Wanpaku Kokkun no Gourmet World au Japon, est un jeu vidéo de plates-formes développé par EIM et édité par Taito en 1992 sur la console Nintendo.', 'https://fr.wikipedia.org/wiki/Panic_Restaurant'),
  ('Q240143', 'Maniac Mansion est un jeu d''aventure développé et édité par Lucasfilm Games. Initialement commercialisé sur Commodore 64 et Apple II en octobre 1987, le jeu est ensuite publié sur DOS en 1988, sur Amiga et Atari ST en 1989 puis sur NES en 1990. Il suit les aventures du jeune Dave Miller qui tente de sauver sa petite amie enlevée par un scientifique fou, le docteur Fred Edison, dont la famille est sous le contrôle d''une météorite qui s’est écrasée derrière leur maison vingt ans auparavant. Le joueur contrôle ses personnages grâce à une interface en pointer-et-cliquer et doit résoudre des énigmes pour avancer dans le jeu.', 'https://fr.wikipedia.org/wiki/Maniac_Mansion'),
  ('Q281924', 'Battle Tank est un jeu vidéo d''action développé par Imagineering, édité par Absolute Entertainment et sorti sur NES est octobre 1990 aux États-Unis. Le jeu est similaire à Battlezone, un jeu d''Atari.', 'https://fr.wikipedia.org/wiki/Battle_Tank'),
  ('Q2592852', 'Big Nose the Caveman est un jeu vidéo de plates-formes développé par Codemasters et édité par Camerica uniquement en Amérique du Nord en 1991 sur NES, puis plus tard sur Amiga et Atari ST.', 'https://fr.wikipedia.org/wiki/Big_Nose_the_Caveman'),
  ('Q2800857', 'Flight of the Intruder est un jeu vidéo de simulation de vol de combat développé par Rowan Software et édité par Spectrum HoloByte, sorti en 1990 sur DOS, Amiga, Atari ST et NES.

Le jeu est inspiré du roman du même nom qui a inspiré le film Le Vol de l''Intruder.', 'https://fr.wikipedia.org/wiki/Flight_of_the_Intruder_(jeu_vid%C3%A9o)'),
  ('Q2615980', 'Super Spike V''Ball, nommé US Championship V''Ball au Japon, est un jeu vidéo de beach-volley sorti en 1989 au Japon, en 1990 en Amérique du Nord et en 1992 en Europe. Ce jeu a été développé et édité par Technos Japan pour le Japon et édité par Nintendo pour l''Occident. Le jeu est ressorti ensuite sur une cartouche multi-jeux nommée Super Spike V''Ball / Nintendo World Cup uniquement en Amérique du Nord en 1990.', 'https://fr.wikipedia.org/wiki/Super_Spike_V%27Ball'),
  ('Q2604860', 'Fire Emblem Gaiden est un jeu vidéo de rôle tactique développé par Intelligent Systems et édité par Nintendo, sorti le 14 mars 1992 sur Famicom, exclusivement au Japon. C''est le second épisode de la série Fire Emblem et le dernier jeu de la série à avoir été édité sur Famicom.

Alors qu''une guerre éclate entre Rigel et Zofia, les deux royaumes de Valentia, deux amis d''enfance, Alm et Celica, tentent de rétablir la paix, respectivement en essayant de contrer la tentative d''invasion de Rigel, et de retrouver Mila, la Déesse Mère de la Terre portée disparue. Le joueur peut diriger ces deux armées simultanément, afin de faire progresser l''histoire et de restaurer la paix à Valentia, en recrutant de nombreux alliés en chemin.', 'https://fr.wikipedia.org/wiki/Fire_Emblem_Gaiden'),
  ('Q2796607', 'Ikari Warriors est un jeu vidéo d''action de type run and gun développé par la société japonaise SNK et commercialisé en 1986 sur borne d''arcade. Il a été adapté sur divers supports familiaux.', 'https://fr.wikipedia.org/wiki/Ikari_Warriors_(jeu_vid%C3%A9o)'),
  ('Q1308649', 'Skate or Die! est un jeu vidéo de simulation de skateboard édité par Electronic Arts sur ordinateur personnel ZX Spectrum, Commodore 64, Amstrad CPC, Apple II, Atari ST et console NES (sur NES développé par Konami et édité par Ultra Games) en 1988.', 'https://fr.wikipedia.org/wiki/Skate_or_Die!'),
  ('Q2815984', '3-D WorldRunner (とびだせ大作戦 (Tobidase Daisakusen), en japonais) est un jeu vidéo d''action développé par Square et édité par DOG (un label de Square), sorti le 12 mars 1987 au Japon sur Famicom Disk System. Il est ensuite publié en septembre 1987 par Acclaim Entertainment aux États-Unis sur Nintendo Entertainment System.

Le joueur endosse le rôle de WorldRunner (connu sous le nom de Jack au Japon), un cow-boy spatial en mission pour sauver plusieurs planètes envahies par des monstres ressemblant à des serpents.

3-D WorldRunner est conçu par Hironobu Sakaguchi, Nobuo Uematsu et Nasir Gebelli. Ces personnes formeront le noyau de l’équipe qui développera le jeu de rôle populaire Final Fantasy. Ils ont également développé JJ, la suite de 3-D WorldRunner.', 'https://fr.wikipedia.org/wiki/3-D_WorldRunner'),
  ('Q2593819', 'Mickey Mousecapade, ou simplement Mickey Mouse en dehors des États-Unis, est un jeu de plates-formes développé par Hudson Soft et édité en 1987 par le développeur au Japon et en 1988 par Capcom aux États-Unis sur NES.

Un Hidden Mickey se trouve dans le circuit imprimé de la cartouche du jeu lorsque celle-ci est demontée.', 'https://fr.wikipedia.org/wiki/Mickey_Mousecapade'),
  ('Q1284570', 'M.U.L.E. (pour Multiple Use Labor Element - élément de travail aux usages multiples) est un jeu vidéo écrit en 1983 par Danielle Bunten Berry, Bill Bunten, Jim Rushing et Alan Watson pour les studios Ozark Softscape, et publié par Electronic Arts. Conçu à l''origine pour les Atari 400/800, il fut porté sur Commodore 64 et Nintendo NES. Bien plus qu''un jeu, c''est un simulateur économique, dont le but est de coloniser une petite planète, en jouant sur la production, l''offre et la demande de ses ressources.', 'https://fr.wikipedia.org/wiki/M.U.L.E.'),
  ('Q1319139', 'Kung-Fu Master (connu sous le nom de Spartan X au Japon et intitulé Kung-Fu lors de son adaptation sur NES) est un beat them all développé par Irem initialement sorti en 1984 sur borne d''arcade, puis sur de nombreux autres supports.

Il est considéré par beaucoup comme le premier véritable beat them all de l''histoire.', 'https://fr.wikipedia.org/wiki/Kung-Fu_Master'),
  ('Q2829419', 'Turbo Racing, connu sous le nom Al Unser Jr.''s Turbo Racing en Amérique du Nord, est un jeu vidéo de course automobile développé et édité par Data East en 1990 sur Nintendo Entertainment System. Il s''agit d''une adaptation du jeu de Formule 1 World Grand-Prix: Pole To Finish sorti au Japon sur Famicom en 1989, avec plusieurs changements au niveau du design et du son.

En Amérique du Nord, le jeu a l''approbation du champion de CART Al Unser Jr., qui donne son nom au jeu et sert de coach au joueur, bien que n''ayant jamais couru en F1. Le titre y connaît une suite, Al Unser Jr.''s Road to the Top sur Super Nintendo. Dans la version européenne, toute référence au coureur automobile a été ôtée, aussi bien dans le jeu que sur la jaquette.', 'https://fr.wikipedia.org/wiki/Turbo_Racing'),
  ('Q1224575', 'Dig Dug II est un jeu vidéo d''arcade développé par Namco sorti en 1985 sur Borne d''arcade. Il fut porté sur Famicom en 1986 et sur Famicom Disk System en 1990. Ce jeu est la suite de Dig Dug.', 'https://fr.wikipedia.org/wiki/Dig_Dug_II'),
  ('Q2819439', 'ASO: Armored Scrum Object (Alpha Mission aux États-Unis, ou Arian Mission) est un jeu d''arcade de type shoot ''em up créé par SNK et sorti sur borne d''arcade (sur le système HAL 21) en 1985.', 'https://fr.wikipedia.org/wiki/ASO:_Armored_Scrum_Object'),
  ('Q2098302', 'Target: Renegade est un jeu vidéo de type beat them all, édité par Ocean Software sur le label Imagine à la fin des années 80 sur Amstrad CPC, Commodore 64 et ZX Spectrum.', 'https://fr.wikipedia.org/wiki/Target:_Renegade'),
  ('Q1327963', 'Xevious est un jeu d''arcade de type shoot ''em up à défilement vertical publié par Namco le 29 janvier 1983. Il a été conçu et programmé par Masanobu Endô. Une seconde version du jeu, Super Xevious, a vu le jour en 1984. Xevious a été porté sur de nombreux supports familiaux et des versions spéciales, sous-titrées Fardraut Saga et Fardraut Densetsu, ont également vu le jour. Le jeu a connu deux suites en 3D: Solvalou (1991) et Xevious 3D/G (1995). Le jeu est ressorti en 2011 sous le nom de 3D Classics - Xevious sur l''eShop de la Nintendo 3DS avec l''ajout de la 3D relief propre aux jeux de la gamme 3D Classics.', 'https://fr.wikipedia.org/wiki/Xevious'),
  ('Q2096756', 'Sid Meier''s Pirates! est un jeu vidéo créé par Sid Meier, publié pour la première fois par MicroProse en 1987. Le jeu est une simulation de la vie d''un pirate dans les Caraïbes au XVIIe siècle.', 'https://fr.wikipedia.org/wiki/Sid_Meier%27s_Pirates!'),
  ('Q2088772', 'Legendary Wings est un jeu vidéo de type shoot ''em up à scrolling vertical développé et édité par Capcom, sorti en novembre 1986 sur système d''arcade Section Z. Il a ensuite été porté sur NES en 1988, puis inclus en 2006 sur la compilation Capcom Classics Collection Vol. 2 pour PlayStation 2 et Xbox et sur Capcom Classics Collection: Remixed pour PlayStation Portable.', 'https://fr.wikipedia.org/wiki/Legendary_Wings'),
  ('Q1324646', 'Gradius, parfois appelé Nemesis en occident, notamment sur MSX et Game Boy, est un jeu vidéo de type shoot ''em up développé et édité par Konami en 1985 sur borne d’arcade.

Il s’agit du premier épisode de la série Gradius, une des séries les plus prolifiques du genre.', 'https://fr.wikipedia.org/wiki/Gradius_(jeu_vid%C3%A9o)'),
  ('Q1323953', 'Antarctic Adventure est un jeu vidéo développé par Konami, sorti sur borne d''arcade en 1984. Il fut ensuite adapté sur MSX, ColecoVision et NES, au Japon seulement. En 1986 sort sa suite, Penguin Adventure.

La musique de jeu, la même pour tous les niveaux, intitulée Les Patineurs, est une valse composée par Émile Waldteufel.', 'https://fr.wikipedia.org/wiki/Antarctic_Adventure'),
  ('Q1353918', 'Thexder est un jeu vidéo de type run and gun développé par Game Arts et édité par D4Enterprise, sorti en 1985 sur DOS, Mac, Amiga, Apple II, MSX, NES, PlayStation 3 et PlayStation Portable.

Il a pour suite Fire Hawk: Thexder - The Second Contact, Thexder 95, Thexder & Fire Hawk et Thexder Neo.', 'https://fr.wikipedia.org/wiki/Thexder'),
  ('Q1330641', 'Adventures of Lolo est un jeu vidéo de réflexion développé par HAL Laboratory sorti en 1989 sur Nintendo Entertainment System. Le jeu reprend les niveaux des différentes versions japonaises de la série Eggerland.', 'https://fr.wikipedia.org/wiki/Adventures_of_Lolo'),
  ('Q1328124', 'Yoshi''s Cookie est un jeu vidéo de puzzle développé par TOSE et édité par Nintendo pour la Nintendo Entertainment System (NES) et la Game Boy en 1992. Le jeu a été réédité sur Super Nintendo en 1993, cette fois-ci développé et édité par Bullet-Proof Software.

Le jeu s''est vendu à 1,12 million d''exemplaires sur NES et à 1,54 million d''exemplaires sur Game Boy.

Alexey Pajitnov, le créateur de Tetris, a participé au développement.', 'https://fr.wikipedia.org/wiki/Yoshi%27s_Cookie'),
  ('Q1330205', 'Paperboy est un jeu vidéo développé et édité par Atari Games sur borne d''arcade en 1984. Le joueur prend le rôle d’un livreur qui distribue les journaux à vélo en les lançant en direction de l''entrée des maisons. Le joueur doit éviter les obstacles qui se présentent à lui (chien, voiture, poubelle, etc.) tout au long de la rue.', 'https://fr.wikipedia.org/wiki/Paperboy'),
  ('Q2081556', 'Tiny Toon Adventures 2: Trouble in Wackyland est un jeu vidéo de plates-formes développé et édité par Konami, sorti en 1992 sur NES.', 'https://fr.wikipedia.org/wiki/Tiny_Toon_Adventures_2:_Trouble_in_Wackyland'),
  ('Q2081247', 'Insector X est un jeu vidéo de type shoot them up développé par Taito, sorti en 1989 sur borne d''arcade. Il a été adapté sur Mega Drive et Famicom en 1990.', 'https://fr.wikipedia.org/wiki/Insector_X'),
  ('Q2079413', 'Traverse USA (également connu sous le nom MotoRace USA, Zippy Race au Japon et Mototour en Espagne) est un jeu d''arcade de course de moto publié par Irem en 1983.', 'https://fr.wikipedia.org/wiki/Traverse_USA'),
  ('Q2078681', 'Air Fortress est un jeu vidéo d''action shoot them up sorti en 1987 sur Nintendo Entertainment System. Le jeu a été développé et édité par HAL Laboratory.

Le jeu est constitué de huit niveaux comportant chacun trois phases: arrivée en vaisseau avec un défilement automatique; placement d''une bombe; évasion chronométrée avant que la forteresse n''explose.', 'https://fr.wikipedia.org/wiki/Air_Fortress'),
  ('Q2068615', 'Attack of the Killer Tomatoes est un jeu vidéo de plates-formes en 2D développé par Imagineering Inc. et édité par THQ en 1991 sur Nintendo. Il fut porté en 1992 sur Game Boy.

Il reprend les évènements et les personnages de la série animée La Guerre des tomates, elle-même basée sur le film Le Retour des tomates tueuses.', 'https://fr.wikipedia.org/wiki/Attack_of_the_Killer_Tomatoes'),
  ('Q2995918', 'Contra Force est un jeu vidéo de type run and gun développé et édité par Konami, sorti en 1992 sur NES.', 'https://fr.wikipedia.org/wiki/Contra_Force'),
  ('Q2998156', 'Corvette ZR-1 Challenge, connu sous le nom de Race America en Amérique du Nord, est un jeu vidéo de course sorti sur NES en 1990 en Europe et en 1992 en États-Unis. Il a été développé par Imagineering Inc. et édité par Milton Bradley pour l''Europe et par Absolute Entertainment pour l''Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Corvette_ZR-1_Challenge'),
  ('Q2979079', 'Cliffhanger est un jeu vidéo de plate-forme et d''action édité par Sony Imagesoft en 1993. Il existe deux versions: l''une développé par Malibu Interactive sur Mega Drive, Mega-CD et Super Nintendo, l''autre par Spidersoft sur Amiga, Game Gear et NES.

Le jeu est basé sur le film Cliffhanger: Traque au sommet (Cliffhanger) de Renny Harlin, sorti en 1992.', 'https://fr.wikipedia.org/wiki/Cliffhanger_(jeu_vid%C3%A9o)'),
  ('Q2982608', 'Ski or Die est un jeu vidéo de sport d''hiver multi-épreuves développé et édité par Electronic Arts en 1990 sur Commodore 64, Amiga et DOS. Le jeu a aussi été édité par Ultra Software sur NES.', 'https://fr.wikipedia.org/wiki/Ski_or_Die'),
  ('Q2984372', 'Color a Dinosaur est un jeu vidéo éducatif sorti sur Nintendo Entertainment System en 1993 qui propose au joueur une version électronique des livres de coloriage: il s''agit ici de colorier des dinosaures.', 'https://fr.wikipedia.org/wiki/Color_a_Dinosaur'),
  ('Q2981165', 'Cobra Command est un jeu vidéo de type shoot them up développé par Data East, sorti en 1988 sur borne d''arcade et NES.', 'https://fr.wikipedia.org/wiki/Cobra_Command_(jeu_vid%C3%A9o,_1988)'),
  ('Q3001743', 'The Mafat Conspiracy est un jeu vidéo sorti sur NES en 1990. C''est la suite directe de Golgo 13: Top Secret Episode. Le jeu est basé sur le manga Golgo 13.', 'https://fr.wikipedia.org/wiki/The_Mafat_Conspiracy'),
  ('Q2962094', 'Fantasy Zone est un jeu vidéo de type shoot ''em up en scrolling horizontal, développé et édité par Sega en 1986 sur borne d''arcade. Il est par la suite porté sur Game Gear, Master System, MSX, Nintendo Entertainment System, PC-Engine et Sharp X68000.

Troisième volume de la collection rétro Sega Ages, ce jeu a été réédité sur PlayStation 2 sous le titre Sega Classics Collection et ses niveaux colorés ont bénéficié d''améliorations en 3D.', 'https://fr.wikipedia.org/wiki/Fantasy_Zone'),
  ('Q3029726', 'Dirty Harry (Dirty Harry: The War Against Drugs en version américaine) est un jeu vidéo tiré de la franchise de films L''Inspecteur Harry, ayant pour interprète principal Clint Eastwood. Le jeu fut développé et édité par Mindscape sur Nintendo Entertainment System en 1990.', 'https://fr.wikipedia.org/wiki/Dirty_Harry_(jeu_vid%C3%A9o)'),
  ('Q3020756', 'Deathbots est un jeu vidéo de type shoot them up développé sur Amiga par Odyssey Software (en) et édité par Anco. Il est sorti en Europe en 1990. Il a été programmé par Lane Waters. La version NES a été distribué aux États-Unis par American Video Entertainment en 1990.', 'https://fr.wikipedia.org/wiki/Deathbots'),
  ('Q3006152', 'Metal Slader Glory est un jeu vidéo d''aventure sorti en 1991 sur Famicom. Il a été développé et édité par HAL Laboratory. Il a ensuite été réédité en 2000 sur Super Famicom sous le nom Metal Slader Glory: Director''s Cut par Nintendo, ce qui en fait le dernier jeu sorti sur cette console. Les deux versions sont sorties uniquement au Japon.

Les personnages, le scénario, ainsi que les graphismes ont été conçus par un mangaka du nom de Yoshimiru qui a aussi publié des mangas basé sur Metal Slader Glory.', 'https://fr.wikipedia.org/wiki/Metal_Slader_Glory'),
  ('Q3001971', 'Crackout est un casse-briques sorti en 1986 sur Famicom Disk System au Japon, puis ressorti en 1991 sur Nintendo Entertainment System en Europe et en Australie. Le jeu a été édité par Konami.', 'https://fr.wikipedia.org/wiki/Crackout'),
  ('Q3008142', 'Cyberball est un jeu vidéo développé et édité par Atari Games sur borne d''arcade en 1988. Il s’agit d’un jeu de sport futuriste de football américain. Le jeu a été converti sur Amiga, Amstrad CPC, Atari ST, Commodore 64, DOS, Lynx, Mega Drive, Nintendo Entertainment System, ZX Spectrum et Xbox Live Arcade. La version Mega Drive japonaise offrait la possibilité à deux joueurs de s''affronter en ligne via le Sega Meganet, le modem de la console.', 'https://fr.wikipedia.org/wiki/Cyberball'),
  ('Q3038698', 'Dragon Ball: Daimaō fukkatsu est un jeu vidéo de rôle par Bandai sorti sur NES le 12 août 1988 au Japon.', 'https://fr.wikipedia.org/wiki/Dragon_Ball:_Daima%C5%8D_fukkatsu'),
  ('Q3073362', 'Flappy est un jeu vidéo de puzzle développé par DB Soft dans le même genre que Adventures of Lolo et Sokoban, mais peu connu à l''extérieur du Japon. Il met en scène Flappy, un personnage assez semblable à une taupe qui doit compléter chaque niveau en poussant une pierre bleue de sa place de départ à une destination signalée par une tuile bleue.

Flappy est d''abord apparu sur l''ordinateur Sharp X1 en 1983. Ce début a été rapidement suivi par des conversions sur un certain nombre d''ordinateurs japonais populaires au début des années 1980, comme ceux des marques NEC et Fujitsu. En tant que puzzle game, il convenait bien à ces premiers systèmes puisqu''il n''exigeait pas une très grande sophistication graphique. Les versions du jeu sur MSX et Famicom sont sorties en 1985. Par la suite, Flappy a connu plusieurs mises à jour et améliorations graphiques.', 'https://fr.wikipedia.org/wiki/Flappy'),
  ('Q3098364', 'Gargoyle''s Quest II: The Demon Darkness, ou Red Arremer II au Japon, est un jeu de plate-forme / RPG de Capcom, distribué en 1992 sur Nintendo. Un portage est sorti sur Game Boy en 1993 uniquement au Japon, et est renommé Makaimura Gaiden: The Demon Darkness.

C''est la suite de Gargoyle''s Quest sorti sur Game Boy.', 'https://fr.wikipedia.org/wiki/Gargoyle%27s_Quest_II:_The_Demon_Darkness'),
  ('Q3047948', 'SonSon est un jeu vidéo de plates-formes développé et édité par Capcom sur borne d''arcade en juillet 1984. Il s''inspire du roman chinois Le Voyage en Occident.', 'https://fr.wikipedia.org/wiki/SonSon'),
  ('Q3073061', 'Fist of the North Star est un jeu vidéo sorti en 1987 au Japon sur Famicom et en 1989 aux États-Unis sur Nintendo Entertainment System. Le jeu est dérivé du manga Ken le Survivant de Buronson et Tetsuo Hara.', 'https://fr.wikipedia.org/wiki/Fist_of_the_North_Star_(jeu_vid%C3%A9o)'),
  ('Q3066241', 'Family Mahjong est un jeu vidéo de mah-jong sorti en 1987 sur Famicom. Le jeu a été édité par Namco.', 'https://fr.wikipedia.org/wiki/Family_Mahjong'),
  ('Q3038826', 'Dragons of Flame est un jeu vidéo de rôle et d’action développé par U.S. Gold et publié par Strategic Simulations (SSI) en 1989 sur Amiga, Amstrad CPC, Atari ST et MS-DOS. Le jeu a ensuite été porté sur Commodore 64 et ZX Spectrum en 1990 puis sur NES en 1992. Le jeu est basé sur le jeu de rôle médiéval-fantastique Donjons et Dragons, publié par TSR. Il est le deuxième volet d’une trilogie se déroulant dans l’univers de Lancedragon, faisant suite à Heroes of the Lance et précédent Shadow Sorcerer. Le jeu prolonge l''histoire raconté dans son prédécesseur, en suivant toujours la trame du premier roman des Chroniques de Lancedragon, intitulé Dragons d''un crépuscule d''automne, écrit par Margaret Weis et Tracy Hickman et publié en 1984. Son système de jeu combine un gameplay de jeu d''action à déroulement horizontal (side-scroller) avec des éléments de jeu de rôle.', 'https://fr.wikipedia.org/wiki/Dragons_of_Flame'),
  ('Q3072372', 'Final Lap est un jeu vidéo de course de Formule 1 sorti en 1987 sur System 2. Le jeu a été développé et édité par Namco. Il s''agit de la suite non officielle du jeu vidéo Pole Position.

Le jeu a connu deux suites: Final Lap 2 (1990) et Final Lap 3 (1992).', 'https://fr.wikipedia.org/wiki/Final_Lap'),
  ('Q3049161', 'Eggerland: Meikyū no Fukkatsu est un jeu vidéo de réflexion sorti en 1988 sur Famicom. Le jeu a été édité par HAL Laboratory.', 'https://fr.wikipedia.org/wiki/Eggerland:_Meiky%C5%AB_no_Fukkatsu'),
  ('Q3038702', 'Dragon Ball 3: Gokū den est un jeu vidéo d’aventure développé par TOSE et édité par Bandai. Il est sorti le 27 octobre 1989 sur Famicom au Japon, et est basé sur l’univers de Dragon Ball.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_3:_Gok%C5%AB_den'),
  ('Q3108305', 'Shadowland, ou Youkai Douchuuki au Japon, parfois incorrectement traduit par Tales of Monster Path, est un jeu vidéo de plates-formes développé et édité par Namco sur borne d''arcade en 1987, et adapté sur Famicom et PC-Engine en 1988. C''est le premier jeu 16-bits de Namco.', 'https://fr.wikipedia.org/wiki/Shadowland_(jeu_vid%C3%A9o)'),
  ('Q3148872', 'Image Fight est un jeu vidéo développé et édité par la société japonaise Irem, sorti en 1988 sur borne d''arcade. Il s''agit d''un shoot ''em up à défilement vertical. Le jeu a été adapté sur les consoles NES, PC-Engine et Sharp X68000 courant 1990. En 2007, la version PC Engine est rééditée sur la console virtuelle de la Wii au Japon.', 'https://fr.wikipedia.org/wiki/Image_Fight'),
  ('Q3112891', 'Terra Cresta est un shoot them up à scrolling vertical sorti en 1985, édité et développé par Nichibutsu.', 'https://fr.wikipedia.org/wiki/Terra_Cresta'),
  ('Q3156908', 'JJ est un jeu vidéo développé par Square Co., notamment par Nasir Gebelli, et édité en 1987 sur Nintendo Entertainment System. Il s''agit de la suite 3-D WorldRunner.', 'https://fr.wikipedia.org/wiki/JJ_(jeu_vid%C3%A9o)'),
  ('Q3181429', 'John Elway''s Quarterback est un jeu vidéo de football américain sorti en 1987 et fonctionne sur DOS, Commodore 64, ZX Spectrum, Amstrad CPC et Nintendo Entertainment System. Le jeu a été développé par Leland Corporation puis édité par Virgin Games.

Il a également été développé comme jeu d''arcade pour deux joueurs. Les joysticks gauche et droit ayant des fonctions différentes (attaque ou défense), les joueurs doivent changer de côté à chaque changement de possession du ballon. En attaque et en défense, les joueurs peuvent choisir une tactique dans une liste préétablie dans un playbook.', 'https://fr.wikipedia.org/wiki/John_Elway%27s_Quarterback'),
  ('Q3120808', 'Gun Nac est un shoot them up à défilement vertical sorti en 1990 sur Nintendo Entertainment System. Le jeu a été développé par Compile.', 'https://fr.wikipedia.org/wiki/Gun_Nac'),
  ('Q2106124', 'Cobra Triangle est un jeu vidéo de course et de combat de véhicules motorisés développé par Rare et publié par Nintendo pour la Nintendo Entertainment System (NES) en 1989. Le joueur contrôle un hors-bord au fil de 25 niveaux présentant divers objectifs, comme gagner des courses, sauver des nageurs ou désamorcer des bombes. Le jeu inclut aussi un système de bonus en jeu, et utilise une vision en perspective 3D isométrique, dont le défilement automatique suit les mouvements du joueur. Les frères Stamper ont conçu le jeu, tandis que David Wise en a composé la musique. Le magazine Computer and Video Games recommande vivement le jeu, et vante ses graphiques et son système de jeu. Des critiques relèvent plus tard la diversité de ses niveaux et remarquent des similitudes au niveau des graphismes avec un jeu précédemment développé par Rare, R.C. Pro-Am. Les sites IGN et GamesRadar+ placent Cobra Triangle parmi leurs meilleurs jeux pour NES et le considèrent comme représentatif de l’esthétique vidéoludique de l’époque. Le jeu apparaît également sur une compilation rétrospective sortie en 2015 par Rare sur Xbox One, Rare Replay.', 'https://fr.wikipedia.org/wiki/Cobra_Triangle'),
  ('Q2115150', 'Exodus: Journey to the Promised Land est un jeu vidéo de puzzle sorti en 1991 et fonctionne sur DOS, Game Boy, Mega Drive et Nintendo Entertainment System. Le jeu a été développé et édité par Wisdom Tree.', 'https://fr.wikipedia.org/wiki/Exodus:_Journey_to_the_Promised_Land'),
  ('Q2117391', 'The Last Ninja est un jeu vidéo d''action-aventure développé et édité par System 3 en 1987 sur Commodore 64. Il a eu un très grand succès dû notamment à de très bons graphismes mais aussi à une musique de grande qualité. Il fut porté sur Apple II, BBC Micro, DOS et trois autres épisodes verront le jour sur micro-ordinateurs 8-bits et 16-bits.', 'https://fr.wikipedia.org/wiki/The_Last_Ninja'),
  ('Q2107567', 'Clu Clu Land est un jeu vidéo de puzzle développé par Nintendo R&D1 et édité par Nintendo, sorti en arcade et sur Nintendo Entertainment System en 1984. La version arcade est appelée Vs. Clu Clu Land.', 'https://fr.wikipedia.org/wiki/Clu_Clu_Land'),
  ('Q300339', 'A Boy and His Blob: Trouble on Blobolonia est un jeu vidéo développé en 1989 par Imagineering pour la console Nintendo Entertainment System. Le jeu a été édité par Absolute Entertainment en Amérique du Nord, par Nintendo en Europe et par Jaleco au Japon. A Boy and His Blob suit l''aventure d''un jeune garçon et de son ami « blob » changeur de forme pour sauver la planète Blobolonia des griffes d''un empereur maléfique.

A Boy and His Blob est un jeu de plates-formes et de réflexion dans lequel le joueur contrôle le garçon: le gameplay repose sur les jelly beans de différents goûts que le garçon donne à son blob. Ces bonbons permettent au blob de se transformer en différents objets pour franchir des obstacles et parcourir l''univers du jeu. A Boy and His Blob a été conçu et développé par David Crane. Une fois la licence de Nintendo obtenue en été 1989, le développement peut démarrer et se termine au bout de six semaines de travail intense. Crane a décrit le concept global de son jeu — le garçon accompagné d''un blob polymorphe — comme non-conventionnel et a voulu profiter de cette occasion pour fournir un panel d''outils variés au joueur.', 'https://fr.wikipedia.org/wiki/A_Boy_and_His_Blob:_Trouble_on_Blobolonia'),
  ('Q349327', 'The Adventures of Tom Sawyer, au Japon Tom Sayer no Bōken, est un jeu vidéo de plates-formes sorti en 1989 sur Nintendo Entertainment System. Le jeu est édité par Seta.

Le jeu est inspiré du roman Les Aventures de Tom Sawyer de Mark Twain.', 'https://fr.wikipedia.org/wiki/The_Adventures_of_Tom_Sawyer_(jeu_vid%C3%A9o)'),
  ('Q288958', 'Operation Wolf est un jeu vidéo de tir au pistolet développé et édité par Taito sur borne d''arcade en 1987.', 'https://fr.wikipedia.org/wiki/Operation_Wolf'),
  ('Q1415070', 'Tales of the Unknown, plus connu par son sous-titre The Bard''s Tale, est un jeu vidéo de type dungeon crawler conçu et programmé par Michael Cranford (en), édité par Interplay Productions en 1985 et distribué par Electronic Arts

Initialement publié sur Apple II, il a également été porté sur Commodore 64, Apple IIgs, ZX Spectrum, Amstrad CPC, Amiga, Atari ST, MS-DOS, Macintosh et Nintendo Entertainment System.

C''est l''un des premiers jeux vidéo inspiré du jeu de rôle Donjons et Dragons. Le jeu était remarquable parmi les autres jeux vidéo de rôle de l''époque pour ses graphismes en simili-3D sans précédent et ses portraits de personnages partiellement animés. Le concept du barde était aussi une innovation: « Le barde était la contribution de l''auteur Michael Cranford au genre, un personnage qui lance des sorts en chantant l''une des six mélodies »', 'https://fr.wikipedia.org/wiki/The_Bard%27s_Tale:_Tales_of_the_Unknown'),
  ('Q1439988', 'Karate Champ est un jeu vidéo de combat en face à face et d''arcade édité en 1984 par Technos Japan pour Data East.', 'https://fr.wikipedia.org/wiki/Karate_Champ'),
  ('Q1418928', 'Silent Service (parfois sous-titré The Submarine Simulation) est un jeu vidéo de simulation de sous-marin. Conçu par Sid Meier, le jeu a été développé et édité par MicroProse en 1985.

Il a pour suite Silent Service II.', 'https://fr.wikipedia.org/wiki/Silent_Service'),
  ('Q1439706', 'Famicom Wars est un jeu vidéo de tactique au tour par tour développé par Intelligent Systems sorti sur Famicom en 1988. Il fait partie de la série Nintendo Wars. Il est uniquement sorti au Japon.', 'https://fr.wikipedia.org/wiki/Famicom_Wars'),
  ('Q1406611', 'Bram Stoker''s Dracula est un jeu vidéo d''action et d''aventure sorti en 1993 et fonctionne sur Amiga, DOS, Game Boy, Game Gear, Master System, Mega-CD, Mega Drive, Nintendo Entertainment System et Super Nintendo. Le jeu a été développé Traveller''s Tales et édité par Psygnosis. Le jeu diffère sensiblement selon la plate-forme. Il s''agit d''une adaptation du film Dracula sorti en 1992.', 'https://fr.wikipedia.org/wiki/Bram_Stoker%27s_Dracula_(jeu_vid%C3%A9o)'),
  ('Q1355850', 'Altered Beast est un jeu vidéo d''action de type beat them all développé et édité par Sega, sorti en 1988 sur borne d''arcade. Il est ensuite porté sur plusieurs plateformes à travers les années et engendre deux suites.', 'https://fr.wikipedia.org/wiki/Altered_Beast'),
  ('Q1398972', 'Faxanadu est un jeu vidéo de type action-RPG développé et édité par Hudson Soft, sorti le 16 novembre 1987 sur Famicom.', 'https://fr.wikipedia.org/wiki/Faxanadu'),
  ('Q1399011', 'PC Kid, ou Bonk''s Adventure en Amérique du Nord, est un jeu vidéo de plates-formes co-développés par Red Company et Atlus, sorti en 1989 sur PC-Engine puis sur borne d''arcade, NES et Game Boy.', 'https://fr.wikipedia.org/wiki/PC_Kid_(jeu_vid%C3%A9o)'),
  ('Q1514023', 'Green Beret, Rush''n Attack aux États-Unis, est un jeu vidéo d''action développé et commercialisé par Konami en 1985 sur borne d''arcade. Le jeu a remporté un certain succès et fut porté sur divers systèmes familiaux. Il a connu une suite sur borne d''arcade en 1989, M.I.A.: Missing in Action.', 'https://fr.wikipedia.org/wiki/Green_Beret_(jeu_vid%C3%A9o,_1985)'),
  ('Q1531134', 'Die Hard est un jeu vidéo commercialisé sur Nintendo Entertainment System (1991) par Activision. Son scénario est basé sur le film Die Hard. Le joueur se doit de sauver des otages et combattre des terroristes au Nakatomi Plaza localisé à Los Angeles.', 'https://fr.wikipedia.org/wiki/Die_Hard_(jeu_vid%C3%A9o,_1991)'),
  ('Q1523204', 'Uninvited est un jeu vidéo d''aventure en pointer-et-cliquer développé par ICOM Simulations et édité par Mindscape, sorti en 1986 sur DOS, Windows, Mac, Amiga, Apple II, Atari ST, Commodore 64, NES, PlayStation 4 et Pocket PC.', 'https://fr.wikipedia.org/wiki/Uninvited_(jeu_vid%C3%A9o)'),
  ('Q2129938', 'Operation Jupiter (aussi titré Hostages en Europe et au Japon, ou encore Hostage: Rescue Mission aux États-Unis) est un jeu vidéo développé par New Frontier et édité par Infogrames. Il est sorti sur plusieurs plateformes comme l''Acorn Electron, Archimedes, Atari ST, Amiga, Apple IIGS, Amstrad CPC, BBC Micro, Commodore 64, Thomson MOTO, DOS, MSX, NES et la ZX Spectrum en 1988. Le portage Nintendo Entertainment System s''intitule Rescue: The Embassy Mission. La musique est d''Alberto José González.', 'https://fr.wikipedia.org/wiki/Operation_Jupiter'),
  ('Q2121419', 'The NewZealand Story est un jeu vidéo de plates-formes développé et édité par Taito, sorti en 1988 sur borne d''arcade.', 'https://fr.wikipedia.org/wiki/The_NewZealand_Story'),
  ('Q2138242', 'Infiltrator est un jeu vidéo édité par U.S. Gold/Mindscape. Il a été développé pour Atari 8-bit family, Apple II, DOS, Commodore 64, et ZX Spectrum par Chris Gray Enterprises.

Le joueur contrôle un héros touche-à-tout de génie appelé Johnny "Jimbo Baby" McGibbits. L''objectif est de piloter un hélicoptère semblable à un Airwolf appelé Gizmo DHX-3, atterrir sur les bases ennemies, et infiltrer un complexe pour arrêter Mad Leader.', 'https://fr.wikipedia.org/wiki/Infiltrator_(jeu_vid%C3%A9o)'),
  ('Q2128100', 'Adventure Island III est un jeu vidéo de plates-formes en 2D à thème préhistorique par Hudson Soft, sorti en 1992 sur Nintendo Entertainment System. Une adaptation, Adventure Island II, est sorti en 1993 sur Game Boy.', 'https://fr.wikipedia.org/wiki/Adventure_Island_III'),
  ('Q2152260', 'Stack-Up, connu au Japon sous le nom de Robot Block, est un jeu vidéo sorti en 1985 sur Famicom et sur Nintendo Entertainment System, conçu pour être utilisé avec le R.O.B.. Stack-Up est l''un des deux jeux à utiliser cet accessoire, l''autre étant Gyromite. Dans ce jeu, le joueur doit, à l''aide de R.O.B., manipuler cinq disques et les mettre dans un certain ordre.

Étant donné que toutes les consoles NES sont compatibles avec la Famicom sortie en 1983, toutes les cartouches du jeu Stack-Up comportent le circuit imprimé à 60 pins connecté à un adaptateur semblable au T89 Cartridge Converter.', 'https://fr.wikipedia.org/wiki/Stack-Up'),
  ('Q2141683', 'Ms. Pac-Man est un jeu vidéo créé par des hackers du MIT après avoir fondé la société General Computer, licencié par la société américaine Midway Manufacturing Company, sorti en 1981 sur borne d''arcade.', 'https://fr.wikipedia.org/wiki/Ms._Pac-Man'),
  ('Q445221', 'Stargate, également appelé Defender II, est un jeu vidéo développé par Vid Kidz, produit par Williams Electronics, sorti en 1981 sur borne d''arcade. Le jeu a été conçu par Larry DeMar. Il s''agit de la suite de Defender (1980), célèbre shoot ''em up créé par Eugene Jarvis.', 'https://fr.wikipedia.org/wiki/Stargate_(jeu_vid%C3%A9o,_1981)'),
  ('Q508004', 'Kick Off est un jeu vidéo de football développé et édité par Anco en 1989 sur les micro-ordinateurs Amiga et Atari ST. Le jeu a été conçu, programmé et dessiné par Dino Dini sur Atari ST, qui l''a adapté avec Steve Screech sur Amiga. Le jeu a été très bien reçu en étant considéré comme l''un des meilleurs du genre. Fin 1989, le jeu est sorti sur Amstrad CPC, Commodore 64 et ZX Spectrum. Ces versions n''ont généralement pas reçu d''aussi bonnes critiques. En 1991, le jeu a été adapté sur NES, Super Nintendo et, sous le titre Super Kick Off, sur Master System, Mega Drive, Game Boy et Game Gear (cf. Kick Off 2).', 'https://fr.wikipedia.org/wiki/Kick_Off'),
  ('Q511995', 'Pinball est un jeu vidéo de flipper développé et édité par Nintendo sorti sur Famicom en 1984 et sur Nintendo Entertainment System en 1985.', 'https://fr.wikipedia.org/wiki/Pinball_(jeu_vid%C3%A9o,_1984)'),
  ('Q512624', 'Loopz est un jeu vidéo de puzzle édité par la compagnie anglaise Audiogenic en 1990 sur divers ordinateurs personnels et consoles de jeu. Il a eu une suite, Super Loopz, sorti en 1994 sur Super Nintendo au Japon et en 1995 sur Amiga 1200 en Europe.

Imaginé par Ian Upton, le principe de jeu se situe au confluent de Tetris (1985) d''Alexei Pajitnov et de Pipe Mania (1989) de The Assembly Line. Des pièces de formes diverses apparaissent les unes après les autres sur un tablier rectangulaire. Le but du jeu est de faire disparaître les pièces en les disposant de manière à former des boucles (loop en anglais), c''est-à-dire des circuits fermés.', 'https://fr.wikipedia.org/wiki/Loopz'),
  ('Q537381', 'Shadowgate est un jeu vidéo d''exploration et d''énigmes à la première personne développé par ICOM Simulations et initialement publié sur Apple IIGS en 1987 avant d''être adapté et traduit sur de nombreux supports. Il fut notamment publié par Kemco sur Nintendo Entertainment System en 1989. L''histoire du jeu présente le personnage principal comme étant le descendant d''une lignée de héros ayant seul le pouvoir de détruire un sorcier maléfique du nom de Lord Warlock. Ce dernier essaye de réveiller dans son château un monstre du nom de Béhémoth pour détruire le monde. Le héros a été téléporté par le magicien Lakmir devant le château pour éradiquer cette menace.', 'https://fr.wikipedia.org/wiki/Shadowgate'),
  ('Q518547', 'Bases Loaded est un jeu vidéo de baseball de Jaleco, sorti à l''origine pour la Nintendo Entertainment System. Il est sorti pour la première fois en 1987 au Japon et en 1988 en Amérique du Nord portage sur Game Boy est sorti en juillet 1990. Une version pour téléphone portable existe également.

Pour la console virtuelle,Bases Loaded est sorti le 11 septembre 2007 au Japon et le 7 avril 2008 en Amérique du Nord pour la Wii, et le 15 mai 2013 au Japon et le 10 juillet 2014 en Amérique du Nord pour la Nintendo 3DS. La Wii U en Amérique du Nord (qui est sortie plus tard au Japon le 22 octobre 2014) est également sortie en même temps que la version Nintendo 3DS. Un portage de Mebius et Clarice Games pour la PlayStation 4 est sorti au Japon en 2015.', 'https://fr.wikipedia.org/wiki/Bases_Loaded'),
  ('Q532200', 'Hyper Sports, connu au Japon sous le titre Hyper Olympic ''84 est un jeu vidéo de sport sur le thème des Jeux Olympiques, publié par Konami dans les salles d''arcade en 1984. Il s''agit d''un sequel du jeu Track and Field de 1983 et propose sept nouvelles épreuves olympiques. Comme son prédécesseur, Hyper Sports a deux boutons de course et un bouton d''action par joueur. La version japonaise du jeu arborait une licence officielle pour les Jeux olympiques d''été de 1984.', 'https://fr.wikipedia.org/wiki/Hyper_Sports'),
  ('Q521272', 'Digital Devil Story: Megami Tensei II est un jeu vidéo de rôle développé par Atlus et édité par Namco, publié en 1990 sur Famicom. Une version améliorée réunissant les deux premiers titres de la série est publiée sur Super Famicom en 1995, sous le nom de Kyūyaku Megami Tensei.

Le développement de Digital Devil Story: Megami Tensei II a débuté en 1987, peu après la sortie du premier opus, Digital Devil Story: Megami Tensei. Contrairement à son prédécesseur, qui était une adaptation de la série de romans Digital Devil Story, Megami Tensei II propose une histoire entièrement originale, conçue pour explorer des thématiques plus profondes. L''histoire suit un protagoniste sans nom explorant un désert post-apocalyptique, combattant et recrutant des démons tout en se retrouvant entraîné dans un conflit opposant les forces démoniaques de Lucifer à l''armée du Dieu Véritable.', 'https://fr.wikipedia.org/wiki/Digital_Devil_Story:_Megami_Tensei_II'),
  ('Q515649', 'Adventures of Lolo 2 est un jeu vidéo de réflexion en solo sorti sur la Famicom au Japon le 6 janvier 1990, puis le 20 mars 1990 sur Nintendo Entertainment System aux États-Unis et dans la zone PAL en 1991. Le jeu est développé et édité par HAL Laboratory. Il est le 6ème jeu de la série de jeux Egerland, le second à être commercialisé en Amérique du Nord (après Adventures of Lolo sur NES) et le 4ème de cette série à être commercialisé en Europe (Après Eggerland Mystery et Eggerland 2 sur MSX et Adventure of Lolo sur NES). Le jeu est par la suite commercialisé sous forme dématérialisée sur la console virtuelle de la Wii, le 5 juin 2007 au Japon, le 21 janvier 2008 en Amérique du Nord, et le 1er février 2008 dans la zone PAL et pour finir le 9 avril 2014 sur la console virtuelle de la Nintendo 3DS au Japon et le 3 septembre 2014 sur la console virtuelle de la Wii U au Japon.', 'https://fr.wikipedia.org/wiki/Adventures_of_Lolo_2'),
  ('Q2157521', 'Fantasy Zone II: The Tears of Opa-Opa un jeu vidéo de Shoot ''em up développé par Sega, est sorti en 1987 sur Master System. Le jeu est par la suite posté sur différents systèmes de jeux comme sur borne d''arcade et NES (Sunsoft) en 1988, puis sur MSX2 en 1989

Fantasy Zone II est réédité sur la console virtuelle de la Wii en 2009 en 2014, et un remake sort sur Nintendo 3DS.', 'https://fr.wikipedia.org/wiki/Fantasy_Zone_II:_The_Tears_of_Opa-Opa'),
  ('Q2172154', 'Teenage Mutant Hero Turtles est un jeu vidéo de plates-formes développé et édité par Konami, sorti sur NES le 12 mai 1989 au Japon sous le titre Gekikame Ninja Den, en juin 1989 en Amérique du Nord sous le titre Teenage Mutant Ninja Turtles et le 17 août 1990 en Europe. Son développement a été supervisé par Yokota-San (également programmeur). Les responsables de ses graphismes sont Nobuya Nakazato et I.Urata.

Il connaît un immense succès sur NES, se vendant à 4 millions d''exemplaires, et est porté sur divers micro-ordinateurs.', 'https://fr.wikipedia.org/wiki/Teenage_Mutant_Hero_Turtles_(jeu_vid%C3%A9o)'),
  ('Q390291', 'Donkey Kong 3 est le troisième jeu vidéo de la série des Donkey Kong créé par Nintendo. Il est sorti presque simultanément en 1983 sur Famicom et sur arcade, puis en 1986 aux États-Unis sur Nintendo Entertainment System. Le jeu est ressorti sur console virtuelle Wii en Amérique du Nord le 14 juillet 2008 et en Europe le 9 janvier 2009. Bien que ce soit une suite, ce titre est une rupture radicale dans la façon de jouer des titres précédents. Alors que dans les deux premières versions, Donkey Kong et Donkey Kong Jr., le joueur devait éviter des pièges dans un jeu de plates-formes, ce titre se rapproche plus d’un jeu de tir. Donkey Kong 3 est également le premier jeu arborant le logo actuel de Donkey Kong (bien que dans le jeu celui-ci soit vert et non rouge).', 'https://fr.wikipedia.org/wiki/Donkey_Kong_3'),
  ('Q376785', 'Ferrari Grand Prix Challenge (F1 HERO MD au Japon) est un jeu vidéo de course sorti en 1992 sur Mega Drive, NES et Game Boy. Le jeu a été édité par Varie.', 'https://fr.wikipedia.org/wiki/Ferrari_Grand_Prix_Challenge'),
  ('Q3273389', 'Alien Syndrome est un jeu vidéo de type run and gun développé et édité par Sega, sorti à partir de 1987 sur borne d''arcade, Amiga, Atari ST, Commodore 64, DOS, MSX, X68000, ZX Spectrum, Master System et NES. Il est également sorti sur Game Gear en 1992 (cette version a été développée par SIMS Co.).', 'https://fr.wikipedia.org/wiki/Alien_Syndrome'),
  ('Q3271336', 'Batman: The Video Game (ou Batman) est un jeu vidéo développé et édité par la société japonaise Sunsoft sur Nintendo Entertainment System en 1989. Le jeu est sorti en même temps que le film homonyme et présente, entre les niveaux, des scènes montrant les personnages du film. Malgré cela, le déroulement du jeu est différent. Une version pour Game Boy est sortie l''année d''après.

Le jeu connait une suite sur NES en 1991: Batman: Return of the Joker.', 'https://fr.wikipedia.org/wiki/Batman:_The_Video_Game_(jeu_vid%C3%A9o,_1989)'),
  ('Q3228947', 'Lee Trevino''s Fighting Golf (Fighting Golf au Japon) est un jeu d''arcade de simulation de golf pour deux joueurs de manière alternative développé par SNK, sorti en 1988 sur borne d''arcade (sur le système Ikari Warriors). Il a ensuite été porté sur Nintendo Entertainment System, PC DOS et Apple II.

La même année, le jeu sort également sous le nom de Country Club, reprenant la même architecture et le même programme avec quelques différences: un contrôle au trackball, l''absence de la sélection du golfeur, l''amélioration et la modification des graphismes.', 'https://fr.wikipedia.org/wiki/Lee_Trevino%27s_Fighting_Golf'),
  ('Q3231455', 'Les Chevaliers du Zodiaque: La Légende d''or est le premier jeu vidéo basé sur l''univers du manga Saint Seiya par Bandai pour la console Nintendo Entertainment System. Il s''agit en fait d''une adaptation en français (menu du jeu et dialogues des personnages) du titre Saint Seiya: Ōgon Densetsu paru au Japon sur Famicom en 1987.

Au Japon, le jeu a connu une suite intitulée Saint Seiya: Ōgon Densetsu - Kanketsu Hen sur Famicom en 1988. Les deux titres ont ensuite été réunis dans la compilation Saint Seiya: Ōgon Densetsu Hen Perfect Edition sur WonderSwan en 2003.', 'https://fr.wikipedia.org/wiki/Les_Chevaliers_du_Zodiaque_:_La_L%C3%A9gende_d%27or'),
  ('Q3218370', 'Last Action Hero est un jeu vidéo de type beat them all sorti en 1992 sur Game Boy, Game Gear, Mega Drive, Nintendo Entertainment System et Super Nintendo. Le jeu a été développé par Bits Studios et édité par Sony Imagesoft. Des versions sur Amiga et DOS sont sorties en 1994. Elles étaient développées par The Dome Software et éditées par Psygnosis.

Il s''agit de l''adaptation du film Last Action Hero de John McTiernan.', 'https://fr.wikipedia.org/wiki/Last_Action_Hero_(jeu_vid%C3%A9o)'),
  ('Q541988', 'Ultima IV: Quest of the Avatar, est un jeu de rôle sur ordinateur publié par Origin Systems en 1985. Le jeu est le quatrième de la série de jeux de rôle Ultima créée par Richard Garriott.', 'https://fr.wikipedia.org/wiki/Ultima_IV:_Quest_of_the_Avatar'),
  ('Q545211', 'Holy Diver est un jeu vidéo de plate-forme sorti au Japon en 1989 sur Famicom. Le jeu a été développé et édité par Irem. Le jeu fut programmé pour sortir en Amérique du Nord et fut même annoncé dans Electronic Gaming Monthly, mais pour des raisons inconnues il n''est jamais sorti.

Le jeu porte le même nom que le premier album de Dio et le personnage principal est une représentation du chanteur et leader de ce groupe Ronnie James Dio. Le jeu reprend des thèmes assez présent dans la musique de Dio, ainsi qu''une imagerie similaire au clip de Holy Diver. Aussi, à la fin du jeu, on peut voir qu''il y a d''autres références musicales, telles que King Crimson, Slayer ou encore Zakk W. et Randy R. (Zakk Wylde et Randy Rhoads, ont été guitaristes pour Ozzy Osbourne.)', 'https://fr.wikipedia.org/wiki/Holy_Diver_(jeu_vid%C3%A9o)'),
  ('Q3276866', 'Magic Bubble est un jeu vidéo de puzzle sorti en 1993 sur Mega Drive. Le jeu a été développé et édité par C&E.

Il est le seul jeu de C&E disponible en anglais.', 'https://fr.wikipedia.org/wiki/Magic_Bubble'),
  ('Q3274230', 'Mach Rider est un jeu vidéo de course futuriste sorti en 1985 sur la Nintendo Entertainment System, développé par HAL Laboratory et édité par Nintendo. Il est ensuite sorti en téléchargement sur les consoles virtuelles de la Wii, en 2007, de la Nintendo 3DS, en 2013, et de la Wii U, en 2014.', 'https://fr.wikipedia.org/wiki/Mach_Rider'),
  ('Q3196363', 'Kickle Cubicle, ou Meikyū Shima en japonais, est un jeu vidéo de puzzle développé par Nanao Corporation. Il sort en arcade en juin 1988 (uniquement au Japon), édité par Irem. Il sera adapté deux ans plus tard sur Nintendo Entertainment System. Son gameplay rappelle légèrement la série des Adventures of Lolo.', 'https://fr.wikipedia.org/wiki/Kickle_Cubicle'),
  ('Q3196441', 'Kidō Senshi Z Gundam: Hot Scramble est un jeu vidéo du type shoot them up développé par Game Studio et édité par Bandai en 1986 sur Nintendo Entertainment System. C''est la troisième adaptation en jeu vidéo de la série basée sur la franchise Mobile Suit Gundam (première sur console). L''histoire s''inspire plus précisément de l''anime Mobile Suit Zeta Gundam.', 'https://fr.wikipedia.org/wiki/Kid%C5%8D_Senshi_Z_Gundam:_Hot_Scramble'),
  ('Q3191691', 'Kabuki: Quantum Fighter est un jeu vidéo de plates-formes / action sorti en 1990 au Japon sur Famicom, en 1991 sur NES sur le continent nord-américain et en 1992 en Europe.', 'https://fr.wikipedia.org/wiki/Kabuki:_Quantum_Fighter'),
  ('Q555897', 'Batman: Return of the Joker est un jeu vidéo d''action et de plate-forme sorti en 1991 sur Game Boy, Mega Drive et Nintendo Entertainment System. Le jeu a été développé et édité par Sunsoft.

Le jeu a été renommé Batman: Revenge of the Joker sur Mega Drive où il a été développé par Ringler Studios et édité par Data East. La version NES s''intitule Dynamite Batman au Japon.', 'https://fr.wikipedia.org/wiki/Batman:_Return_of_the_Joker'),
  ('Q3186013', 'Joshua and the Battle of Jericho est un jeu vidéo d''action sorti en 1992 fonctionnant sur Mega Drive et Nintendo Entertainment System. Le jeu a été développé et édité par Wisdom Tree. Il a pour thème la bataille de Jéricho décrite dans le livre de Josué (dans la Bible) et dans laquelle le peuple d''Israël assiège Jéricho jusqu''à en faire tomber les murailles. Le joueur incarne Josué.', 'https://fr.wikipedia.org/wiki/Joshua_and_the_Battle_of_Jericho'),
  ('Q3282425', 'Vice: Project Doom, ou Gun-Dec au Japon, est un jeu d''action à plates-formes de science-fiction, parsemé d''éléments de shoot them up. Développé par Aicom et édité par Sammy sur NES, le jeu est sorti au Japon le 26 avril 1991 puis en l''Amérique du Nord en novembre 1991.', 'https://fr.wikipedia.org/wiki/Vice:_Project_Doom'),
  ('Q3281100', 'WWF King of the Ring est un jeu vidéo de catch professionnel basé sur l''univers de la World Wrestling Federation, commercialisé en 1993 sur Nintendo Entertainment System et Game Boy. Il s''agit du dernier jeu WWF à être commercialisé sur NES, et le troisième sur Game Boy. Dans ce jeu, le joueur se doit d''obtenir le titre de King of the Ring (roi du ring) en gagnant une série de huit matchs par élimination. Le joueur doit vaincre tous les personnages du jeu pour devenir le WWF Champion. Des matchs exhibition en solo et modes tag team pour un ou deux joueurs sont également disponibles.', 'https://fr.wikipedia.org/wiki/WWF_King_of_the_Ring'),
  ('Q3281783', 'Kick Master est jeu d''action et de plates-formes en 2D à thèmes d''arts martiaux et fantastique. Il a été développé par KID et édité par Taito. Il est sorti uniquement en Amérique du Nord en janvier 1992.', 'https://fr.wikipedia.org/wiki/Kick_Master'),
  ('Q591171', 'Elevator Action est un jeu vidéo de plates-formes développé et édité par Taito, sorti en 1983 sur borne d''arcade. Le jeu a été adapté sur divers systèmes familiaux.', 'https://fr.wikipedia.org/wiki/Elevator_Action'),
  ('Q582642', 'Marble Madness est un jeu vidéo créé par Atari Games, sorti en 1984 sur borne d''arcade. Le jeu a été conçu et programmé par Mark Cerny.

Le joueur contrôle une bille dans des décors accidentés et jonchés d''obstacles et le but du jeu est de rallier une ligne d''arrivée avant la fin du temps imparti. Marble Madness est un classique du jeu d''arcade. Il a connu un succès commercial et fut adapté à partir de 1986 sur divers ordinateurs personnels et consoles de jeu. Il inspirera de nombreux jeux d''adresse comme Super Monkey Ball.', 'https://fr.wikipedia.org/wiki/Marble_Madness'),
  ('Q568489', 'Adventure Island, appelé aussi Adventure Island Classic, est un jeu vidéo de plates-formes sorti sur NES et MSX en 1986. Ce jeu a été développé par Hudson Soft.

Portage du jeu d''arcade Wonder Boy de Sega dont Hudson Soft était responsable, il a été décidé pendant le développement de remplacer le principal personnage de la version originale par le porte-parole d''Hudson Soft: Takahashi Meijin. Dans la version occidentale du jeu, celui-ci sera rebaptisé Master Higgins.', 'https://fr.wikipedia.org/wiki/Adventure_Island_(jeu_vid%C3%A9o)'),
  ('Q3283252', 'Paperboy 2 est un jeu vidéo de genre arcade sorti en 1991 sur Amiga, Amstrad CPC, Atari ST, DOS, Game Boy, Game Gear, Mega Drive, Nintendo Entertainment System, Super Nintendo et ZX Spectrum. Le jeu a été développé par Tengen et édité par Mindscape.

Il s''agit de la suite de Paperboy.', 'https://fr.wikipedia.org/wiki/Paperboy_2'),
  ('Q603874', 'Ice Hockey est un jeu vidéo de hockey sur glace, édité par Nintendo, sorti sur Nintendo Entertainment System en 1988.', 'https://fr.wikipedia.org/wiki/Ice_Hockey_(jeu_vid%C3%A9o,_Nintendo)'),
  ('Q597781', 'Battletoads est un jeu vidéo de type beat them all créé par Tim et Chris Stamper et développé par Rare. Il a tout d''abord été publié sur la NES en 1991 puis a été porté sur de nombreuses autres plates-formes. Le jeu met en scène deux crapauds, Rash et Zitz, partis combattre la Reine Noire et ses lieutenants sur la planète Ragnarok afin de sauver leurs amis kidnappés, Pimple et la princesse Angelica.

Alors que le marché du jeu vidéo accueillait les consoles 16 bits, Battletoads est sans doute l''un des jeux vidéo les plus avancés graphiquement sortis sur NES. Le jeu est devenu célèbre pour son extrême difficulté, due en particulier aux niveaux de courses et d''obstacles, et les moyens humoristiques de combattre les ennemis.', 'https://fr.wikipedia.org/wiki/Battletoads_(jeu_vid%C3%A9o,_1991)'),
  ('Q610785', 'Dragon Ball: Le Secret du dragon, connu sous le nom de Dragon Power aux États-Unis, est un jeu vidéo d''action de Bandai, adapté du manga Dragon Ball d''Akira Toriyama, sorti sur NES le 27 novembre 1986 au Japon, en mars 1988 aux États-Unis et en 1990 en France. Le jeu est ressorti sur Nintendo DS.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_:_Le_Secret_du_dragon'),
  ('Q608480', 'Knight Rider est un jeu vidéo de course automobile, s''inspirant de la série télévisée K 2000, développé et édité par l''entreprise japonaise Pack-In-Video en 1988 sur la console de salon Nintendo NES.', 'https://fr.wikipedia.org/wiki/Knight_Rider_(jeu_vid%C3%A9o,_1988)'),
  ('Q610968', 'Mario Bros. est un jeu d’arcade développé et édité par Nintendo en 1983. Il a été conçu par Shigeru Miyamoto comme la suite de Donkey Kong, avec lequel il constitue un des premiers jeux de plates-formes jamais créés.

Le jeu met en scène le plombier Mario — dénommé « Jumpman » auparavant dans Donkey Kong — qui doit, avec son frère Luigi, combattre des créatures apparaissant dans les égouts de New York.

Boudé des salles d''arcade à sa sortie, Mario Bros. trouve le succès en 1986 avec sa réédition sur Nintendo Entertainment System (NES) en se vendant à plus de 2,27 millions d’exemplaires dans le monde sur cette seule console. Le jeu a depuis été réédité sur de multiples plates-formes, notamment sur Game Boy Advance, ce qui lui valut des critiques lassées de la presse spécialisée, qui loue néanmoins l’efficacité du gameplay.', 'https://fr.wikipedia.org/wiki/Mario_Bros.'),
  ('Q3392005', 'Platoon est un jeu vidéo sorti sur Amiga, Amstrad CPC, Apple II, Atari ST, Commodore 64, DOS, NES et ZX Spectrum à partir de 1987. Il s''agit d''une adaptation du film homonyme d''Oliver Stone conçu par Cho Musou, édité par Sunsoft et développé par Ocean Software. Dans ce jeu, il est possible de jouer chaque segment du long métrage grâce à des phases à la jouabilité différente. La première partie est un jeu à défilement horizontal dans la jungle où vous pouvez sauter et vous accroupir pour passer les obstacles ou se défendre contre des ennemis. La seconde partie est une traversée de tunnels en vue à la première personne.', 'https://fr.wikipedia.org/wiki/Platoon_(jeu_vid%C3%A9o,_1987)'),
  ('Q3440477', 'Rollerball est un jeu vidéo de flipper développé et édité par HAL Laboratory, sorti en 1984 sur MSX et porté en 1988 sur NES.', 'https://fr.wikipedia.org/wiki/Rollerball_(jeu_vid%C3%A9o)'),
  ('Q3438819', 'Roger Clemens'' MVP Baseball est un jeu vidéo de baseball sorti en 1992 et fonctionne sur Mega Drive, Super Nintendo, Nintendo Entertainment System et Game Boy. Le jeu a été développé par Sculptured Software puis édité par Acclaim, LJN et Flying Edge.', 'https://fr.wikipedia.org/wiki/Roger_Clemens%27_MVP_Baseball'),
  ('Q3459392', 'SD Gundam: Gundam Wars est un jeu vidéo de stratégie développé et édité par bandai en avril 1993 sur Nintendo Entertainment System. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam. Le jeu nécessite le Datach Joint ROM System pour fonctionner.', 'https://fr.wikipedia.org/wiki/SD_Gundam:_Gundam_Wars'),
  ('Q636411', 'Might and Magic: The Secret of The Inner Sanctum est un jeu vidéo de type dungeon crawler développé par New World Computing, édité en 1986 sur Apple II. C''est le 1er jeu de la série Might and Magic. Il a été adapté en 1987 sur Commodore 64, IBM PC/Tandy 1000 et compatibles, et Macintosh puis sur MSX et NES. Il est également paru dans l''édition spéciale de Might and Magic VI: Le Mandat Céleste.', 'https://fr.wikipedia.org/wiki/Might_and_Magic:_The_Secret_of_the_Inner_Sanctum'),
  ('Q639619', 'Super Mario Bros. 3 est un jeu vidéo de plates-formes développé et édité par Nintendo sur Nintendo Entertainment System (NES). Il s''agit du troisième volet de la série Super Mario et il est commercialisé en 1988 au Japon, en 1990 aux États-Unis et en 1991 en Europe. Le développement est pris en charge par Nintendo Entertainment Analysis & Development sous la houlette de Shigeru Miyamoto, qui dirige le jeu avec Takashi Tezuka et Hiroshi Yamauchi.

Le jeu met en avant les personnages de Mario et Luigi dans une quête pour sauver les souverains de chacune des sept régions du Royaume Champignon des griffes de Bowser. Les deux frères voyagent à travers huit mondes afin de rétablir l''ordre dans le royaume. Le gameplay du jeu est basé sur celui des précédents titres de la série, et des nouveaux power-ups améliorent les capacités des personnages. Super Mario Bros. 3 établit des conventions reprises dans les jeux suivants de la série.', 'https://fr.wikipedia.org/wiki/Super_Mario_Bros._3'),
  ('Q634502', 'Takahashi Meijin no Bōken Jima IV est un jeu vidéo de plates-formes par Hudson Soft sorti en 1994 sur Famicom uniquement au Japon. C''est le dernier jeu officiellement sorti sur Famicom.', 'https://fr.wikipedia.org/wiki/Takahashi_Meijin_no_B%C5%8Dken_Jima_IV'),
  ('Q638828', 'Dr. Jekyll and Mr. Hyde est un jeu vidéo d''action et de plates-formes à défilement horizontal sorti sur Nintendo Entertainment System en 1988. Le jeu est inspiré du roman L''Étrange Cas du docteur Jekyll et de M. Hyde écrit par Robert Louis Stevenson.', 'https://fr.wikipedia.org/wiki/Dr._Jekyll_and_Mr._Hyde_(jeu_vid%C3%A9o)'),
  ('Q3359482', 'P.O.W.: Prisoners of War est un jeu d''arcade de 1988 développé par SNK. C''est un jeu vidéo du type beat them all. Il est sorti sur le système d''arcade 68K Based, puis a été porté sur Nintendo Entertainment System.', 'https://fr.wikipedia.org/wiki/P.O.W.:_Prisoners_of_War'),
  ('Q3341362', 'Nigel Mansell''s World Championship est un jeu vidéo de course de Formule 1 développé et édité par Gremlin Graphics, sorti en 1992 sur Amiga 500, Amstrad CPC et Atari ST. Il a été édité en 1993 sur Amiga 1200, Amiga CD32, DOS, Mega Drive (par Konami), Nintendo Entertainment System, Super Nintendo et Game Boy (par GameTek).

Nigel Mansell est un pilote anglais, champion du monde de Formule 1 en 1992.', 'https://fr.wikipedia.org/wiki/Nigel_Mansell%27s_World_Championship'),
  ('Q3362541', 'Best of the Best: Championship Karate (Super Kick Boxing, The Kick Boxing) est un jeu de karaté édité par Loriciel sur Amiga, Amstrad CPC, DOS, Game Boy, Mega Drive, NES, PC Engine, et Super Nintendo.

Une option « Kumité » permet de pratiquer des combats clandestins lorsque le joueur a atteint un niveau technique suffisant. 55 mouvements sont disponibles (le joueur doit en choisir 13).

Le jeu est similaire à Panza Kick Boxing, mais le nom d''André Panza n''apparaît pas, le nom des adversaires a été modifié, et les sessions d''entraînement ont été changées. Cette opération s''est effectuée à la faveur de l''arrêt de Loriciels et de la réouverture sous le nom de Loriciel', 'https://fr.wikipedia.org/wiki/Best_of_the_Best:_Championship_Karate'),
  ('Q3328277', 'Musashi no Bōken est un RPG, créé par Sigma Ent. Inc., sorti sur la Famicom le 22 décembre 1990 au Japon.', 'https://fr.wikipedia.org/wiki/Musashi_no_B%C5%8Dken'),
  ('Q3500399', 'Strider est un jeu vidéo d''action-plates-formes développé et édité par Capcom sur Nintendo Entertainment System en juillet 1989.

Il ne s''agit pas de la version connue sur borne d''arcade mais d''une nouvelle développée spécialement pour la console 8-bits de Nintendo.', 'https://fr.wikipedia.org/wiki/Strider_(jeu_vid%C3%A9o,_juillet_1989)'),
  ('Q3493437', 'Spider-Man: Return of the Sinister Six est un jeu vidéo d''action et de plates-formes sorti en 1992 sur NES, Master System et en 1993 sur Game Gear. Le jeu a été développé par Bits Studios et édité par LJN et Flying Edge. Le jeu est fondé sur une mini-série de Marvel Comics sur Spider-Man et les Sinister Six au début des années 1990.', 'https://fr.wikipedia.org/wiki/Spider-Man:_Return_of_the_Sinister_Six'),
  ('Q3489627', 'Solstice: The Quest for the Staff of Demnos est un jeu vidéo d''aventure/réflexion développé par Software Creation Ltd., sorti en 1990 sur NES.', 'https://fr.wikipedia.org/wiki/Solstice:_The_Quest_for_the_Staff_of_Demnos'),
  ('Q3482630', 'Shufflepuck Cafe est un jeu vidéo édité par Brøderbund Software en 1988. Conçu et programmé par Christopher Gross, il s''agit d''une simulation de air hockey. Le jeu a d''abord été développé en noir et blanc sur Macintosh avant d''être décliné en couleurs sur Amiga, Atari ST, Amstrad CPC, MS-DOS et Apple IIgs.

Le jeu se déroule dans un café de l''espace où il est possible d''affronter en duel différents personnages plus ou moins originaux.', 'https://fr.wikipedia.org/wiki/Shufflepuck_Cafe'),
  ('Q3496966', 'Star Luster est un jeu vidéo de tir à la première personne développé et édité par Namco, sorti en 1985 sur Famicom exclusivement au japon. La même année, Nintendo adapte le jeu sur leur borne d''arcade Vs. System.', 'https://fr.wikipedia.org/wiki/Star_Luster'),
  ('Q3477465', 'Section Z est un jeu vidéo de type shoot ''em up à défilement horizontal développé et édité par Capcom, sorti en décembre 1985 sur le système d''arcade baptisé du même nom Section Z. Il a ensuite été porté en 1987 sur NES et Famicom Disk System, puis inclus en 2005 sur la compilation Capcom Classics Collection pour PlayStation 2 et Xbox et sur Capcom Classics Collection: Remixed en 2006 pour PlayStation Portable.', 'https://fr.wikipedia.org/wiki/Section_Z'),
  ('Q3459413', 'SD Gundam Gaiden: Knight Gundam Monogatari est un jeu vidéo de rôle développé et édité par Bandai en août 1990 sur NES. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam. Il est notamment basé sur l''univers de SD Gundam Gaiden Sieg Zion Hen et c''est le premier opus d''une série composée de cinq jeux vidéo de rôle. Il a été porté en 1994 sur Game Boy.', 'https://fr.wikipedia.org/wiki/SD_Gundam_Gaiden:_Knight_Gundam_Monogatari'),
  ('Q3459419', 'SD Gundam Gaiden: Knight Gundam Monogatari 3 - Densetsu no Kishi Dan est un jeu vidéo de rôle développé et édité par Bandai en octobre 1992 sur NES. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam. Il est notamment basé sur l''univers de SD Gundam Gaiden Sieg Zion Hen et c''est le quatrième opus d''une série composée de cinq jeux vidéo de rôle.', 'https://fr.wikipedia.org/wiki/SD_Gundam_Gaiden:_Knight_Gundam_Monogatari_3_-_Densetsu_no_Kishi_Dan'),
  ('Q3459416', 'SD Gundam Gaiden: Knight Gundam Monogatari 2 - Hikari no Kishi est un jeu vidéo de rôle développé et édité par Bandai en décembre 1991 sur NES. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam. Il est notamment basé sur l''univers de SD Gundam Gaiden Sieg Zion Hen et c''est le troisième opus d''une série composée de cinq jeux vidéo de rôle.', 'https://fr.wikipedia.org/wiki/SD_Gundam_Gaiden:_Knight_Gundam_Monogatari_2_-_Hikari_no_Kishi'),
  ('Q3459438', 'SD Gundam World: Gachapon Senshi 4 - New Type Story est un jeu vidéo de stratégie développé par Bandai, et édité par Yutaka en décembre 1991 sur Nintendo Entertainment System. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam. C''est le quatrième opus d''une série de cinq jeux vidéo.', 'https://fr.wikipedia.org/wiki/SD_Gundam_World:_Gachapon_Senshi_4_-_New_Type_Story'),
  ('Q3459439', 'SD Gundam World: Gachapon Senshi 5 - Battle of Universal Century est un jeu vidéo de stratégie développé par Bandai, et édité par Yutaka en décembre 1992 sur Nintendo Entertainment System. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam. C''est le dernier opus d''une série de cinq jeux vidéo.', 'https://fr.wikipedia.org/wiki/SD_Gundam_World:_Gachapon_Senshi_5_-_Battle_of_Universal_Century'),
  ('Q3459436', 'SD Gundam World: Gachapon Senshi 3 - Eiyū Senki est un jeu vidéo de stratégie développé par Bandai, et édité par Yutaka en juin 1990 sur Nintendo Entertainment System. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam. C''est le troisième opus d''une série de cinq jeux vidéo.', 'https://fr.wikipedia.org/wiki/SD_Gundam_World:_Gachapon_Senshi_3_-_Eiy%C5%AB_Senki'),
  ('Q3459437', 'SD Gundam World: Gachapon Senshi 2 - Capsule Senki est un jeu vidéo de stratégie développé par Bandai, et édité par Shinsei en juin 1989 sur Nintendo Entertainment System. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam. C''est le deuxième opus d''une série de cinq jeux vidéo. Il a été porté sur MSX.', 'https://fr.wikipedia.org/wiki/SD_Gundam_World:_Gachapon_Senshi_2_-_Capsule_Senki'),
  ('Q646691', 'Teenage Mutant Ninja Turtles III: The Manhattan Project, ou Teenage Mutant Ninja Turtles 2: The Manhattan Project au Japon, est un jeu vidéo de type beat them all développé et édité par Konami.

C''est le troisième opus de la série Tortues Ninja sorti sur NES en 1991 au Japon et en 1992 en Amérique du Nord. Le jeu sortira pour la première fois en Europe en 2022 par l''entremise de la compilation Teenage Mutant Ninja Turtles: The Cowabunga Collection de Konami.', 'https://fr.wikipedia.org/wiki/Teenage_Mutant_Ninja_Turtles_III:_The_Manhattan_Project'),
  ('Q650278', 'Mighty Bomb Jack est un jeu vidéo de plates-formes développé par Tecmo, sorti en 1987 sur NES. Il a été adapté sur Amiga, Atari ST et Commodore 64 en 1990.', 'https://fr.wikipedia.org/wiki/Mighty_Bomb_Jack'),
  ('Q674227', 'Ninja Gaiden III: The Ancient Ship of Doom, connu au Japon sous le titre Ninja Ryūkenden III: Yomi no Hakobune, est un jeu vidéo de plates-formes/action développé et édité par Tecmo pour la NES, sorti en juin 1991 au Japon, et en août 1991 en Amérique du Nord. En 1993, le jeu est porté par Tecmo sur Atari Lynx, et est publié aux États-Unis et en Europe, où, contrairement aux opus précédents, il conserve le nom Ninja Gaiden. En 1995, le jeu a également été porté sur Super Nintendo pour intégrer la compilation Ninja Gaiden Trilogy, sortie aux États-Unis et au Japon. Il est réédité à partir de 2008 sur Console Virtuelle, sur Wii, 3DS puis Wii U au Japon, en Amérique du Nord et en Europe. Le jeu a été réalisé par Masato Kato, prenant la place de Hideo Yoshizawa, qui avait dirigé les deux premiers opus, Ninja Gaiden, et Ninja Gaiden II: The Dark Sword of Chaos.', 'https://fr.wikipedia.org/wiki/Ninja_Gaiden_III:_The_Ancient_Ship_of_Doom'),
  ('Q668757', 'Urban Champion est un jeu vidéo de combat sorti sur Nintendo Entertainment System, édité par Nintendo en 1984.', 'https://fr.wikipedia.org/wiki/Urban_Champion'),
  ('Q677353', 'Stinger est un shoot them up sorti en 1986 sur Famicom Disk System, puis un an après aux États-Unis sur Nintendo Entertainment System. Il est ressorti sur Famicom en 1993. Le jeu a été développé et édité par Konami.', 'https://fr.wikipedia.org/wiki/Stinger_(jeu_vid%C3%A9o,_Konami)'),
  ('Q669784', 'Digital Devil Story: Megami Tensei est un jeu vidéo de rôle développé par Atlus et édité par Namco, publié en 1987 sur Famicom. Il s''agit du premier jeu de la franchise Megami Tensei, qui est basé sur la série de romans Digital Devil Story de l''auteur japonais Aya Nishitani. Une version améliorée réunissant les deux premiers titres de la série est publiée sur Super Famicom en 1995, sous le nom de Kyūyaku Megami Tensei.

L''histoire suit deux lycéens japonais, Akemi Nakajima et Yumiko Shirasagi, qui se retrouvent confrontés aux forces de Lucifer après que Nakajima a accidentellement libéré des démons à l''aide d''un programme d''invocation qu''il a lui-même conçu. Le gameplay propose une exploration de donjons en vue à la première personne (dungeon crawler) et des combats au tour par tour, ainsi que la possibilité de négocier avec les démons dans les versions Famicom et Super Famicom.', 'https://fr.wikipedia.org/wiki/Digital_Devil_Story:_Megami_Tensei_(jeu_vid%C3%A9o)'),
  ('Q3532685', 'Total Recall est un jeu vidéo de beat them all-plate-forme adapté du film du même nom Total Recall et sorti sur NES en 1992.', 'https://fr.wikipedia.org/wiki/Total_Recall_(jeu_vid%C3%A9o)'),
  ('Q3521337', 'The Hunt for Red October est un jeu vidéo d''action sorti en 1990 sur Nintendo Entertainment System, Super Nintendo et Game Boy. Le jeu a été édité par Hi-Tech Expressions sur les consoles Nintendo. Il est inspiré du film À la poursuite d''Octobre Rouge.', 'https://fr.wikipedia.org/wiki/The_Hunt_for_Red_October_(jeu_vid%C3%A9o,_1990,_Beam_Software)'),
  ('Q3553822', 'Valis: The Fantasm Soldier est un jeu vidéo de type action-RPG sorti en 1986 et fonctionne sur MSX, Nintendo Entertainment System, Mega Drive et PC-Engine CD. Le jeu a été développé par Telenet Japan puis édité par Riot et Renovation.

Il s''agit du premier épisode de la série Mugen Senshi Valis.', 'https://fr.wikipedia.org/wiki/Valis:_The_Fantasm_Soldier'),
  ('Q3521145', 'The Great Waldo Search est un jeu vidéo de réflexion sorti en 1992 sur Mega Drive, NES et Super NES. Le jeu a été développé par Radiance Software et édité par THQ. Il est basé sur le livre-jeu Où est Charlie ? Le voyage fantastique et fait suite au jeu vidéo Where''s Waldo? sorti sur NES un peu plus tôt.', 'https://fr.wikipedia.org/wiki/The_Great_Waldo_Search'),
  ('Q3569964', 'Stadium Events est un jeu vidéo d''athlétisme de Bandai sorti en 1986 au Japon et en 1988 en Europe qui utilise le Family Fun Fitness.

Quelques mois après le début de la commercialisation du titre aux États-Unis en 1987, il est retiré de la vente, ce qui confère à cette première édition une grande valeur marchande pour les collectionneurs. Nintendo, qui a racheté les droits sur le marché nord-américain, y sort alors de version modifiée intitulée World Class Track Meet. Celle-ci est vendue en pack avec le Family Fun Fitness, renommé Power Pad par Nintendo.

Le jeu s''est vendu à 3,08 millions d''exemplaires.', 'https://fr.wikipedia.org/wiki/Stadium_Events'),
  ('Q3634758', 'Barbie est un jeu vidéo de plates-formes développé par Imagineering Inc., édité par Hi Tech Expressions, et sorti sur NES et DOS en 1991.', 'https://fr.wikipedia.org/wiki/Barbie_(jeu_vid%C3%A9o,_1991)'),
  ('Q3628242', 'Atlantis no Nazo est un jeu vidéo de plates-formes développé et édité par Sunsoft et sorti uniquement au Japon en 1986 sur Famicom puis en 2001 sur PlayStation et Windows.

Le jeu se déroule dans la mythique Atlantide. Le joueur contrôle un aventurier amateur nommé Wynn, dont l''objectif est de sauver son maître retenu captif.

Sunsoft développe le jeu dans l''intention de surpasser le très populaire Super Mario Bros., et fait la publicité de son titre avec le slogan Ano Super Mario wo koeta!!. Le nombre de niveaux surpasse également celui de Super Mario Bros..', 'https://fr.wikipedia.org/wiki/Atlantis_no_Nazo'),
  ('Q3564653', 'WCW World Championship Wrestling (WCW Wrestling, ou encore Super Star Pro Wrestling au Japon) est un jeu vidéo de catch professionnel commercialisé sur console Nintendo Entertainment System en 1990. Il s''agit du premier (et à ce jour unique) jeu vidéo basé sur la National Wrestling Alliance (à cette époque, la WCW était un membre de la NWA).', 'https://fr.wikipedia.org/wiki/WCW_World_Championship_Wrestling'),
  ('Q687559', 'Final Fantasy III est un jeu vidéo de rôle, développé par Square Co., Ltd., sorti sur Famicom en 1990 au Japon.

Un remake entièrement en 3D du jeu, développé par Matrix Software et édité par Square Enix, sorti sur Nintendo DS le 24 août 2006 au Japon, le 14 novembre de la même année en Amérique du Nord et le 3 mai 2007 en Europe. Cette version propose une nouvelle bande-son, une intégration progressive des personnages avec un scénario différent pour chacun et un mode de jeu multijoueur via des messages à envoyer (en réseau local et Internet).

Le remake du jeu a aussi été adapté sur la PSP (d''après la version DS); il est sorti le 26 septembre 2012, sur le PlayStation Store européen. De même, un port pour iOS est sorti le 24 mars 2011, et un port sur Android le 12 mars 2012, ainsi qu''une version spéciale pour Ouya en avril 2013. La version Windows est sortie le 27 mai 2014. La version "Pixel Remaster" est sortie sur Steam et App Store le 28 juillet 2021.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_III'),
  ('Q684629', 'F-15 Strike Eagle est un jeu vidéo de simulation de vol de combat créé par Sid Meier et Grant Irani et publié par MicroProse en 1984 sur borne d''arcade, Amstrad CPC, Apple II, Atari 8-bit, Atari ST, C64, IBM PC, MSX, NES, PC-88, ZX Spectrum, Game Gear, Game Boy et Thomson TO. Le joueur y pilote un avion de chasse McDonnell Douglas F-15 Eagle au cours de sept missions de combat. Six d’entre elles sont basées sur des évènements historiques et la dernière, hypothétique, prend place dans le golfe Persique en 1984. Le joueur contrôle son avion par l’intermédiaire d’une vue à la première personne du cockpit de l’avion et d’un affichage tête haute. Ce dernier inclut une carte de navigation sur laquelle est affichée la position de l’avion et de la base du joueur, ainsi que celle des ennemis. La vue du cockpit affiche l’environnement en trois dimensions et les ennemis, que ce soit dans les airs ou au sol. Le joueur contrôle son avion au joystick.', 'https://fr.wikipedia.org/wiki/F-15_Strike_Eagle_(jeu_vid%C3%A9o)'),
  ('Q677764', 'Klax est un jeu vidéo de puzzle développé et édité par Atari Games sur borne d''arcade en 1989. Le jeu a été adapté sur de nombreux supports familiaux.', 'https://fr.wikipedia.org/wiki/Klax_(jeu_vid%C3%A9o)'),
  ('Q3810637', 'Journey to Silius, ou Raf World au Japon, est un jeu vidéo de type run and gun sur thème post-apocalyptique. Il a été développé par Tokai Engineering et édité par Sunsoft en 1990 sur Nintendo.', 'https://fr.wikipedia.org/wiki/Journey_to_Silius'),
  ('Q745044', 'Devil World est un jeu vidéo développé par Nintendo, sorti au Japon le 5 octobre 1984 et le 15 juillet 1987 en Europe, plus particulièrement en Suède, sur la NES. Le jeu a un gameplay similaire à celui de Pac-Man. C''est le seul jeu conçu par Shigeru Miyamoto n''ayant jamais été sorti aux États-Unis, bien que toutes les versions du jeu soient en anglais. Cela est dû à la politique stricte de Nintendo sur les icônes religieuses dans les jeux vidéo, qui étaient fréquentes dans ce jeu. Malgré cela, Nintendo sortit quand même son jeu en Europe. Ce jeu est l''un des premiers jeux NES sur lequel a travaillé Koji Kondo, compositeur pour Nintendo.', 'https://fr.wikipedia.org/wiki/Devil_World'),
  ('Q698705', 'Double Dragon est un jeu vidéo de type beat them all développé par Technos, sorti sur borne d''arcade en 1987, et adapté sur divers consoles et ordinateurs de l''époque.

Il s''agit du premier épisode de la série Double Dragon.

Également développé par Yoshihisa Kishimoto, il est considéré comme le successeur spirituel de Renegade (1986).

La version NES de ce jeu a la particularité d''être sortie en France après sa suite Double Dragon II: The Revenge.', 'https://fr.wikipedia.org/wiki/Double_Dragon_(jeu_vid%C3%A9o,_1987)');

insert into import_summary (wikidata_id, summary, source) values
  ('Q716880', 'The Miracle Piano Teaching System est un jeu vidéo éducatif sorti en 1990 sur Mega Drive, Nintendo Entertainment System, DOS, Super Nintendo, Amiga et Mac OS. Le jeu a été développé et édité par The Software Toolworks. Il permet d''apprendre les bases du piano en utilisant un clavier MIDI.', 'https://fr.wikipedia.org/wiki/The_Miracle_Piano_Teaching_System'),
  ('Q769834', 'The Incredible Crash Dummies est un jeu vidéo d''action dont les différentes versions sont sorties entre 1992 et 1994 sur Amiga, Game Boy, Game Gear, Master System, Mega Drive, NES et Super Nintendo. Le jeu a été développé selon les versions par Software Creations, Gray Matter Interactive et Teeny Weeny Games, et édité par LJN et Flying Edge.

L''univers du jeu est basé sur la licence de jouets Crash Dummies, elles-mêmes basées sur les mannequins d’essai de choc automobiles.', 'https://fr.wikipedia.org/wiki/The_Incredible_Crash_Dummies_(jeu_vid%C3%A9o)'),
  ('Q764069', 'Duck Hunt est un jeu vidéo de tir au pistolet développé et édité par Nintendo. Il est d''abord sorti le 21 avril 1984 au Japon sur Famicom et en Amérique du Nord sur le système d''arcade Vs. System, puis a fait partie des jeux de lancement de la console Nintendo Entertainment System le 18 octobre 1985 en Amérique du Nord, puis est sorti en Europe sur cette même console le 15 août 1987. Il s''agit du premier jeu à exploiter le pistolet de la console, le NES Zapper, qui est utilisée lors d''une chasse au canard virtuelle.

Ce jeu vidéo est le remake du jeu Laser Clay System sorti en 1976. Il s''est vendu à plus de 28 millions d''exemplaires, ce qui en fait le deuxième jeu le plus vendu sur cette console.', 'https://fr.wikipedia.org/wiki/Duck_Hunt'),
  ('Q3945119', 'Saint Seiya: Ōgon Densetsu Kanketsu Hen est le deuxième jeu vidéo basé sur l''univers du manga Saint Seiya pour la console Nintendo Entertainment System. Il est la suite de Les Chevaliers du Zodiaque: La Légende d''or et ne sort que 9 mois après, exclusivement au Japon.', 'https://fr.wikipedia.org/wiki/Saint_Seiya:_%C5%8Cgon_Densetsu_-_Kanketsu_Hen'),
  ('Q3952040', 'Disney''s The Little Mermaid est un jeu vidéo d''action tiré du film d''animation La Petite Sirène sorti en 1989, produit par Walt Disney Feature Animation. Le jeu fut développé et édité par Capcom sur Nintendo Entertainment System en 1991 puis, est porté sur Game Boy en 1993.', 'https://fr.wikipedia.org/wiki/Disney%27s_The_Little_Mermaid'),
  ('Q3939307', 'RoboCop 2 est un jeu vidéo d''action développé par Ocean Software et distribué sur divers micro-ordinateurs en 1990. Plusieurs versions ont vu le jour en fonction des plates-formes. Une sur Amiga et Atari ST. Une autre sur Amstrad CPC et ZX Spectrum.

Puis en 1991, deux autres versions apparaissent; une sur Commodore 64, NES et Game Boy; et enfin une version, développée par Data East, distribuée sur borne d''arcade.', 'https://fr.wikipedia.org/wiki/RoboCop_2_(jeu_vid%C3%A9o)'),
  ('Q849328', 'Probotector, ou Gryzor selon les versions, plus connu sous le nom Contra hors Europe, est un jeu vidéo d''action de type run and gun, développé et édité par Konami, sorti initialement en 1987 sur borne d''arcade.

Le jeu a été converti sur Amstrad CPC, Commodore 64, DOS, MSX 2, NES et ZX Spectrum. La plate-forme de téléchargement de la Xbox 360 propose le jeu depuis 2009.', 'https://fr.wikipedia.org/wiki/Probotector_(jeu_vid%C3%A9o,_1987)'),
  ('Q798676', 'Bad Dudes vs. DragonNinja, ou plus simplement Bad Dudes (Japon: DragonNinja est un jeu vidéo d''arcade de type beat them all, développé par Data East et sorti en 1988.', 'https://fr.wikipedia.org/wiki/Bad_Dudes_vs._DragonNinja'),
  ('Q810986', 'Battle Chess est un jeu vidéo d''échecs sorti en 1988 sur Amiga, puis a été porté sur 3DO, AmigaCD32, Amiga CDTV, Apple IIGS, Archimedes, Atari ST, Commodore 64, DOS, Mac OS et Nintendo Entertainment System. Développé et édité par Interplay, le jeu a été conçu par Todd Camasta, Michael Quarles, Jayesh J. Patel et Bruce Schlickbernd.

Battle Chess s''est rendu célèbre de par les animations des pièces lorsque le joueur les déplace ou les fait attaquer. Certaines de ces animations sont inspirées de films; ainsi le combat de deux cavaliers ("chevaliers" en anglais) vient de la scène du chevalier noir de Sacré Graal ! des Monty Python, et le combat du fou contre le roi vient des Aventuriers de l''Arche Perdue.', 'https://fr.wikipedia.org/wiki/Battle_Chess'),
  ('Q810990', 'Battle City est un jeu vidéo d''action développé et édité par Namco, sorti en 1985 sur borne d''arcade, Sharp X1, NES, et Game Boy. Il fait suite à Tank Battalion et précède Tank Force.', 'https://fr.wikipedia.org/wiki/Battle_City'),
  ('Q785278', 'Pac-Mania est un jeu vidéo de labyrinthe développé et manufacturé par Namco en 1987 sur borne d''arcade. Il a été adapté sur diverses plates-formes familiales.', 'https://fr.wikipedia.org/wiki/Pac-Mania'),
  ('Q798519', 'Mission impossible (Mission: Impossible) est un jeu vidéo d''action tiré de la série télévisée du même nom. Il est développé par Konami, et édité en 1990 en Amérique du Nord et en 1991 en Europe sur NES.', 'https://fr.wikipedia.org/wiki/Mission_impossible_(jeu_vid%C3%A9o,_1990)'),
  ('Q3516981', 'Tecmo Bowl est un jeu d''arcade de football Américain développé et publié par Tecmo en 1987.', 'https://fr.wikipedia.org/wiki/Tecmo_Bowl_(jeu_vid%C3%A9o)'),
  ('Q3520704', 'The Earth Fighter Rayieza est un jeu vidéo de rôle sorti sur PC-88, FM-7, Sharp X1 et MSX en 1985. Il a été édité au Japon par Enix. Il a été porté sur Famicom par Nintendo en 1987.', 'https://fr.wikipedia.org/wiki/The_Earth_Fighter_Rayieza'),
  ('Q3516985', 'Tecmo Cup Football Game (ou Tecmo Cup Soccer Game aux États-Unis) est un jeu vidéo de football, publié par Tecmo en 1992 sur NES. Il s''agit d''une adaptation occidentalisée du titre Captain Tsubasa, inspiré du manga du même nom, sorti en 1988 au Japon sur Famicom.', 'https://fr.wikipedia.org/wiki/Tecmo_Cup_Football_Game'),
  ('Q3514133', 'Takahashi Meijin no Bug-tte Honey est un jeu vidéo de plates-formes sorti sur Famicom en 1987. Ce jeu, développé et édité par Hudson Soft, est seulement sorti au Japon.', 'https://fr.wikipedia.org/wiki/Takahashi_Meijin_no_Bug-tte_Honey'),
  ('Q3514327', 'Takeshi no chōsenjō est un jeu vidéo japonais pour la Famicom par le comédien et réalisateur Takeshi Kitano. Il est sorti exclusivement au Japon en décembre 1986. Il s''agit d''un jeu expérimental tentant de briser un maximum de règles des jeux vidéo.', 'https://fr.wikipedia.org/wiki/Takeshi_no_ch%C5%8Dsenj%C5%8D'),
  ('Q3521086', 'The Goonies est un jeu vidéo de plates-formes sorti en 1986 sur Famicom, MSX et PC-98, puis ressorti en 1988 sur Famicom Disk System. Le jeu a été développé et édité par Konami. Le jeu est tiré du film les Goonies et a connu une suite sortie en 1987 sous le nom The Goonies II.', 'https://fr.wikipedia.org/wiki/The_Goonies_(jeu_vid%C3%A9o,_1986)'),
  ('Q3985728', 'The Astyanax (connu au Japon sous le nom The Lord of King) est un jeu d''arcade de type action plates-formes en 2D développé et édité par Jaleco. Le jeu est également sorti au Japon le 21 décembre 1989 et aux États-Unis sur Nintendo Entertainment System en mars 1990 sous le titre Astyanax.', 'https://fr.wikipedia.org/wiki/The_Astyanax'),
  ('Q3989775', 'The Uncanny X-Men est un jeu vidéo d''action développé par Pixel et édité par LJN sorti en 1989 sur NES.', 'https://fr.wikipedia.org/wiki/The_Uncanny_X-Men_(jeu_vid%C3%A9o)'),
  ('Q4033647', 'Kid Dracula est un jeu de plates-formes développé et publié par Konami le 19 octobre 1990 au Japon sur Famicom. Il est considéré comme une parodie de la franchise Castlevania. Une version pour téléphone mobile est commercialisée au Japon le 30 juin 2006.

Le jeu est porté sur PlayStation 4, Xbox One, Nintendo Switch et Microsoft Windows dans le cadre de la Castlevania Anniversary Collection, sortie en version numérique le 16 mai 2019 dans toutes les régions, avec une localisation anglaise sous le nom de Kid Dracula. C''est la première fois que le jeu sort en dehors du Japon.', 'https://fr.wikipedia.org/wiki/Kid_Dracula_(jeu_vid%C3%A9o,_1990)'),
  ('Q854479', 'Super Mario Bros. 2 (ou Super Mario USA au Japon) est un jeu vidéo de plates-formes développé par Nintendo R&D4 et édité par Nintendo. Il sort sur Nintendo Entertainment System en 1988 en Amérique du Nord, en 1989 en Europe puis en 1992 au Japon.

Cet épisode n''est pas un jeu original puisqu''il s''agit de l''adaptation de Yume Kōjō: Doki Doki Panic, un jeu de Nintendo sorti au Japon sur Famicom Disk System en 1987. La première véritable suite à Super Mario Bros. est Super Mario Bros.: The Lost Levels (connu au Japon sous le nom de Super Mario Bros. 2) mais cet épisode n''étant pas sorti à l''époque en Occident, c''est cette adaptation qui a fait office de suite pour les Occidentaux.', 'https://fr.wikipedia.org/wiki/Super_Mario_Bros._2'),
  ('Q856305', 'Bible Adventures est un jeu de plate-forme chrétien non licencié développé et édité par Wisdom Tree. Le jeu est d''abord sorti en 1991 sur NES puis en 1995 sur Mega Drive.', 'https://fr.wikipedia.org/wiki/Bible_Adventures'),
  ('Q4038693', 'Felix the Cat est un jeu vidéo de plates-formes réalisé en 1992 pour Nintendo Entertainment System (NES) et en 1993 pour Game Boy par Hudson Soft. Le jeu est basé sur le dessin animé du même nom Félix le Chat (Felix the Cat).

Konami republie les versions NES et Game Boy sur Nintendo Switch, PlayStation 5 et PlayStation 4, le 28 mars 2024.', 'https://fr.wikipedia.org/wiki/Felix_the_Cat_(jeu_vid%C3%A9o)'),
  ('Q4041647', 'Isolated Warrior, connu au Japon sous le nom Max Warrior: Wakusei Kaigenrei, est un shoot them up en 2D isométrique en vue aérienne développé par KID Corp. et édité par NTVIC au Japon et par Vap Inc. aux États-Unis. Il est sorti au Japon le 15 février 1991 et en Amérique du Nord la même année sur Nintendo Entertainment System.', 'https://fr.wikipedia.org/wiki/Isolated_Warrior'),
  ('Q4045031', 'Varie est un éditeur et développeur de jeux vidéo japonais fondé en 1986 et disparu en 1997. La société édite et développe des jeux sur Game Boy, Famicom, Super Famicom et Mega Drive.', 'https://fr.wikipedia.org/wiki/Varie'),
  ('Q4037585', 'Dragon Fighter est un jeu vidéo, mélangeant l''action - plates-formes et le genre shoot them up, développé par Natsume. Il est distribué le 10 août 1990 au Japon, suivi de l''Amérique du Nord en 1991 sur la console Nintendo.', 'https://fr.wikipedia.org/wiki/Dragon_Fighter_(jeu_vid%C3%A9o)'),
  ('Q4299798', 'Supremacy: Your Will Be Done (intitulé Overlord aux États-Unis) est un jeu vidéo de stratégie en temps réel conçu par David Perry et Nick Bruty et produit par Probe Software. Initialement publié début 1990 sur Amiga et Atari ST, le jeu est ensuite porté sur Commodore 64 et PC en 1991 puis sur Nintendo Entertainment System en 1993. Le jeu se déroule dans un univers de science-fiction. L’objectif est de créer et de protéger des colonies sur diverse planètes tout en essayant de détruire les colonies de l’adversaire.', 'https://fr.wikipedia.org/wiki/Supremacy:_Your_Will_Be_Done'),
  ('Q4051082', 'The Flintstones: The Surprise at Dinosaur Peak est un jeu vidéo de plates-formes par Taito en 1993 sur Nintendo. Il s''agit d''une adaptation de la série d''animation Les Pierrafeu.', 'https://fr.wikipedia.org/wiki/The_Flintstones:_The_Surprise_at_Dinosaur_Peak'),
  ('Q4051552', 'Shatterhand ou Tokkyū Shirei Soruburein au Japon, est un jeu d''action et de plates-formes en 2D à thème de science-fiction. Le jeu a été développé par Natsume et édité par Angel et Jaleco sur NES. Le jeu est sorti le 26 octobre 1991 au Japon suivi de l''Amérique du Nord et l''Europe l''année suivante. Au Japon, il s''agit d''une adaptation de la série télévisée Tokkyū Shirei Soruburein (ja).', 'https://fr.wikipedia.org/wiki/Shatterhand'),
  ('Q4053053', 'Werewolf: The Last Warrior est un jeu vidéo d''action et de plates-formes développé et édité par Data East, sorti en 1990 sur NES.', 'https://fr.wikipedia.org/wiki/Werewolf:_The_Last_Warrior'),
  ('Q4047361', 'Prince of Persia est un jeu vidéo d''action/réflexion et d''aventure en deux dimensions édité par Brøderbund et sorti en 1989 pour le micro-ordinateur 8 bits Apple II. Développé par Jordan Mechner pendant près de quatre ans, il rencontre un fort succès. Traduit en six langues et porté sur une vingtaine de supports, le jeu s''est vendu à plus de deux millions d''exemplaires à travers le monde.

Il est resté célèbre pour la qualité des animations par rapport aux autres jeux de l''époque grâce à l''utilisation de la technique de rotoscopie. Il est le premier épisode de la saga Prince of Persia et le premier épisode du premier cycle de la série.', 'https://fr.wikipedia.org/wiki/Prince_of_Persia_(jeu_vid%C3%A9o,_1989)'),
  ('Q4045164', 'Nekketsu Kakutō Densetsu est un jeu vidéo de combat développé et édité par Technos Japan, sorti en 1992 sur Famicom. C''est un spin-off de la série Kunio-kun.

Le jeu fait partie de la compilation Kunio-kun Nekketsu Complete: Famicom-Hen sortie en 2016 sur Nintendo 3DS.', 'https://fr.wikipedia.org/wiki/Nekketsu_Kakut%C5%8D_Densetsu'),
  ('Q4397217', 'Digger T. Rock (The Legend of the Lost City starring Digger T. Rock sur l''écran de titre) est un jeu vidéo de labyrinthe et de plates-formes développé par Rare et édité par Milton Bradley Company, sorti en 1990 sur NES.', 'https://fr.wikipedia.org/wiki/Digger_T._Rock'),
  ('Q4880213', 'Les jeux vidéo Beetlejuice forment une série de jeux vidéo s''inscrivant dans des genres divers. Ils sont basés sur le film Beetlejuice et ses adaptations.', 'https://fr.wikipedia.org/wiki/Liste_de_jeux_vid%C3%A9o_Beetlejuice'),
  ('Q4998084', 'Burai Fighter (Burai Fighter Deluxe sur Game Boy) est un shoot ''em up à défilement développé et édité par Taxan en 1990 sur NES et sur Game Boy. KID développe une adaptation du jeu, intitulée Space Marauder (Burai Fighter Color au Japon) et éditée par Agetec sur Game Boy Color en août 2000.', 'https://fr.wikipedia.org/wiki/Burai_Fighter'),
  ('Q4922705', 'Super Dodge Ball ou Nekketsu Kōkō Dodgeball Bu au Japon est un jeu de balle aux prisonniers sorti en 1987 sur NES. Développé par Technos Japan, le jeu est basé sur le jeu d''arcade éponyme de 1987.', 'https://fr.wikipedia.org/wiki/Super_Dodge_Ball_(jeu_vid%C3%A9o,_1988)'),
  ('Q5050570', 'Castlequest, ou Castle Excellent au Japon, est un jeu vidéo de plates-formes et de réflexion développé par ASCII Entertainment et édité par Nexoft sur NES et MSX. Il est sorti au Japon le 28 novembre 1986 et en Amérique du Nord en 1989. Il fait suite au jeu The Castle sorti sur ordinateur au Japon.', 'https://fr.wikipedia.org/wiki/Castlequest'),
  ('Q5054998', 'Caveman Ugh-Lympics est un jeu vidéo de sport développé par Dynamix et publié par Electronic Arts en 1988 sur Commodore 64 et PC.', 'https://fr.wikipedia.org/wiki/Caveman_Ugh-Lympics'),
  ('Q5070123', 'Championship Lode Runner est un jeu vidéo de plates-formes développé par Douglas E. Smith et publié par Brøderbund Software en 1983 sur Apple II, Atari 8-bit et Commodore 64. Le jeu fait suite à Lode Runner (1983) dont il reprend à l’identique le système de jeu. Comme dans ce dernier, le joueur contrôle un personnage qui évolue dans des niveaux constitués de différents types de structure (échelles, murs, passerelles) afin de récupérer des lingots tout en échappant aux gardes qui le poursuivent. Le personnage dispose d’un pistolet laser qui lui permet de forer des trous, pour y faire tomber les gardes, ou des murs afin de débloquer de nouveaux passages. Si un garde le touche ou si héros tombe dans un de ses trous, le joueur perd une vie et doit recommencer au début du niveau. S’il parvient à récupérer tous les lingots, une échelle apparait et lui permet d’accéder au niveau suivant. Championship Lode Runner est composé de cinquante niveaux inédit, plus difficiles que ceux du jeu original. Après avoir terminé ces cinquante niveaux, le joueur obtient un mot de passe grâce auquel il peut obtenir un « certificat de champion » personnalisé auprès de Brøderbund Software.', 'https://fr.wikipedia.org/wiki/Championship_Lode_Runner'),
  ('Q5090594', 'NES Play Action Football est un jeu vidéo de football américain développé par TOSE et édité par Nintendo, sorti en 1990 sur NES et Game Boy. Le jeu se nomme Play Action Football sur Game Boy.

Il a pour suite à Super Play Action Football.', 'https://fr.wikipedia.org/wiki/NES_Play_Action_Football'),
  ('Q5162455', 'Conquest of the Crystal Palace (connu au Japon sous le nom Matendo Douji) est un jeu vidéo de plates-formes à thème fantastique en 2D développé et édité par Quest au Japon en août 1990, et édité par Asmik en Amérique du Nord la même année, sur NES.', 'https://fr.wikipedia.org/wiki/Conquest_of_the_Crystal_Palace'),
  ('Q5165990', 'Ghostbusters est un jeu vidéo d''action basé sur le film SOS Fantômes, édité par Activision sur Amstrad CPC, Apple II, Atari 2600, Atari 8-bit, Commodore 64, MSX, DOS, Master System, ZX Spectrum, NES à partir de 1984.', 'https://fr.wikipedia.org/wiki/Ghostbusters_(jeu_vid%C3%A9o,_1984)'),
  ('Q5191424', 'Crystalis, connu au Japon sous le nom God Slayer: Haruka Tenkū no Sonata est un jeu vidéo de rôle de type action-RPG à thème futuro-fantastique en vue aérienne, développé et édité par SNK. Il est sorti au Japon le 13 avril 1990 et en Amérique du Nord la même année. Une version modifiée du jeu est ressortie sur Game Boy Color en 2000', 'https://fr.wikipedia.org/wiki/Crystalis'),
  ('Q5245663', 'Deadly Towers, nommé également Mashō au Japon, est un jeu vidéo de type Action-RPG développé par les sociétés Lenar et Tamtex, et publié par Irem (au Japon, le 15 septembre 1986) et par Broderbund (en Amérique du Nord, en septembre 1987). Il est sorti sur Nintendo Entertainment System.', 'https://fr.wikipedia.org/wiki/Deadly_Towers'),
  ('Q5231241', 'The Tower of Druaga est un jeu vidéo d''action-RPG développé et édité par Namco en juin 1984 sur la borne d''arcade Super Pac-Man.', 'https://fr.wikipedia.org/wiki/The_Tower_of_Druaga'),
  ('Q5248755', 'Decathlon est un jeu de sport sur le thème du décathlon, développé par C&E pour la Nintendo Entertainment System, sorti en 1992.', 'https://fr.wikipedia.org/wiki/Decathlon_(jeu_vid%C3%A9o,_1992)'),
  ('Q5243398', 'Days of Thunder est un jeu vidéo de course développé par Beam Software et édité par Mindscape Group, sorti à partir de 1990 sur DOS, Amiga, Atari ST, Commodore 64, ZX Spectrum, NES, PlayStation 3, Xbox 360 et Game Boy.

Il est adapté du film Jours de tonnerre. Le jeu a fait l''objet d''un remake en 2009 sur iOS (Days of Thunder) et en 2011 sur Xbox 360, PlayStation 3 et PlayStation Portable (Days of Thunder).', 'https://fr.wikipedia.org/wiki/Days_of_Thunder_(jeu_vid%C3%A9o,_1990)'),
  ('Q5236657', 'Milon''s Secret Castle est un jeu vidéo d''action-plates-formes édité et développé par Hudson Soft. Il est sorti en 1986 sur Famicom au Japon et sur Nintendo Entertainment System en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Milon%27s_Secret_Castle'),
  ('Q5305059', 'Dragon''s Lair est un jeu vidéo de plate-formes à défilement horizontal vaguement basé sur le jeu d''arcade éponyme. Il est sorti sur NES et développé par MotiveTime. Le synopsis du jeu est le même que le jeu d''arcade (un chevalier nommé Dirk part seul à l''assaut d''un immense château rempli de monstres pour libérer une princesse, nommée Daphne, retenue prisonnière par un dragon géant).', 'https://fr.wikipedia.org/wiki/Dragon%27s_Lair_(jeu_vid%C3%A9o,_1990)'),
  ('Q5305286', 'Dragon Spirit: The New Legend, connu au Japon sous le nom Dragon Spirit: Aratanaru Densetsu, est un jeu d''action Shoot them up en 2D à défilement vertical développé par Namco et édité sur Amiga, Amstrad CPC, Arcade, Atari ST, Commodore 64, DOS, Sharp X68000, TurboGrafx-16, Wii, ZX Spectrum et NES.. Il s''agit de la suite du jeu Dragon Spirit sorti sur Arcade.', 'https://fr.wikipedia.org/wiki/Dragon_Spirit:_The_New_Legend'),
  ('Q5305307', 'Dragon Wars est un jeu vidéo de rôle développé par Interplay Productions et publié par Activision en 1989. Après avoir terminé de travailler sur The Bard''s Tale III: Thief of Fate, Rebecca Heineman commence à développer un nouveau moteur de jeu destiné à The Bard''s Tale IV. À l’époque, Interplay décide cependant de se tourner vers Activision pour publier leurs nouveaux jeux, dont ce nouvel opus, alors que les trois premiers jeux de la série ont été publiés par Electronic Arts. Ces derniers détenant les droits, Interplay décide donc de rebaptiser le jeu Dragon Wars quelques semaines avant sa sortie afin d’éviter tout conflit avec le précédent. Lorsqu''est choisi ce nouveau nom, le jeu ne contient pas de dragons et Rebecca Heineman doit alors en inclure dans le scénario à la dernière minute.', 'https://fr.wikipedia.org/wiki/Dragon_Wars'),
  ('Q5305282', 'Romancia (également connu sous le nom de Dragon Slayer Jr.) est un jeu vidéo de type action-RPG développé et édité par Nihon Falcom à partir de 1986 sur PC-88, PC-98, MSX, MSX2, Sharp X1, NES et Windows.', 'https://fr.wikipedia.org/wiki/Romancia'),
  ('Q5420074', 'Exerion est un jeu de tir développé et édité par Jaleco en 1983 sur borne d''arcade. Il est porté sur SG-1000 et SC-3000, MSX, et sur NES. Le jeu est réédité sur la console virtuelle de la Wii en 2007, sur la console virtuelle de la Wii U en 2015, et sur PlayStation Network en 2014.', 'https://fr.wikipedia.org/wiki/Exerion'),
  ('Q5319237', 'Dynowarz: The Destruction of Spondylus (Dynowarz: Destruction of Spondylus sur l''écran titre) est un jeu d''action plates-formes en 2D à défilement horizontal à thème mecha. Il a été développé par Advance Communication Co. et édité par Bandai, uniquement en Amérique du Nord en avril 1990.', 'https://fr.wikipedia.org/wiki/Dynowarz:_The_Destruction_of_Spondylus'),
  ('Q5520531', 'Ganbare Goemon! Karakuri Dōchū est un jeu d''action-aventure développé par Konami et sorti au Japon sur NES le 1er août 1986 puis le portage sur MSX2 en 1987.', 'https://fr.wikipedia.org/wiki/Ganbare_Goemon!_Karakuri_D%C5%8Dch%C5%AB'),
  ('Q5512043', 'G.I. Joe: The Atlantis Factor est un jeu vidéo d''action développé par KID et édité par Capcom, sorti en 1992 sur NES. Il est adapté de la gamme de jouets G.I. Joe.', 'https://fr.wikipedia.org/wiki/G.I._Joe:_The_Atlantis_Factor'),
  ('Q5708762', 'Hello Kitty no Hanabatake est un jeu vidéo de type plates-formes destiné aux enfants, développé par Shimada Kikaku. Il a été édité par Character Soft, une filiale d’édition de jeux vidéo de Sanrio, sur Family Computer. Le jeu est sorti exclusivement au Japon le 11 décembre 1992.', 'https://fr.wikipedia.org/wiki/Hello_Kitty_no_Hanabatake'),
  ('Q6073279', 'Ironsword: Wizards and Warriors II est un jeu vidéo de plates-formes développé par Zippo Games et publié sur Nintendo Entertainment System par Acclaim Entertainment en décembre 1989 en Amérique du Nord et en mars 1991 en Europe. Il fait suite à Wizards and Warriors, publié en 1987, dont il reprend les personnages et l’univers. Dans le jeu, le joueur incarne le guerrier Kuros dans sa quête pour vaincre le sorcier démoniaque Malkil. Pour cela, Kuros doit retrouver et assembler les pièces d’une épée magique, la "IronSword". Le jeu a été développé par le fondateur du studio Zippo Games, Ste Pickford, et est le premier jeu que ce dernier développe pour la NES. Pour cela il est assisté par Steve Hughes et David Wise qui a composé la musique du jeu et créé ses effets sonores. À sa sortie, le jeu est très bien accueilli par la presse spécialisée qui salue ses graphismes, ses effets sonores, le niveau de détail des personnages et son système de jeu. Il se vend ainsi à 500 000 exemplaires en Amérique du Nord et à 50 000 exemplaires en Europe. Son succès conduit Zippo Games à développer d’autres jeux pour Rare sur NES dont Solar Jetman: Hunt for the Golden Warpship et Wizards & Warriors III: Kuros: Visions of Power.', 'https://fr.wikipedia.org/wiki/Ironsword:_Wizards_and_Warriors_II'),
  ('Q5664513', 'Hatris est un jeu vidéo de puzzle développé et édité par Bullet-Proof Software sur NES. Le jeu est sorti uniquement en Amérique du Nord en avril 1992. Il a été conçu par l''inventeur de Tetris, Alexey Pajitnov.', 'https://fr.wikipedia.org/wiki/Hatris'),
  ('Q5643982', 'Ys II: Ancient Ys Vanished – The Final Chapter est un jeu vidéo de type action-RPG développé et édité par Nihon Falcom, sorti en 1988 sur DOS, Windows, MSX2, PC-88, PC-98, Sharp X1, PC-Engine, Saturn, NES, PlayStation 2, Console virtuelle (Wii), Nintendo DS, iOS et Android.', 'https://fr.wikipedia.org/wiki/Ys_II:_Ancient_Ys_Vanished_-_The_Final_Chapter'),
  ('Q5554520', 'Getsu Fūma Den (月風魔伝, i.e. "La Légende de Getsu Fūma") est un jeu d''action-aventure à défilement horizontal pour la console Famicom développé par Konami, sorti en 1987, et exclusivement disponible au Japon. Il y est fait référence dans de nombreux titres ultérieurs de Konami au fil des ans. Le jeu est similaire structurellement à Castlevania II: Simon''s Quest et The Goonies II. Une suite intitulée Getsu Fūma Den: Undying Moon (en) est sortie en 2022 sur Steam et Nintendo Switch.', 'https://fr.wikipedia.org/wiki/Getsu_F%C5%ABma_Den'),
  ('Q6131418', 'Wily and Right no RockBoard: That''s Paradise (ou simplement RockBoard) est un jeu vidéo de simulation économique développé et édité par Capcom le 15 janvier 1993 pour la Famicom uniquement au Japon, spin-off de la série originale Mega Man de Capcom. Le gameplay est similaire au jeu de plateau Monopoly, dans lequel les joueurs et l''intelligence artificielle jouent au tour par tour autour d''un ensemble de carrés connectés, achètent des biens et font payer les loyers aux autres participants lorsqu''ils atterrissent sur ces espaces. RockBoard a bénéficié d''une traduction anglaise et d''une version Game Boy en développement, mais n''ont pas été commercialisées. La presse spécialisée a très mal accueilli ce jeu.', 'https://fr.wikipedia.org/wiki/Wily_and_Right_no_RockBoard:_That%27s_Paradise'),
  ('Q6199858', 'Jimmy Connors Tennis, appelé Yannick Noah Tennis sur Game Boy en France, est un jeu vidéo de sport (tennis) développé par NMS Software et édité par Ubisoft, sorti en 1993 sur NES et Game Boy. Le jeu a également été développé sur Lynx par Hand Made Software pour une sortie la même année.

Le jeu tire son nom des joueurs Jimmy Connors et Yannick Noah.', 'https://fr.wikipedia.org/wiki/Jimmy_Connors_Tennis'),
  ('Q6296588', 'Vs. Slalom est un jeu vidéo de ski développé par Rare et publié par Nintendo sur Vs. System en 1986. Il est par la suite publié sous le nom Slalom sur NES en Amérique du Nord en mars 1987 et en Europe plus tard cette même année. Le jeu est développé par Tim et Chris Stamper et la musique est composée par David Wise. Le joueur court dans une série de slaloms en descente et navigue à travers des drapeaux et des obstacles avant l''expiration d''un délai.

Slalom est le premier jeu NES développé à l''extérieur du Japon et le premier jeu des frères Stamper sorti sous la marque Rare. Les magazines des années 1980 jugent Slalom irréaliste, mais apprécient largement ses graphiques et ses animations. Slalom est réédité dans la compilation Rare Replay sur Xbox One.', 'https://fr.wikipedia.org/wiki/Slalom_(jeu_vid%C3%A9o)'),
  ('Q6410984', 'King''s Knight est un jeu vidéo de tir vertical (vertical shooter) développé et édité par Square, sorti en 1986 sur MSX, PC-88, Sharp X1 et NES.', 'https://fr.wikipedia.org/wiki/King%27s_Knight'),
  ('Q6455660', 'L''Empereur (titre original: Ranperūru) est un jeu vidéo de stratégie au tour par tour développé et publié par Koei en 1989 sur MSX, NES, DOS et Sharp X68000. Le joueur y incarne Napoléon Bonaparte pendant les guerres napoléoniennes et a pour objectif de conquérir l’Europe. Au début du jeu, le joueur n’est qu’un simple officier mais ses victoires le font peu à peu monter en grade jusqu’à devenir l’empereur des français, chaque promotion lui donnant des pouvoirs supplémentaires. Le joueur doit mener son armée au combat mais également gérer ses cités et s’occuper de la diplomatie.', 'https://fr.wikipedia.org/wiki/L%27Empereur_(jeu_vid%C3%A9o)'),
  ('Q6494118', 'Last Armageddon est un jeu vidéo de rôle développé par Advance Communication Company et Braingrey.Mind, édité par Yutaka. Il est sorti en 1988 sur DOS, FM Towns, MSX, PC-88, PC-Engine, X68000 et NES.', 'https://fr.wikipedia.org/wiki/Last_Armageddon'),
  ('Q6738119', 'Major League Baseball est un jeu vidéo de sport (baseball) développé par LJN et édité par Atlus, sorti en 1988 sur NES.', 'https://fr.wikipedia.org/wiki/Major_League_Baseball_(jeu_vid%C3%A9o,_1988)'),
  ('Q6826906', 'MiG-29: Soviet Fighter est un jeu vidéo de type rail shooter développé par Codemasters en 1989 et publié pour plusieurs ordinateurs personnels. Une version sans licence a également été publiée pour la NES par Camerica.', 'https://fr.wikipedia.org/wiki/MiG-29:_Soviet_Fighter'),
  ('Q6712166', 'McDonaldland, ou M.C. Kids en Amérique du Nord, est un jeu vidéo de plates-formes développé par Visual Concepts et édité par Ocean Software ou Virgin Interactive selon les versions, en 1992 sur Amiga, Atari ST, NES et Game Boy.

C''est un jeu qui utilise la licence de l''enseigne américaine de restauration rapide McDonald''s.

La version Game Boy n''utilise pas la même licence hors Europe. Elle est éditée par Virgin Interactive et utilise une licence se rattachant à la marque de boisson 7 Up. Elle se nomme Spot: The Cool Adventure en Amérique du Nord et Spot: Cool Adventure au Japon.', 'https://fr.wikipedia.org/wiki/McDonaldland_(jeu_vid%C3%A9o)'),
  ('Q6726002', 'Mad Max est un jeu vidéo d''action développé et édité par Mindscape sur NES en 1990. Le jeu prend place dans l''environnement post-apocalyptique de la franchise Mad Max.', 'https://fr.wikipedia.org/wiki/Mad_Max_(jeu_vid%C3%A9o,_1990)'),
  ('Q6552947', 'Metal Gear est un jeu vidéo d''action-infiltration conçu par Hideo Kojima, développé et édité par Konami sur MSX2 en 1987. Le jeu est adapté sur NES en 1987 et sur Commodore 64 et DOS en 1990.

Considéré comme un précurseur du genre infiltration, le jeu marque les débuts de la série Metal Gear, l''une des plus appréciés et des plus anciennes de l''histoire du jeu vidéo. Une suite directe, Metal Gear 2: Solid Snake, est sorti en 1990 sur MSX2 tandis qu''un épisode non-canonique, Snake''s Revenge, sortait la même année sur NES.', 'https://fr.wikipedia.org/wiki/Metal_Gear_(jeu_vid%C3%A9o)'),
  ('Q6902826', 'Monster Truck Rally, ou Stadium Mud Buggies, est un jeu vidéo de course de monster trucks développé par Realtime Associates et édité par INTV, sorti en 1989 sur les consoles Intellivision et NES. Il s''agit du dernier jeu d''INTV avant sa faillite. La version Intellivision est rééditée en 2021 par Blue Sky Rangers.', 'https://fr.wikipedia.org/wiki/Monster_Truck_Rally'),
  ('Q7352488', 'Robin des Bois, prince des voleurs (Robin Hood: Prince of Thieves) est un jeu vidéo d''action-aventure développé par Sculptured Software et édité par Virgin Games, sorti en 1991 sur NES et Game Boy.

Il est adapté du film du même nom.', 'https://fr.wikipedia.org/wiki/Robin_des_Bois,_prince_des_voleurs_(jeu_vid%C3%A9o)'),
  ('Q7134983', 'Varie est un éditeur et développeur de jeux vidéo japonais fondé en 1986 et disparu en 1997. La société édite et développe des jeux sur Game Boy, Famicom, Super Famicom et Mega Drive.', 'https://fr.wikipedia.org/wiki/Varie'),
  ('Q7038930', 'Ninja Jajamaru-kun (parfois stylisé Ninja JaJaMaru-kun) est une série de jeux vidéo créée par Ryuichi Nishizawa chez UPL Corporation avant d''être reprise par Hamster Corporation et Jaleco. Les jeux de la série mêlent plates-formes et action. Ils mettent en scène Ninja-kun (aussi appelé Taro ou Maru), un petit ninja vêtu de rouge.', 'https://fr.wikipedia.org/wiki/Ninja_Jajamaru-kun'),
  ('Q7537365', 'Sky Kid est un jeu vidéo de type shoot ''em up développé et édité par Namco, sorti en 1985 sur borne d''arcade, NES et Epoch Cassette Vision.', 'https://fr.wikipedia.org/wiki/Sky_Kid'),
  ('Q7601015', 'Star Trek: The Next Generation est un jeu vidéo de simulation développé et édité par Absolute Entertainment, sorti en 1993 sur NES et Game Boy. Le jeu est adapté de la série Star Trek: La Nouvelle Génération.', 'https://fr.wikipedia.org/wiki/Star_Trek:_The_Next_Generation_(jeu_vid%C3%A9o)'),
  ('Q7653353', 'Swamp Thing est un jeu d''action plates-formes 2D sorti sur NES et Game Boy en 1992, qui met en scène des super héros. Développé par Imagineering (version NES) et par Equilibrium (version Game Boy) et édité par THQ, c''est une adaptation du comic et dessin animé éponyme.', 'https://fr.wikipedia.org/wiki/Swamp_Thing_(jeu_vid%C3%A9o)'),
  ('Q7715623', 'The Bard''s Tale II: The Destiny Knight est un jeu vidéo de type dungeon crawler développé par Interplay Productions et publié par Electronic Arts en 1986.

C’est la suite de The Bard''s Tale, premier opus de la série dont il reprend l’univers médiéval fantastique (inspiré de Donjons et Dragons) et le système de jeu. Il est le dernier épisode de la série à avoir été conçu et programmé par Michael Cranford (en).', 'https://fr.wikipedia.org/wiki/The_Bard%27s_Tale_II:_The_Destiny_Knight'),
  ('Q7805036', 'Time Lord un jeu vidéo d''action/plates-formes de type Beat them all futuriste développé par Rare et édité par Milton Bradley, le fabricant de jeux de société. Il est sorti sur NES en Amérique du Nord le 1er septembre 1990, suivi de l''Europe en octobre 1991.', 'https://fr.wikipedia.org/wiki/Time_Lord'),
  ('Q7757819', 'The Portopia Serial Murder Case est un jeu vidéo de type aventure et visual novel développé par Chunsoft et édité par Enix, sorti à partir de 1983 sur FM-7, FM-8, MSX, NEC PC-6001, PC-88, Sharp X1, NES et téléphone mobile.

Il est considéré comme le jeu initiateur du genre visual novel.', 'https://fr.wikipedia.org/wiki/The_Portopia_Serial_Murder_Case'),
  ('Q7761289', 'The Rocketeer est un jeu vidéo d''action et de plates-formes développé par Ironwind Software et édité par Bandai, sorti en 1991 sur NES.

Il est basé sur le film Les Aventures de Rocketeer.', 'https://fr.wikipedia.org/wiki/The_Rocketeer_(jeu_vid%C3%A9o)'),
  ('Q7806576', 'Times of Lore est un jeu vidéo de type action-RPG et de thème heroic fantasy développé par Origin Systems et édité par Toho Co. Ltd. Il a été conçu par Chris Roberts. Il est sorti sur Famicom au Japon le 7 décembre 1990, suivi de l''Amérique du Nord sur NES en mai 1991. Le jeu est aussi sorti sur d''autres plateformes, telles que, Amstrad CPC, Commodore 64, Apple II, Atari ST, Amiga et ZX Spectrum à partir de 1988.', 'https://fr.wikipedia.org/wiki/Times_of_Lore'),
  ('Q7975976', 'Wayne''s World est un jeu vidéo de plates-formes sorti en 1993 sur Game Boy, Mega Drive, Nintendo Entertainment System et Super Nintendo. Le jeu a été développé par Radical Entertainment et édité par THQ.

Il est basé sur le film Wayne''s World de Penelope Spheeris sorti en 1992.', 'https://fr.wikipedia.org/wiki/Wayne%27s_World_(jeu_vid%C3%A9o)'),
  ('Q7884786', 'Hydlide ou The Legend of Hydlide est un jeu vidéo développé par T&E Soft sorti à l’origine sur NEC PC-6001 et NEC PC-8801 en 1984, au Japon uniquement. Une sortie MSX vint l’année suivante, puis une version Famicom d’abord sous le nom Hydlide Special en mars 1986 au Japon, et trois ans plus tard, en juin 1989, cette version vit le jour aux États-Unis, de nouveau sous le nom d’Hydlide.', 'https://fr.wikipedia.org/wiki/Hydlide_(jeu_vid%C3%A9o)'),
  ('Q8028765', 'Wizardry III: Legacy of Llylgamyn est un jeu vidéo de type dungeon crawler développé et publié par Sir-Tech à partir de 1983 sur Apple II, Commodore 64, DOS, NES, PC booter, PC-98 et Game Boy Color. Le jeu est le troisième opus de la série Wizardry. Techniquement, le jeu est quasiment identique à ses deux prédécesseurs. Le joueur y incarne des descendants des personnages des deux premiers épisodes et doit explorer les six niveaux d’un donjon afin de retrouver le dragon L''Kbreth dont l’orbe magique peut protéger la cité de Llylgamyn contre la récente recrudescence de tremblements de terre et d’éruptions volcaniques. Comme dans Wizardry II: The Knight of Diamonds, le joueur peut importer ses personnages des précédents épisodes mais leur expérience est remise à zéro puisqu’ils incarnent une nouvelle génération d’aventuriers. Un rite de passage leur permet cependant de recevoir des bonus. Ils peuvent également changer d’alignement, celui-ci déterminant quelles zones ils peuvent explorer. Une des originalités du jeu réside dans le fait que le joueur commence dans les profondeurs du donjon et qu’il doit donc remonter jusqu’à la surface. Le jeu inclut plusieurs références aux précédents épisodes, comme le temple de Cant et la boutique de Boltac.', 'https://fr.wikipedia.org/wiki/Wizardry_III:_Legacy_of_Llylgamyn'),
  ('Q7997606', 'Whomp ''Em est un jeu vidéo de genre action et plates-formes développé par la société Jaleco et sorti sur NES en 1991. C''est la version américaine du jeu japonais Saiyūki World 2: Tenjōkai no Majin sorti en 1990.

Le jeu met en scène un amérindien devant retrouver six éléments de sa tribu disséminés dans de multiples tableaux.', 'https://fr.wikipedia.org/wiki/Whomp_%27Em'),
  ('Q8028773', 'Wizards and Warriors III: Kuros: Visions of Power est un jeu vidéo de plates-formes développé par Zippo Games et publié sur Nintendo Entertainment System par Acclaim Entertainment en mars 1992 en Amérique du Nord et en janvier 1993 en Europe. Il est le troisième et dernier épisode de la série Wizards and Warriors et fait suite à Wizards and Warriors et Ironsword: Wizards and Warriors II. Le jeu se déroule juste après les événements d’Ironsword alors que le guerrier Kuros vient juste de vaincre le sorcier Malkil. Ignorant que l’esprit du sorcier est encore intact, Kudos est touché par un sort qui lui fait perdre son armure, sa mémoire et son honneur. Le jeu a été développé par les fondateurs du studio Zippo Games, Ste et John Pickford. Ils le conçoivent comme un hommage au jeu Atic Atac d’Ultimate Play the Game et s’inspirent notamment d’autres titres publiés sur NES comme Metroid, Faxanadu, and Super Mario Bros. 3. À sa sortie, le jeu est très bien accueilli par la presse spécialisée qui salue ses graphismes, son gameplay et son niveau de difficulté. Il se vend plutôt bien mais ne rencontre pas le succès de son prédécesseur. Racheté pendant le développement par Rare, Zippo Games ferme ses portes peu de temps après la sortie du jeu. Une suite était initialement prévue mais celle-ci n’a jamais été développée.', 'https://fr.wikipedia.org/wiki/Wizards_and_Warriors_III:_Kuros:_Visions_of_Power'),
  ('Q8030537', 'Wolverine est un jeu vidéo d''action développé par Software Creations et édité par LJN sorti en 1991 sur NES.', 'https://fr.wikipedia.org/wiki/Wolverine_(jeu_vid%C3%A9o)'),
  ('Q9089201', 'Totally Rad, sorti au Japon sous le nom de Magic John, est un jeu d''action plates-formes en 2D, développé par Aicom et publié par Jaleco. Il est sorti au Japon sur Famicom le 28 septembre 1990, suivi de l''Europe et l''Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Totally_Rad'),
  ('Q8762678', 'New Ghostbusters II est un jeu vidéo d''action tiré du film SOS Fantômes 2 sorti en 1989 au cinéma. Il est développé et édité par HAL Laboratory sur Nintendo en 1990 en Europe et au Japon.

La même année, un autre jeu édité par Activision, nommé Ghostbusters II, est sorti en Amérique du Nord et en Europe sur diverses plates-formes ainsi que sur NES.', 'https://fr.wikipedia.org/wiki/New_Ghostbusters_2'),
  ('Q8037625', 'Wrath of the Black Manta est un jeu vidéo d''action et de plates-formes développé par AI et édité par Kyugo, sorti en 1989 sur NES.', 'https://fr.wikipedia.org/wiki/Wrath_of_the_Black_Manta'),
  ('Q9358285', 'The Ultimate Stuntman est un jeu vidéo d''action développé par Camerica et édité par Codemasters, sorti en 1990 sur NES.', 'https://fr.wikipedia.org/wiki/The_Ultimate_Stuntman'),
  ('Q11278253', 'The Krion Conquest, ou Magical Kids Doropie au Japon, est un jeu vidéo d''action/plates-formes développé et édité par Vic Tokai sur la console 8 bits Nintendo. Il est sorti au Japon le 14 décembre 1990, puis en Amérique du Nord l''année suivante', 'https://fr.wikipedia.org/wiki/The_Krion_Conquest'),
  ('Q11233573', 'Uncharted Waters est un jeu vidéo de rôle sorti à partir de 1990 sur DOS, Mac, FM Towns, MSX, PC-88, PC-98, Sharp X1, X68000, Mega Drive, NES et Super Nintendo. Le jeu a été développé et édité par Koei. Il a pour suite Uncharted Waters II: New Horizons.', 'https://fr.wikipedia.org/wiki/Uncharted_Waters'),
  ('Q11319329', 'Tetris 2, ou Tetris Flash au Japon, est un jeu vidéo de puzzle développé par Nintendo R&D1 et édité par Nintendo, sorti en 1993 sur NES, Super Nintendo et Game Boy.', 'https://fr.wikipedia.org/wiki/Tetris_2'),
  ('Q11322994', 'Legacy of the Wizard est un jeu vidéo de type action-RPG développé par Nihon Falcom à partir de 1987 sur MSX, MSX2 et NES.', 'https://fr.wikipedia.org/wiki/Legacy_of_the_Wizard'),
  ('Q11301528', 'Ninja kid (GeGeGe no Kitaro - Yōkai Daimakyō) est un jeu d''action plates-formes qui se déroule dans un univers inspiré de mythologie japonaise. Il s''agit d''une adaptation du manga et anime Kitaro le repoussant de Shigeru Mizuki. Le jeu a été développé par TOSE et édité par Bandai pour la Nintendo Entertainment System. Il est sorti le 17 avril 1986 au Japon et en Octobre 1986 en Amérique.', 'https://fr.wikipedia.org/wiki/Ninja_Kid'),
  ('Q11286214', 'Puyo Puyo est un jeu vidéo de puzzle de la série Puyo Puyo, dérivé de Columns, développé par Compile, sorti en 1991 sur MSX2 et Famicom Disk System. Sega commercialise une version sur borne d''arcade en 1992, qui devient le jeu le plus populaire au Japon en Arcade avant l''arrivée de Street Fighter 2[réf. nécessaire]. Cette version est adaptée sur divers systèmes familiaux.

Les personnages de ce jeu, sont ceux d''un donjon RPG du même développeur, Madou Monogatari (en), qui n''est jamais sorti du Japon.

Le succès du jeu engendre une flopée de suites. Il inspire aussi d''autres séries au point qu''on rencontre parfois le terme « Puyo Puyo-like ». Une suite sort sous le nom Puyo Puyo 2.', 'https://fr.wikipedia.org/wiki/Puyo_Puyo_(jeu_vid%C3%A9o)'),
  ('Q16683360', 'Willow est un jeu vidéo de type action-RPG développé et édité par Capcom en 1989 sur Nintendo. C''est un dérivé du film américain Willow sorti en 1988 au cinéma.', 'https://fr.wikipedia.org/wiki/Willow_(jeu_vid%C3%A9o,_NES)'),
  ('Q16913800', 'Super Hydlide est un jeu de rôle de type action-RPG développé par T&E Soft et édité par Seismic Software, sorti sur Mega Drive en 1991 en Europe, 1990 aux États-Unis, et 1989 au Japon.

Il s''agit d''un portage du jeu Hydlide 3: The Space Memories, sorti uniquement au Japon sur différentes plateformes à partir de 1987. Par la suite, d''autres versions plus abouties sortiront sous le nom de Hydlide 3 Special Version et Hydlide 3 Gold Pack toujours seulement au Japon. Super Hydlide est la seule version à avoir vu le jour en Europe.

Cette suite met à jour tous les aspects des premiers opus d''Hydlide. Avant sa sortie, le jeu était appelé Hollo Fighter dans certaines publicités de Sega pour la Mega Drive.', 'https://fr.wikipedia.org/wiki/Super_Hydlide'),
  ('Q17190863', 'Genghis Khan (titre original: Aoki Ōkami to Shiroki Mejika: Genghis Khan) est un jeu vidéo de stratégie au tour par tour développé et publié par Koei en 1987 sur NEC PC-9801 puis porté sur MSX, NES, Amiga et MS-DOS. Il fait suite à Aoki Ōkami to Shiroki Mejika, publié sur PC-88, PC-98 et MSX en 1985. À sa sortie, le jeu est plutôt bien accueilli par la presse spécialisée, le magazine Computer Gaming World saluant par exemple sa difficulté, sa richesse et son réalisme historique.

Le jeu a bénéficié de plusieurs suites, dont Genghis Khan II: Clan of the Gray Wolf publié en 1992.', 'https://fr.wikipedia.org/wiki/Genghis_Khan_(jeu_vid%C3%A9o)'),
  ('Q17177267', 'Disney''s TaleSpin est un jeu vidéo de type shoot them up, tiré de la série télévisée Super Baloo créée par Disney. Le jeu fut édité par Capcom sur Nintendo Entertainment System en 1991 et sur Game Boy en 1992.

Le 16 mars 2017, Capcom annonce la ressortie le 18 avril de plusieurs titres phares 8 bits de Disney Interactive des années 1990 sous le nom The Disney Afternoon Collection sur Xbox One, PlayStation 4 et PC dont Disney''s Darkwing Duck, Disney''s DuckTales, Disney''s DuckTales 2, Disney''s Chip''n Dale: Rescue Rangers, Disney''s Chip''n Dale: Rescue Rangers 2 et Disney''s TaleSpin.', 'https://fr.wikipedia.org/wiki/Disney%27s_TaleSpin_(jeu_vid%C3%A9o,_1991)'),
  ('Q16266830', 'Faria: A World of Mystery and Danger!, ou Faria: Fuuin no Tsurugi au Japon, est un jeu vidéo de rôle action-RPG en vue aérienne. Il a été développé par Game Arts et édité par Hi-Score Media Works et Nexoft pour la NES. Le jeu est sorti au Japon le 21 juillet 1989 et en Amérique du Nord en juin 1991.', 'https://fr.wikipedia.org/wiki/Faria:_A_World_of_Mystery_and_Danger!'),
  ('Q16267515', 'Wayne Gretzky Hockey est un jeu vidéo de sport (hockey sur glace) développé et édité par Bethesda Softworks, sorti en 1988 sur DOS, Mac, Amiga, Atari ST et NES.

Il tient son nom du joueur Wayne Gretzky et a pour suite Wayne Gretzky Hockey II et Wayne Gretzky Hockey 3.', 'https://fr.wikipedia.org/wiki/Wayne_Gretzky_Hockey'),
  ('Q17494453', 'Aladdin est un jeu vidéo de plates-formes développé et édité par Virgin Interactive en 1993 sur Mega Drive. Des versions Amiga 1200, DOS, Game Boy et NES ont également vu le jour. Il s''agit d''un des trois jeux réalisés d''après le film du même nom de Walt Disney Pictures, aux côtés de Aladdin pour Super Nintendo et Game Boy Advance, et de Aladdin pour Master System et Game Gear.', 'https://fr.wikipedia.org/wiki/Aladdin_(Virgin)'),
  ('Q21039932', 'Super Turrican est un jeu vidéo de type run and gun développé par Rainbow Arts et édité par Imagineer, sorti en 1992 sur NES.', 'https://fr.wikipedia.org/wiki/Super_Turrican_(NES)'),
  ('Q16205201', 'Where in Time Is Carmen Sandiego? est un jeu vidéo d''aventure éducatif, développé et édité par Brøderbund en 1989. Le jeu fait partie de la franchise Carmen Sandiego.

Le joueur incarne un enquêteur d''Interpol qui parcourt le globe pour arrêter Carmen Sandiego et les membres de son organisation. L''aventure prend la forme d''un jeu de piste mais à la différence de l''épisode original, Where in the World Is Carmen Sandiego?, le joueur ne doit plus simplement déduire la localisation des malfrats mais aussi l''époque à laquelle ils se trouvent.', 'https://fr.wikipedia.org/wiki/Where_in_Time_Is_Carmen_Sandiego%3F'),
  ('Q15036792', 'Hudson Hawk est un jeu vidéo de plates-formes développé par Special FX Ltd. et édité par Ocean Software, sorti en 1991 sur Amiga, Amstrad CPC, Atari ST, Commodore 64, ZX Spectrum, NES et Game Boy.

Il est basé sur le film Hudson Hawk, gentleman et cambrioleur.', 'https://fr.wikipedia.org/wiki/Hudson_Hawk_(jeu_vid%C3%A9o)'),
  ('Q15036769', 'Shanghai est un jeu vidéo de réflexion développé et publié par Activision à partir de 1986 sur Amiga, Amstrad CPC, Apple II, Atari 8-bit, Atari ST, borne d''arcade, Commodore 64, FM Towns, Game Boy, IBM PC, Lynx, Macintosh, Master System, MSX, NES, PC-88, PC-98, PC-Engine, Sharp X1, Tandy 1000 et X68000.

Il s’agit d’une variante du mah-jong qui se joue avec des tuiles similaires. Au début d’une partie, le programme répartit 144 tuiles, chaque type de tuile existant en quatre exemplaires, de manière aléatoire sur une pile de cinq étages.

Le joueur doit ensuite retirer ces tuiles par paires jusqu’à ce qu’il n’en reste plus où jusqu’à ce qu’il ne soit plus possible d’apparier deux tuiles. De plus, les tuiles ne peuvent être retirées que lorsqu’elles sont sur les bords de la pile. Ainsi, si une tuile est bordée de deux autres tuiles se trouvant au même étage qu’elle, elle est bloquée et ne peut être retirée. Plusieurs modes de jeu sont proposés: en solitaire, par équipe, tournoi et défi. Le mode par équipe est similaire au jeu en solitaire à la différence que les joueurs retirent des tuiles chacun à leur tour. Le mode tournoi permet d’imposer une limite de temps à la partie. En mode défi, chaque joueur dispose d’un temps limité pour jouer son coup.', 'https://fr.wikipedia.org/wiki/Shanghai_(jeu_vid%C3%A9o,_1986)'),
  ('Q16259540', 'Flying Warriors est un jeu d''action et de combat en 2D développé et édité par Culture Brain en 1991 sur NES, sorti uniquement en Amérique du Nord en février 1991. Il s''agit de la suite de Flying Dragon: The Secret Scroll dans la série Hiryū no Ken.', 'https://fr.wikipedia.org/wiki/Flying_Warriors'),
  ('Q67198438', 'RBI Baseball (en Amérique du Nord, ou Pro Yakyū Family Stadium au Japon) est un jeu vidéo de baseball sorti en 1986. Il a été développé par Namco et édité par Tengen.', 'https://fr.wikipedia.org/wiki/R.B.I._Baseball'),
  ('Q67387683', 'Tetris est un jeu vidéo de puzzle développé et édité par Nintendo sur Nintendo Entertainment System, commercialisé en Amérique du Nord en novembre 1989 puis en Europe en février 1990. Le jeu est une adaptation du concept de Alekseï Pajitnov imaginé à partir de 1984.

Publié après une bataille légale entre Nintendo et Atari Games, ce jeu est aussi la première version de Tetris publiée par Nintendo en Europe, tandis qu''aux États-Unis, elle arrive un peu après la version Game Boy.', 'https://fr.wikipedia.org/wiki/Tetris_(NES)'),
  ('Q63865490', 'Zen: Intergalactic Ninja est un jeu vidéo d''action et de plates-formes développé et édité par Konami, sorti en 1993 sur NES et Game Boy.

Il est basé sur le comics Zen: Intergalactic Ninja.', 'https://fr.wikipedia.org/wiki/Zen:_Intergalactic_Ninja_(jeu_vid%C3%A9o)'),
  ('Q104898442', 'Varie est un éditeur et développeur de jeux vidéo japonais fondé en 1986 et disparu en 1997. La société édite et développe des jeux sur Game Boy, Famicom, Super Famicom et Mega Drive.', 'https://fr.wikipedia.org/wiki/Varie'),
  ('Q54320', 'Star Wars est un jeu vidéo de plates-formes, sorti à partir de 1991 sur NES, Game Boy, Master System et Game Gear.', 'https://fr.wikipedia.org/wiki/Star_Wars_(jeu_vid%C3%A9o,_1991)'),
  ('Q55532', '1942 est un jeu vidéo de type shoot ''em up à défilement vertical sorti en 1984 sur système d''arcade Z80 Based de Capcom, puis porté par la suite sur de nombreuses autres machines. Il s''agit du premier jeu développé par Yoshiki Okamoto pour Capcom.

Il a fait l''objet d''un remake en 2008 sur PlayStation 3 et Xbox 360: 1942: Joint Strike.', 'https://fr.wikipedia.org/wiki/1942_(jeu_vid%C3%A9o)'),
  ('Q54319', 'Star Wars est un jeu vidéo de plates-formes développé et édité par Namco au Japon en 1987 sur NES.', 'https://fr.wikipedia.org/wiki/Star_Wars_(jeu_vid%C3%A9o,_1987)'),
  ('Q27296', 'Bio Miracle Bokutte Upa est un jeu vidéo de Konami publié pour la première fois sur le marché japonais en 1988 pour le Famicom Disk System. Il a été publié de nouveau en cartouche de jeu en 1993 pour la Famicom.

Bio Miracle Bokutte Upa avait aussi été prévu pour le marché américain en 1989, mais Howard Philips de Nintendo l''a rejeté, mentionnant que le jeu n''était pas assez bon pour ce marché.

Également créé dans les téléphones mobiles en 2006.', 'https://fr.wikipedia.org/wiki/Bio_Miracle_Bokutte_Upa'),
  ('Q54329', 'Star Wars: The Empire Strikes Back est un jeu vidéo d''action édité par JVC, sorti en 1992 sur NES et Game Boy.

Le jeu est adapté de Star Wars, épisode V: L''Empire contre-attaque.', 'https://fr.wikipedia.org/wiki/Star_Wars:_The_Empire_Strikes_Back_(jeu_vid%C3%A9o,_1992)'),
  ('Q11168', 'Super Mario Bros. est un jeu vidéo de plates-formes à défilement horizontal développé par Nintendo R&D4 et édité par Nintendo. Il est sorti sur Famicom au Japon en 1985 puis sur Nintendo Entertainment System en Amérique du Nord la même année et en 1987 en Europe. Il s''agit du premier jeu de la série Super Mario.

Le joueur contrôle Mario et voyage à travers le Royaume Champignon afin de sauver la princesse Peach des griffes de Bowser, l''antagoniste de Mario. Le jeu est jouable à deux joueurs, le premier contrôlant Mario et le second Luigi, le frère de ce dernier. Le jeu est composé de huit mondes qui contiennent chacun quatre niveaux dans lesquels le joueur doit naviguer du côté gauche vers le côté droit de l''écran afin d''atteindre la fin du niveau pour accéder au suivant. Mario possède plusieurs habiletés, comme sauter et courir, et peut récupérer des power-ups.', 'https://fr.wikipedia.org/wiki/Super_Mario_Bros.'),
  ('Q12395', 'The Legend of Zelda (litt.La Légende de Zelda, ou simplement Zelda) est un jeu d''action-aventure développé et édité par Nintendo le 21 février 1986 au Japon sur Famicom Disk System, l''extension de la Famicom, puis sur NES le 22 août 1987 aux États-Unis et en novembre 1987 en Europe. Il s''agit du premier épisode de la série homonyme.

Dans un univers de médiéval fantastique appelé Hyrule, Link doit récupérer les huit fragments de la Triforce de la sagesse afin de vaincre Ganon, délivrer la princesse Zelda et ramener la paix dans le royaume. Durant le jeu, Link se déplace librement et sans indication dans une carte du monde affichée en vue de dessus, mais explore également plusieurs donjons labyrinthiques souterrains. Le royaume d''Hyrule est habité par de nombreux monstres que Link doit combattre, et recèle de nombreux secrets et énigmes à résoudre, ce qui permet à Link de découvrir des objets utiles à son avancement dans la quête ou des armes améliorant ses capacités. L''exploration et la découverte de secrets sont le cœur de l''expérience de jeu. Lorsque le joueur a fini la partie, il peut recommencer le jeu dans une aventure remaniée appelée « seconde quête » comportant des donjons et une carte du monde modifiés ainsi que des ennemis plus coriaces.', 'https://fr.wikipedia.org/wiki/The_Legend_of_Zelda_(jeu_vid%C3%A9o)'),
  ('Q12384', 'Donkey Kong, est un jeu vidéo d''arcade créé par Nintendo en 1981. C''est un des premiers jeux de plates-formes, précédé dans le même genre par Space Panic et Apple Panic. L''intérêt est centré sur le déplacement d''un personnage principal à travers quatre niveaux en évitant des obstacles mouvants. Si le scénario est simple, il est suffisamment développé pour l''époque: Mario, appelé alors Jumpman, doit secourir une demoiselle en détresse, capturée par un gorille géant, Donkey Kong. Les deux personnages qu''il introduit sont appelés à devenir deux icônes de la marque Nintendo.

Le jeu résulta des efforts de Nintendo pour s''imposer sur le marché nord-américain; son président, Hiroshi Yamauchi, a donné le projet à l''un de ses nouveaux game designer, Shigeru Miyamoto. Fortement inspiré par la culture américaine, à travers les personnages de Popeye et de King Kong, Miyamoto développa le scénario et dirigea la programmation du jeu aux côtés de l''ingénieur en chef Gunpei Yokoi. Les deux concepteurs y introduisirent deux innovations: les cinématiques et les niveaux de jeu multiples.', 'https://fr.wikipedia.org/wiki/Donkey_Kong_(jeu_vid%C3%A9o,_1981)'),
  ('Q55605', 'Boulder Dash est un jeu vidéo conçu par Peter Liepa (en) et Chris Gray, et édité par First Star Software (en) à partir de 1984 sur de nombreux supports. En juillet 2017, les droits de Boulder Dash ont été transférés de First Star Software à la société allemande BBG Entertainment.', 'https://fr.wikipedia.org/wiki/Boulder_Dash_(jeu_vid%C3%A9o)'),
  ('Q55535', '1943: The Battle of Midway est un jeu vidéo de type shoot them up à défilement vertical développé et édité par Capcom sur le système d''arcade Commando, sorti en 1987. Il a été conçu par Yoshiki Okamoto. Il fut porté sur Amiga, Amstrad CPC, Atari ST, Commodore 64, Nintendo Entertainment System et ZX Spectrum en 1988. La même année, une version remaniée du jeu est sortie en salle d''arcade au Japon, 1943 Kai: Midway Kaisen. Celle-ci fut adaptée sur PC Engine en mars 1991.', 'https://fr.wikipedia.org/wiki/1943:_The_Battle_of_Midway'),
  ('Q55815', 'Elite est un jeu vidéo de commerce et de combat spatial édité à l''origine par Acornsoft sur BBC Micro en 1984 puis porté sur beaucoup d''autres ordinateurs. Écrit et développé par David Braben et Ian Bell, Elite est considéré par certains comme l''un des jeux les plus innovants de l''histoire du jeu vidéo.', 'https://fr.wikipedia.org/wiki/Elite_(jeu_vid%C3%A9o)'),
  ('Q55610', 'Athena est un jeu vidéo de plate-forme développé et édité par SNK, sorti en 1986 sur borne d''arcade (sur le système Ikari Warriors). Le jeu sera, plus tard, porté sur Amstrad CPC, ZX Spectrum et Commodore 64 par Ocean Software sous leurs label Imagine Software, puis sur NES par Micronics en 1987. Seule la version NES est sortie en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Athena_(jeu_vid%C3%A9o)'),
  ('Q1989599', 'The Addams Family est un jeu vidéo de plates-formes développé et édité par Ocean Software en 1992 sur Amiga, Amstrad CPC, Atari ST, Commodore 64, Game Boy, Game Gear, Master System, Mega Drive, Nintendo Entertainment System, Super Nintendo et ZX Spectrum. Le jeu repose sur le film La Famille Addams.

Les versions Amstrad CPC, Commodore 64 et ZX Spectrum sont modifiées par rapport à la version originale parue sur Super Nintendo, ces trois versions ne contiennent pas de scrolling, les écrans s''affichent en un seul coup lorsque le personnage change de pièce. Des options sont ajoutées, le joueur peut choisir le niveau de jeu, le mode contrôle et la possibilité de continuer une partie après un Game Over.', 'https://fr.wikipedia.org/wiki/The_Addams_Family_(jeu_vid%C3%A9o)'),
  ('Q1255124', 'DragonStrike est un jeu vidéo de rôle et de simulation de vol développé et publié par Strategic Simulations (SSI) en 1990 sur Amiga, Commodore 64 et MS-DOS et en 1992 sur NES. Le jeu est basé sur le jeu de rôle médiéval-fantastique Donjons et Dragons, publié par TSR. Il se déroule dans l''univers de Lancedragon, un décor de campagne du jeu de rôle Donjons et Dragons, pendant la Guerre de la Lance qui fait rage dans le monde de Krynn. Le joueur contrôle un chevalier combattant à dos de dragon métallique, le jeu combinant des éléments de jeu de rôle et de simulation de vol à dos d''un dragon.', 'https://fr.wikipedia.org/wiki/DragonStrike'),
  ('Q388929', 'After Burner est un jeu vidéo de type shoot ''em up développé par Sega-AM2 et édité par Sega, sorti en 1987 sur borne d''arcade. Il fut ensuite porté sur 32X, Amiga, Amstrad CPC, Atari ST, Commodore 64, PC (DOS), FM Towns, Master System, MSX, Nintendo Entertainment System et ZX Spectrum. Il fait partie de la série After Burner, dont il constitue le premier épisode.', 'https://fr.wikipedia.org/wiki/After_Burner_(jeu_vid%C3%A9o)'),
  ('Q3986143', 'The Bugs Bunny Crazy Castle (en français - « Le château déjanté de Bugs Bunny »), également connu sous le nom de Roger Rabbit ou de Mickey Mouse, est un jeu vidéo d''action et de réflexion, édité par Kemco sur Nintendo en 1989, puis sur Game Boy en 1990.

Il s''agit du premier épisode d''une série de jeux vidéo de dix titres, sortis sous des noms différents suivant les continents.', 'https://fr.wikipedia.org/wiki/The_Bugs_Bunny_Crazy_Castle'),
  ('Q948387', 'Captain America and the Avengers (Captain America et les Vengeurs) est un beat them all développé par Data East, sorti sur arcade en 1991, puis sur Game Gear, Mega Drive, Nintendo Entertainment System et Super Nintendo.', 'https://fr.wikipedia.org/wiki/Captain_America_and_the_Avengers'),
  ('Q3061894', 'Exed Exes est un jeu vidéo de type shoot ''em up à scrolling vertical développé et édité par Capcom, sorti en février 1985 sur système d''arcade: Z80 Based. Il est sorti aux États-Unis sous le nom Attack of the Savage Bees (ou plus simplement Savage Bees). Il a ensuite été porté sur Famicom la même année.

Il a été inclus sur les compilations Capcom Generations Vol. 3 pour Saturn et PlayStation, puis sur Capcom Classics Collection Vol. 1 pour PlayStation 2 et Xbox, et sur Capcom Classics Collection: Reloaded pour PlayStation Portable.', 'https://fr.wikipedia.org/wiki/Exed_Exes'),
  ('Q734758', 'Gauntlet est un jeu vidéo développé et édité par Atari Games en 1985 sur borne d''arcade. Considéré comme un classique du jeu d''arcade, Gauntlet est un jeu d''action qui a la particularité d''être jouable à quatre en simultané. Il fut porté sur de nombreux supports familiaux.

Le jeu a eu une suite en 1986, Gauntlet II.', 'https://fr.wikipedia.org/wiki/Gauntlet_(jeu_vid%C3%A9o,_1985)'),
  ('Q3101570', 'George Foreman''s KO Boxing est un jeu vidéo de boxe sorti en 1992 et fonctionne sur Game Boy, Game Gear, Master System, Mega Drive, Nintendo Entertainment System et Super Nintendo. Le jeu a été développé et édité par Flying Edge pour Sega et développé par Beam Software et édité par Acclaim Entertainment chez Nintendo.', 'https://fr.wikipedia.org/wiki/George_Foreman%27s_KO_Boxing'),
  ('Q3389134', 'Pirate Ship Higemaru est un jeu vidéo de puzzle sorti en 1984 sur système d''arcade Z80 Based. Le jeu a été développé et édité par Capcom. Il a connu une suite sur NES et MSX2 portant le nom Higemaru Makaijima: Nanatsu no Shima Daibouken.', 'https://fr.wikipedia.org/wiki/Pirate_Ship_Higemaru'),
  ('Q3140325', 'Hook est un jeu vidéo d''action édité par Sony Imagesoft en 1992. Le jeu fonctionne sur Mega Drive, Mega-CD, Nintendo, Super Nintendo, Game Boy et Game Gear.

Le jeu est basé sur le film Hook ou la Revanche du Capitaine Crochet de Steven Spielberg.', 'https://fr.wikipedia.org/wiki/Hook_(jeu_vid%C3%A9o,_Sony_Imagesoft)'),
  ('Q351926', 'Labyrinth: The Computer Game est un jeu vidéo d’aventure développé par Lucasfilm Games et publié par Activision sur Apple II, Commodore 64, Commodore 128 et MSX en 1986. Le jeu s’inspire du film Labyrinthe, réalisé par Jim Henson en 1986, mais propose un scénario différent. Le joueur y incarne un personnage qui doit résoudre des énigmes et éviter des dangers pour progresser dans un labyrinthe afin de retrouver et de détruire Jareth, le principal antagoniste du jeu, dans un délai de treize heures. Contrairement à la plupart des jeux d’aventure de l’époque, le joueur ne contrôle pas son personnage par l’intermédiaire d’une interface en ligne de commande.', 'https://fr.wikipedia.org/wiki/Labyrinth:_The_Computer_Game'),
  ('Q1665169', 'Uridium est un jeu vidéo développé par Graftgold et édité par Hewson Consultants, sorti en 1986 sur l''ordinateur 8-bit Commodore 64. Conçu et programmé par Andrew Braybrook, Uridium est un shoot them up à scrolling horizontal, plébiscité pour son concept original et sa réalisation poussée. Aux commandes du vaisseau Manta, le joueur survole des cuirassés de l''espace et doit détruire des cibles tout en évitant la flotte ennemie et les reliefs.

Le jeu a été porté sur les 8-bit Amstrad CPC et ZX Spectrum, le 16-bit Atari ST et les compatibles PC. Il est également disponible sur Nintendo Entertainment System, dans une version remaniée intitulée The Last Starfighter (1990), basée sur le film homonyme. Le jeu a connu une suite, Uridium 2, en 1993.', 'https://fr.wikipedia.org/wiki/Uridium'),
  ('Q3277744', 'Mahjong est un jeu vidéo de mah-jong sorti en 1983 sur Famicom, puis ressorti en 1986 sur Famicom Disk System. Le jeu a été développé et édité par Nintendo. Il est uniquement sorti au Japon.', 'https://fr.wikipedia.org/wiki/Mahjong_(jeu_vid%C3%A9o)'),
  ('Q3303109', 'The Maze of Galious est la suite du jeu Knightmare. Le héros Popolon a retrouvé sa dulcinée, la belle Aphrodite. Ils vont avoir un enfant. Galious enlève leur bébé avant sa naissance; Popolon et Aphrodite parcourent le château de Galious pour le délivrer.

The Maze of Galious est un jeu MSX 1, c''est un jeu de plate-forme sans défilement continu (« scrolling ») apparenté au genre porte-monstre-trésor.

Dans le château se trouvent dix portes menant à dix mondes; il faut éliminer le gardien de chaque monde pour pouvoir accéder au monde suivant.

Le château recèle de nombreux objets, des dieux et déesses qui aideront le joueur dans sa quête.', 'https://fr.wikipedia.org/wiki/The_Maze_of_Galious'),
  ('Q10856189', 'Nobunaga''s Ambition II est un jeu vidéo de stratégie au tour par tour développé et publié par Koei en 1988. Il fait suite à Nobunaga''s Ambition et se déroule au XVIe siècle dans le Japon médiéval. Il propose deux scénarios. Dans le premier, le Japon est partagés entre de nombreux seigneurs qui tentent chacun d''unifier le pays. Dans le second, qui se déroule quelques années avant le premier, le joueur fait face au seigneur Nobunaga qui contrôle déjà la moitié du pays. Le jeu se déroule au tour par tour sur une carte du Japon divisé en provinces sur laquelle le joueur contrôle des samourais auxquels sont rattachées des unités militaires. À chaque tour, le joueur peut réaliser différentes actions, comme transférer des hommes ou des ressources d''une province à une autre ou développer l''agriculture, le commerce ou les fortifications de sa région.', 'https://fr.wikipedia.org/wiki/Nobunaga%27s_Ambition_II'),
  ('Q99522908', 'RoboCop 3 — parfois surnommé RoboCop 3D — est un jeu vidéo d''action en 3D développé par Digital Image Design et édité par Ocean Software en 1992 sur Amiga, Atari ST et DOS. Le jeu est basé sur le film homonyme produit par Orion Pictures.

L''aventure reprend globalement la trame du film et propose des séquences de jeu variées avec des phases de tir à pied, des poursuites en voiture ou encore le survol de la ville en jetpack. Conçu par les créateurs de F29 Retaliator, Epic et plus tard TFX, le jeu est réputé pour son moteur 3D.', 'https://fr.wikipedia.org/wiki/RoboCop_3_(jeu_vid%C3%A9o)'),
  ('Q3440991', 'Romance of the Three Kingdoms est un jeu vidéo de grande stratégie développé par la société japonaise Koei. C''est le premier titre de la populaire série du même nom, qui en est rendu à sa quatorzième édition (2020).

Initialement sorti sur MSX au Japon en 1986, il fut adapté sur Famicom Disk System, Amiga, DOS et NES. Des versions Game Boy, Game Boy Color, Wonderswan et téléphone mobile ont également vu le jour. Selon la version, le contenu du jeu original subit parfois quelques variantes.

Inspiré du roman Histoire des Trois Royaumes écrit par Luo Guanzhong au XIVe siècle, ce jeu fait partie des séries de simulation historique développées par Koei telles que Nobunaga''s Ambition, Genghis Khan, Uncharted Waters et Operation Europe.', 'https://fr.wikipedia.org/wiki/Romance_of_the_Three_Kingdoms_(jeu_vid%C3%A9o)'),
  ('Q1523333', 'Sweet Home est un jeu vidéo de rôle développé et édité par Capcom en 1989 sur Famicom. Il est fondé sur le film d''horreur japonais du même nom et sorti la même année.', 'https://fr.wikipedia.org/wiki/Sweet_Home_(jeu_vid%C3%A9o)'),
  ('Q1886140', 'Wizardry: Proving Grounds of the Mad Overlord (aussi intitulé Sorcellerie dans sa première version française) est un jeu vidéo de type dungeon crawler conçu par Andrew Greenberg et Robert Woodhead. En 1980, Norman Sirotek créé Sir-Tech Software, Inc. et lance la bêta du jeu lors de la Boston Computer Convention avant de publier la version finale du jeu en 1981 sur Apple II. Au début du jeu, le joueur doit créer un groupe de six aventuriers auxquels il assigne un nom et une classe de personnage, comme guerrier, mage ou voleur. Il accède ensuite au donjon dont les environnements sont décrits par du texte et affiché dans une fenêtre graphique. Le jeu a été programmé par Robert Woodhead et Andrew Greenberg. Ces derniers ont utilisé leurs propres prénoms, en les inversant, pour baptiser les deux personnages principaux du jeu — le seigneur fou Trebor et le sorcier maléfique Werdna — que le joueur affronte au plus profond du donjon. Wizardry est l’une des premières adaptations en jeu vidéo du jeu de rôle Donjons et Dragons, et le premier jeu de ce genre à proposer des graphismes en couleur. Il est également le premier jeu vidéo de rôle proposant de contrôler un groupe de personnages.', 'https://fr.wikipedia.org/wiki/Wizardry:_Proving_Grounds_of_the_Mad_Overlord'),
  ('Q343608', 'Action 52 est un jeu vidéo de type party game sorti en 1991 sur NES et 1993 sur Mega Drive uniquement en Amérique du Nord. Une version SNES était prévue mais annulée. Le jeu a été développé par FarSight Studios (Mega Drive) et Active Enterprises (Nintendo Entertainment System) et édité par Active Enterprises. Au Japon, ce jeu est appelé Cheetahmen. Le jeu a été créé par Vince Perry, qui a eu l''idée du jeu en voyant son fils jouer à une multicartouche illégale taïwanaise composée de 40 jeux.', 'https://fr.wikipedia.org/wiki/Action_52'),
  ('Q1089369', 'The Adventures of Captain Comic est un jeu vidéo de plates-formes, développé par Michael Denio et édité par Color Dreams, sorti en 1989 sur Nintendo Entertainment System et sous DOS.

Il a pour suite Captain Comic II: Fractured Reality.', 'https://fr.wikipedia.org/wiki/The_Adventures_of_Captain_Comic'),
  ('Q940168', 'Chiller est un jeu vidéo créé par la firme Exidy en 1986.

Il est réputé pour être le jeu d''arcade le plus violent. Il s''utilise avec un light gun. Le but du jeu consiste à tirer sur tous les monstres et les innocents.', 'https://fr.wikipedia.org/wiki/Chiller'),
  ('Q591978', 'Fantastic Dizzy est un jeu vidéo d''aventure et de plate-forme sorti en 1991 et fonctionne sur Amiga CD32, Amiga, Atari ST, Commodore 64, GameGear, Master System, Mega Drive, Nintendo Entertainment System et PC. Le jeu a été développé par Philip Oliver et Andrew Oliver puis édité par Codemasters.

Le jeu a été renommé The Fantastic Adventures of Dizzy pour les versions commercialisées en dehors de l''Europe et de l''Australie. Il fait partie de la série Dizzy dont il est le septième opus.', 'https://fr.wikipedia.org/wiki/Fantastic_Dizzy'),
  ('Q126194', 'Le démineur (Minesweeper en anglais) est un jeu vidéo de réflexion dont le but est de localiser des mines cachées dans une grille représentant un champ de mines virtuel, avec pour seule indication le nombre de mines dans les zones adjacentes.

De nombreuses versions gratuites du Démineur existent, mais la plus connue est[réf. souhaitée] celle fournie par défaut avec le système d''exploitation Microsoft Windows[Lequel ?]. Cette version particulière, sans avoir inventé le concept, l''a popularisé, et la désignation « Démineur » identifie souvent cette version précise et non le principe général du jeu.[réf. souhaitée]', 'https://fr.wikipedia.org/wiki/D%C3%A9mineur_(genre_de_jeu_vid%C3%A9o)'),
  ('Q7339401', 'Road Runner est un jeu vidéo de course développé et édité par Atari Games, sorti en 1985 sur borne d''arcade, DOS, Amstrad CPC, Atari ST, Commodore 64, ZX Spectrum, Atari 2600 et NES. Il est basé sur les courts-métrages Bip Bip et Coyote.', 'https://fr.wikipedia.org/wiki/Road_Runner_(jeu_vid%C3%A9o)'),
  ('Q887292', 'Somari the Adventurer est un jeu vidéo de plates-formes à défilement latéral sorti en 1994 sur Famicom. Cette contrefaçon non autorisée, dérivée du jeu vidéo Sonic the Hedgehog (1991) de Sega Genesis/Mega Drive, est principalement distribué en Asie, en Russie, en Europe orientale et en d’autres contrées où se diffusaient des cartouches pirates pour NES et Famicom. À l’instar de l’œuvre originale, le joueur se doit de combattre le scientiste dément, le Dr. Robotnik, dont le dessein scélérat vise à métamorphoser la population animale de l’île fictive du Sud en une armée de robots maléfiques. Toutefois, à la différence du modèle, ce jeu substitue au hérisson Sonic la figure emblématique de Nintendo, Mario, en qualité de protagoniste.', 'https://fr.wikipedia.org/wiki/Somari'),
  ('Q2405612', 'Spiritual Warfare est un jeu vidéo de rôle sorti en 1992 sur PC (DOS), Game Boy et Nintendo Entertainment System; puis, en 1994 sur Mega Drive. Le jeu a été développé et édité par Wisdom Tree, une société de développement et d''édition de jeux vidéo chrétiens.

Spiritual Warfare est profondément inspiré par The Legend of Zelda.', 'https://fr.wikipedia.org/wiki/Spiritual_Warfare'),
  ('Q853143', 'Super Mario World est un jeu vidéo de plates-formes développé par Nintendo EAD et édité par Nintendo pour le Super Nintendo Entertainment System (SNES). Il est sorti au Japon en 1990, en Amérique du Nord en 1991, et en Europe ainsi qu''en Australie en 1992. Le joueur contrôle Mario dans sa quête pour sauver Princesse Peach et Dinosaur Land de l''antagoniste de la série, Bowser et les Koopalings. Le gameplay est similaire à celui des précédents jeux Super Mario: les joueurs contrôlent Mario à travers une série de niveaux dont le but est d''atteindre le poteau d''arrivée à la fin.

Le jeu a été développé par Nintendo Entertainment Analysis & Development, dirigé par le directeur Takashi Tezuka et le producteur et créateur de la série Shigeru Miyamoto. C''est le premier jeu Mario pour la SNES et il a été conçu pour exploiter au maximum les caractéristiques techniques de la console. L''équipe de développement avait plus de liberté par rapport aux épisodes de la série pour la Nintendo Entertainment System. Yoshi a été conceptualisé lors du développement des jeux NES, mais n''a été utilisé qu''à partir de Super Mario World en raison des limitations matérielles.', 'https://fr.wikipedia.org/wiki/Super_Mario_World'),
  ('Q1276594', 'Pang, appelé Pomping World au Japon, Buster Bros. en Amérique du Nord, est un jeu vidéo d''action-réflexion développé et commercialisé par Mitchell Corporation, sorti en 1989 sur système d''arcade Mitchell. Il a été converti sur divers micro-ordinateurs et consoles de jeu.

Une suite du jeu, appelée Super Pang et issue du même studio de développement, est sortie l''année suivante.', 'https://fr.wikipedia.org/wiki/Pang'),
  ('Q2257053', 'Super Pang, appelé Super Buster Bros. en Amérique du Nord, est un jeu vidéo d''action-réflexion développé et commercialisé par Mitchell Corporation, sorti en 1990 sur système d''arcade Mitchell. Il a été adapté en 1992 sur Super Nintendo, puis réédité en compilation sur plate-forme Sony en 1997 et 2006.

Super Pang est la suite de Pang.', 'https://fr.wikipedia.org/wiki/Super_Pang'),
  ('Q2829467', 'Aladdin est un jeu vidéo de plate-forme sorti en 1993 sur Super NES et sur Game Boy Advance, à l''occasion de la sortie du dessin animé Aladdin produit par Walt Disney Pictures la même année.

Il ne faut pas le confondre avec les deux autres jeux vidéo du même nom, eux aussi adaptés du dessin animé, que sont Aladdin de Virgin sur Mega Drive et Aladdin de Sega sur Master System.', 'https://fr.wikipedia.org/wiki/Aladdin_(Capcom)'),
  ('Q3141541', 'Bomberman ''94 est un jeu vidéo d''action développé par Hudson Soft, initialement sorti en 1993 sur PC-Engine et adapté en 1994 sur Mega Drive sous le titre Mega Bomberman. Le jeu fait partie de la série Bomberman.', 'https://fr.wikipedia.org/wiki/Bomberman_%2794'),
  ('Q2910422', 'Boogerman: A Pick and Flick Adventure est un jeu de plateforme développé et publié par Interplay Entertainment et sorti sur Mega Drive et Super Nintendo en 1995. En 2008, une réédition intègre les jeux de la console virtuelle (Wii).

Le joueur dirige Boogerman, le personnage principal. Balayeur pour un laboratoire, Boogerman doit entrer dans une dimension parallèle d''ordures et de saleté pour sauver le monde.

La particularité de Boogerman est d''être un jeu qui plonge le joueur dans un monde dégoûtant. Le héros, dont le nom signifie "crotte de nez man" doit se battre contre des créatures à forte acné, fouiller des tas d''ordures à la recherche de bonus de gaz ou autres.', 'https://fr.wikipedia.org/wiki/Boogerman:_A_Pick_and_Flick_Adventure'),
  ('Q1368099', 'Super Probotector: Alien Rebels, ou Contra III: The Alien Wars en Amérique du Nord, ou bien Contra Spirits au Japon, est un jeu vidéo d''action dit de type run and gun développé et édité par Konami sur Super Nintendo en 1992.

Il est porté sur Game Boy en 1994, et, est renommé Probotector 2 en Europe et Contra: The Alien Wars en Amérique du Nord (le titre étant resté le même au Japon). Puis sur Game Boy Advance en 2003 sous le titre Contra Advance: The Alien Wars EX.', 'https://fr.wikipedia.org/wiki/Super_Probotector:_Alien_Rebels'),
  ('Q518987', 'Donkey Kong Country (DKC, Super Donkey Kong au Japon) est un jeu vidéo de plates-formes développé par Rare et édité par Nintendo à partir de novembre 1994 sur Super Nintendo. Premier jeu de la série Donkey Kong Country, il met en scène les personnages de Donkey Kong et de Diddy Kong. Une suite est proposée sur Game Boy en juin 1995 sous le titre Donkey Kong Land. Il est porté sur Game Boy Color en 2000, puis en 2003 sur Game Boy Advance. Le jeu est disponible dans sa version originale en téléchargement sur la console virtuelle de la Wii depuis décembre 2006, celle de la Wii U en 2014 et celle de la New Nintendo 3DS en 2016.Il est notamment disponible sur le service Online de la Nintendo Switch et Nintendo Switch 2 depuis 2020.', 'https://fr.wikipedia.org/wiki/Donkey_Kong_Country_(jeu_vid%C3%A9o)'),
  ('Q2358727', 'Dragon: The Bruce Lee Story est un jeu de combat développé par Avalon Interactive et édité par Acclaim, sorti en 1993 sur Mega Drive, Super Nintendo, Jaguar, Game Gear et Master System.

Il est basé sur le film Dragon, l''histoire de Bruce Lee de Rob Cohen sorti en 1993, qui raconte d''une manière romancée la vie de Bruce Lee.', 'https://fr.wikipedia.org/wiki/Dragon:_The_Bruce_Lee_Story_(jeu_vid%C3%A9o)'),
  ('Q727139', 'Earthworm Jim est un jeu vidéo de plates-formes de David Perry et de Doug TenNapel (concept original) pour Virgin Interactive, sorti sur Mega Drive, Super Nintendo, Game Gear, Game Boy, Mega-CD et PC en 1994.

Le jeu est très représentatif des jeux de David Perry sur consoles 16-bits (voir aussi Global Gladiators, Cool Spot et Aladdin): l''animation est extrêmement détaillée et réussie et le graphisme coloré et recherché. Il s''agit du seul jeu de David Perry sur les consoles de cette génération qui ne soit pas tiré d''une licence déjà existante.

Le jeu a été remastérisé sur PlayStation 3, Xbox 360 et Windows Phone sous le titre Earthworm Jim HD.', 'https://fr.wikipedia.org/wiki/Earthworm_Jim_(jeu_vid%C3%A9o)'),
  ('Q2601047', 'Final Fight 3, sorti au Japon sous le titre Final Fight Tough, est un jeu vidéo à défilement horizontal de type beat them all édité et développé par Capcom. Le jeu est sorti sur Super Nintendo le 22 décembre 1995 au Japon et le 13 mars 1996 en France.

Le jeu revient avec le personnage principal Guy accompagné de Mike Haggar et introduit deux nouveaux personnages, Lucia et Dean. Comme dans les précédents jeux Final Fight, chaque personnage possède son propre ensemble de mouvements, de techniques et de capacités propres. Comme dans Final Fight 2, le jeu peut être joué seul ou avec un second joueur, avec un mode de jeu supplémentaire qui permet à un seul joueur d''être accompagné par un partenaire contrôlé par l''ordinateur.', 'https://fr.wikipedia.org/wiki/Final_Fight_3'),
  ('Q1074369', 'Fatal Fury Special est un jeu vidéo de combat 2D développé et édité par SNK en 1993 sur les systèmes Neo-Geo MVS, Neo-Geo AES et Neo-Geo CD (NGM / NGH 058). Il fut adapté sur FM Towns, Mega-CD, PC Engine, Super Nintendo, X68000, Game Gear & Xbox Live Arcade.

Fatal Fury Special est le troisième épisode de la série Fatal Fury.', 'https://fr.wikipedia.org/wiki/Fatal_Fury_Special'),
  ('Q2747904', 'Mighty Morphin Power Rangers est un jeu vidéo de combat sorti en 1994 sur Mega Drive, Super Nintendo, Game Boy et Game Gear. Le jeu a été développé par Bandai et édité par Sega.', 'https://fr.wikipedia.org/wiki/Mighty_Morphin_Power_Rangers_(jeu_vid%C3%A9o)'),
  ('Q150294', 'Mortal Kombat (communément abrégé en MK) est un jeu vidéo de Midway Manufacturing Company sorti sur borne d''arcade en 1992, célèbre pour sa violence, sa brutalité et son côté gore.

L''histoire se centre sur un tournoi du nom de Mortal Kombat organisé par le maléfique sorcier Shang Tsung.

Le jeu a connu un très fort succès ce qui a donné suite à un second volet, Mortal Kombat II en 1993.', 'https://fr.wikipedia.org/wiki/Mortal_Kombat_(jeu_vid%C3%A9o,_1992)'),
  ('Q3392932', 'Pocahontas est un jeu vidéo de plates-formes sorti en 1996 sur Game Boy et Mega Drive. Le jeu a été développé par Funcom et édité par Buena Vista Games.

Il s''agit de l''adaptation du film Pocahontas: Une légende indienne des studios Disney, sorti en 1995.', 'https://fr.wikipedia.org/wiki/Pocahontas_(jeu_vid%C3%A9o)'),
  ('Q5575485', 'Street Fighter II'': Champion Edition est un jeu de combat en un-contre-un développé et édité par Capcom sur le système d''arcade CP System, et publié en mars 1992. C''est la première amélioration du jeu Street Fighter II, depuis la mouture originale sous-titrée The World Warrior, sortie un an auparavant. Il a été adapté sur de nombreuses plates-formes de jeu, parmi lesquelles la Sega Mega Drive.', 'https://fr.wikipedia.org/wiki/Street_Fighter_II%27:_Champion_Edition'),
  ('Q2638825', 'Shinobi III: Return of the Ninja Master, titre original japonais The Super Shinobi II, est un jeu vidéo d''action développé par Sega AM7 et édité par Sega, sorti en 1993 sur borne d''arcade et Mega Drive. C''est la suite directe de The Revenge of Shinobi.', 'https://fr.wikipedia.org/wiki/Shinobi_III:_Return_of_the_Ninja_Master'),
  ('Q4051517', 'Tiny Toon Adventures: Babs'' Big Break était le premier jeu basé sur Les Tiny Toons à être sorti sur la console portable Game Boy de Nintendo. Il est sorti en 1992 et a été développé et édité par Konami.', 'https://fr.wikipedia.org/wiki/Tiny_Toon_Adventures:_Babs%27_Big_Break'),
  ('Q4020896', 'World Heroes 2 est un jeu vidéo de combat développé par ADK et édité par SNK en 1993 sur borne d''arcade Neo-Geo MVS et sur console Neo-Geo AES, puis en 1995 sur Neo-Geo CD (NGM 057). Le jeu a été porté sur les consoles PC Engine, Super Famicom, PlayStation 2 et Wii console virtuelle. C''est la suite de World Heroes sorti en 1992 et le deuxième épisode de la série World Heroes.', 'https://fr.wikipedia.org/wiki/World_Heroes_2'),
  ('Q2892913', 'Beat ''Em and Eat ''Em est un jeu vidéo pornographique conçu par Mystique pour l''Atari 2600. Il est sorti le 13 octobre 1982.

Bien que le jeu se soit mal vendu à sa sortie, son concept hors du commun l''a rendu "culte" et notoire dans la communauté des gamers. On le considère souvent comme l''un des plus mauvais jeux vidéo jamais créés, une réputation qu''il partage avec d''autres créations de Mystique, dont Custer''s Revenge.', 'https://fr.wikipedia.org/wiki/Beat_%27Em_and_Eat_%27Em'),
  ('Q1060323', 'The Legend of Zelda: Link''s Awakening (ou simplement Link''s Awakening) est un jeu d''action-aventure développé et édité par Nintendo le 6 juin 1993 au Japon sur Game Boy, puis en août 1993 aux États-Unis et en décembre 1993 en Europe. Il s''agit du quatrième épisode de la série The Legend of Zelda.

Link rentre en bateau vers Hyrule, mais une tempête coule son embarcation. Il s''échoue sur l''île Cocolint, où il doit trouver le Poisson-rêve, le seul être qui puisse l''aider à partir de cette île. Il s''avère que l''île et ses habitants ne sont qu''une illusion produite par le Poisson-rêve, endormi et enfermé dans un œuf géant posé sur le mont Tamaranch. Link doit le réveiller pour mettre fin à ces cauchemars. Durant le jeu, Link se déplace dans une carte du monde affichée en vue de dessus, mais explore également plusieurs donjons labyrinthiques pour la plupart souterrains afin de trouver les objets lui permettant d''avancer dans sa quête, qui consiste à trouver les huit instruments de musique des sirènes, qui vont lui permettre de réveiller le Poisson-rêve. La princesse Zelda, Ganon et la Triforce ne figurent pas dans cet épisode.', 'https://fr.wikipedia.org/wiki/The_Legend_of_Zelda:_Link%27s_Awakening'),
  ('Q474798', 'The Legend of Zelda: The Minish Cap (litt.La Légende de Zelda: Le Chapeau mystérieux) souvent abrégé en Minish Cap, est un jeu d''action-aventure développé par Capcom et Flagship et édité par Nintendo. Il sort sur Game Boy Advance le 4 novembre 2004 au Japon, le 12 novembre 2004 en Europe, et l''année suivante le 10 janvier 2005 en Amérique du Nord et le 7 avril 2005 en Australasie. Il s''agit du douzième opus de la franchise The Legend of Zelda et le troisième à sortir sur cette console.

Préquelle directe de The Legend of Zelda: Four Swords sorti en 2002 sur Game Boy Advance, le jeu met en scène Link, le petit-fils du forgeron du royaume d''Hyrule. Il cherche à libérer Zelda, son amie d''enfance et princesse du royaume, d''une malédiction infligée par le sorcier maléfique Vaati. Accompagné dans sa quête par le Minish Exelo, un être microscopique qui lui confère le pouvoir de rapetisser et de grandir à loisir, Link cherche alors à reforger la lame sacrée Minish pour briser le sort lancé par Vaati et sauver son amie.', 'https://fr.wikipedia.org/wiki/The_Legend_of_Zelda:_The_Minish_Cap'),
  ('Q370055', 'The Legend of Zelda: A Link to the Past (litt.La Légende de Zelda: La Triforce des dieux, ou simplement A Link to the Past, ALttP, et parfois Zelda III) est un jeu d''action-aventure développé et édité par Nintendo le 21 novembre 1991 au Japon sur Super Nintendo, puis en avril 1992 aux États-Unis et en septembre 1992 en Europe. Il s''agit du troisième épisode de la série The Legend of Zelda.

Dans un univers de fantasy appelé Hyrule, Link doit trouver les trois pendentifs magiques afin d''obtenir l''épée Excalibur, puis délivrer les sept descendantes des sept sages (dont la princesse Zelda) et vaincre Ganon, dans le but de récupérer la Triforce et ramener la paix dans le royaume. Durant le jeu, Link se déplace dans une carte du monde affichée en vue de dessus, mais explore également plusieurs donjons labyrinthiques souterrains. Le royaume d''Hyrule est habité par de nombreux monstres que Link doit combattre, et recèle de nombreux secrets et énigmes à résoudre, ce qui permet à Link de découvrir des objets utiles à son avancement dans la quête ou des armes améliorant ses capacités. L''exploration et la découverte de secrets sont le cœur de l''expérience de jeu.', 'https://fr.wikipedia.org/wiki/The_Legend_of_Zelda:_A_Link_to_the_Past');

update public.game g
set summary = i.summary, summary_source = i.source
from import_summary i
where g.wikidata_id = i.wikidata_id
  and g.summary is null;

drop table import_summary;
